}
RESULTS = Path("benchmarks/analysis/results")


@dataclass(frozen=True)
class Probe:
    phase: Phase
    offset: int
    arm: Arm

    @property
    def key(self) -> str:
        return f"{self.phase}:{self.offset}:{self.arm}"


def probe_schedule() -> tuple[Probe, ...]:
    phases: tuple[Phase, ...] = ("warmup", "ordinary", "profile")
    order: tuple[tuple[int, Arm], ...] = (
        (7, "math"),
        (7, "efficient"),
        (18, "efficient"),
        (18, "math"),
    )
    return tuple(Probe(phase, offset, arm) for phase in phases for offset, arm in order)


def admit_sources(path: Path, sha256: str) -> dict[str, str]:
    saved = cast(dict[str, str], read_object(path))
    if (
        digest(path) != sha256
        or set(saved) != {str(item) for item in SOURCES}
        or any(digest(ROOT / name) != sha for name, sha in saved.items())
    ):
        raise ValueError("Every exact five-file shape identity is required")
    return saved


def source_paths() -> dict[str, Path]:
    return {**latency.source_paths(), **{str(path): ROOT / path for path in SOURCES}}


def admit_history(
    reference: BenchmarkCycle,
    cuda: BenchmarkCycle,
    cases: tuple[EvaluationCase, ...],
) -> dict[str, str]:
    pins = {str(RESULTS / name): sha for name, sha in HISTORY_PINS.items()}
    if any(digest(ROOT / name) != sha for name, sha in pins.items()):
        raise ValueError("Independently reviewed B1 history changed")
    declaration = ROOT / RESULTS / "cuda-latency-source-declaration-20261005.json"
    hashes = latency.admit_sources(declaration, HISTORY_PINS[declaration.name])
    pins.update(latency.admit_screens(reference, cuda, cases))
    confirm = ROOT / RESULTS / "cuda-latency-confirm-b1.json"
    pins.update(
        latency.admit_confirmation(
            confirm,
            HISTORY_PINS[confirm.name],
            wall_sha256=HISTORY_PINS["cuda-latency-confirm-b1.wall.json"],
            batch_size=1,
            source_hashes=hashes,
            reference=reference,
            cuda=cuda,
            cases=cases,
        )
    )
    timing = ROOT / RESULTS / "cuda-latency-timing-b1.json"
    saved = read_object(timing)
    latency.require_parent(timing)
    if (
        saved.get("mode") != "timing"
        or saved.get("batch_size") != 1
        or saved.get("completed") is not True
        or saved.get("quality_passed") is not True
        or saved.get("case_ids") != [case.id for case in cases]
        or saved.get("input_sha256") != INPUT_SHA
        or saved.get("new_source_hashes") != hashes
        or any(cast(dict[str, list[str]], saved["unknown_case_ids"]).values())
    ):
        raise ValueError("Prior timing must retain complete canonical B1 outcomes")
    chronological = cast(list[dict[str, object]], saved["cycles"])
    expected = ["warmup_math", "warmup_efficient"] + [
        f"pair{pair}_{arm}"
        for pair in range(6)
        for arm in (("math", "efficient") if pair % 2 == 0 else ("efficient", "math"))
    ]
    if [item.get("key") for item in chronological] != expected:
        raise ValueError("All prior six paired cycles are required in order")
    reconstructed = []
    for item in chronological:
        cycle = latency.read_cycle(item["cycle"], cases)
        if not check_cycle(cycle, reference, cuda)[0]:
            raise ValueError("Prior timing violates the unchanged numerical gates")
        reconstructed.append(cycle)
    for start in range(0, 14, 2):
        if not compare_cycles(
            (reconstructed[start],), (reconstructed[start + 1],), QualityGate()
        ).passed:
            raise ValueError("Prior timing paired quality failed")
    current = latency.source_paths()
    if saved["source_sha256"] != {name: digest(path) for name, path in current.items()}:
        raise ValueError("Prior timing execution sources changed")
    archive = cast(dict[str, str], saved["source_archive"])
    archive_path = timing.with_suffix(f".sources-{archive['sha256'][:16]}.json")
    if digest(archive_path) != archive["sha256"]:
        raise ValueError("Prior timing source archive changed")
    pins[str(archive_path.relative_to(ROOT))] = archive["sha256"]
    return pins


def trace_metadata(path: Path) -> dict[str, object]:
    """Archive native bytes; interpret the observed schema independently later."""
    return {
        "path": str(path),
        "sha256": digest(path),
        "bytes": path.stat().st_size,
        "schema_interpreted": False,
        "scope": "Raw Chrome evidence; launch geometry/linkage/clock domains unknown",
    }


def require_finite_timing(cycle: BenchmarkCycle) -> None:
    if (
        not math.isfinite(cycle.latency_ms)
        or cycle.latency_ms <= 0
        or any(
            not math.isfinite(row.latency_ms) or row.latency_ms < 0
            for row in cycle.rows
        )
    ):
        raise ValueError("Completed intervals must be finite and nonnegative")


def math_dispatch_gate(evidence: dict[str, object]) -> bool:
    operators = cast(Sequence[dict[str, object]], evidence.get("operators", ()))
    counts: dict[str, int] = {}
    for event in operators:
        name, count = event.get("name"), event.get("count")
        if not isinstance(name, str) or type(count) is not int or count < 0:
            return False
        counts[name] = counts.get(name, 0) + count
    return counts.get("aten::_scaled_dot_product_attention_math") == 28 and not any(
        count > 0
        and any(
            other in name
            for other in ("efficient_attention", "flash_attention", "cudnn_attention")
        )
        for name, count in counts.items()
    )


def profile_one(
    scorer: Scorer,
    case: EvaluationCase,
    *,
    name: str,
    trace_path: Path,
    retain: Callable[[BenchmarkCycle, dict[str, object]], None],
) -> dict[str, object]:
    """One exported capture; retain output even if cleanup/export later fails."""
    if trace_path.exists():
        raise FileExistsError("A native trace must never overwrite prior evidence")
    observer = Dispatch()
    cycle: BenchmarkCycle | None = None
    try:
        torch.cuda.synchronize()
        with (
            warnings.catch_warnings(record=True) as caught,
            profile(
                activities=[ProfilerActivity.CPU, ProfilerActivity.CUDA],
                record_shapes=True,
            ) as profiler,
            observer,
        ):
            with record_function(name):
                cycle = _run(
                    BenchmarkEngine(
                        name,
                        Model(scorer, model_id=MODEL_ID),
                        batch_size=1,
                        synchronize=torch.cuda.synchronize,
                    ),
                    (case,),
                )
            torch.cuda.synchronize()
        observed: dict[str, object] = {
            "case_ids": [case.id],
            "dispatch": observer.events,
            "operators": [
                {
                    "name": event.key,
                    "count": event.count,
                    "shapes": event.input_shapes,
                    "self_cpu_time_us": event.self_cpu_time_total,
                    "self_device_time_us": event.self_device_time_total,
                }
                for event in profiler.key_averages(group_by_input_shape=True)
            ],
            "cuda_kernel_events": [
                {
                    "name": event.name,
                    "duration_us": event.time_range.elapsed_us(),
                    "device_index": event.device_index,
                }
                for event in profiler.events()
                if event.device_type == DeviceType.CUDA
            ],
            "warnings": [str(item.message) for item in caught],
            "timing_scope": "Intrusive one-call profile; no ordinary-speed claim",
            "cleanup_completed": True,
        }
    except Exception as error:
        if cycle is not None:
            retain(
                cycle,
                {
                    "cleanup_completed": False,
                    "error": str(error),
                    "dispatch": observer.events,
                },
            )
        raise
    observed["cuda_kernel_names_available"] = bool(observed["cuda_kernel_events"])
    retain(cycle, observed)
    if trace_path.exists():
        raise FileExistsError("A native trace must never overwrite prior evidence")
    try:
        profiler.export_chrome_trace(str(trace_path))
    except Exception as error:
        observed["chrome_export_error"] = f"{type(error).__name__}: {error}"
        if trace_path.exists():
            observed["chrome"] = trace_metadata(trace_path)
        raise
    observed["chrome"] = trace_metadata(trace_path)
    if trace_path.stat().st_size <= 0:
        raise ValueError("Native Chrome export produced no bytes")
    return observed


def study(model: Path, output: Path, *, sources: Path, sources_sha256: str) -> bool:
    started = time.perf_counter_ns()
    active_phase: Phase | None = None
    phase_starts: dict[Phase, int] = {}
    phase_wall_ms: dict[str, float] = {}
    selection_ids = {offset: case_id for offset, case_id, _ in CASE_SELECTION}
    pending = {probe.key: [selection_ids[probe.offset]] for probe in probe_schedule()}
    payload: dict[str, object] = {
        "completed": False,
        "quality_passed": False,
        "dispatch_passed": False,
        "accepted": False,
        "cycles": [],
        "profiles": {},
        "unknown_case_ids": pending,
        "phase_wall_ms": phase_wall_ms,
        "selection": [list(item) for item in CASE_SELECTION],
        "expected_rows": 12,
        "scope": "Exploratory real B1 L192/L197; content/order/governor confounded",
        "gate": asdict(QualityGate()),
        "limits": [
            "Missing native launch fields unknown",
            "Profile durations do not establish ordinary speed or critical path",
            "No routing threshold, synthetic input or production promotion",
        ],
    }

    def write() -> None:
        output.write_text(json.dumps(payload, allow_nan=False) + "\n")

    with output.open("x") as handle:
        handle.write(json.dumps(payload, allow_nan=False) + "\n")
    try:
        new_hashes = admit_sources(sources, sources_sha256)
        manifest = ROOT / RESULTS / "cuda-transfer-manifest-v2-20261005.json"
        if digest(manifest) != latency.MANIFEST_SHA:
            raise ValueError("Original 44-asset manifest changed")
        admission = admit(manifest)
        control = ROOT / RESULTS / "cuda-fp32-b1.json"
        if digest(control.with_suffix(".wall.json")) != latency.CONTROL_WALL_SHA:
            raise ValueError("Original control parent identity changed")
        pinned = admit_control(control, latency.CONTROL_SHA, admission, batch_size=1)
        if any(
            (
                sdpa_attention._is_torch_mps_available,
                sdpa_attention._is_torch_xpu_available,
                sdpa_attention._is_torch_npu_available,
            )
        ):
            raise ValueError("Frozen Linux CUDA HF availability required")
        frozen = freeze_sources(source_paths(), output)
        payload.update(
            admission=admission,
            control=pinned,
            new_source_hashes=new_hashes,
            source_declaration_sha256=sources_sha256,
            source_sha256=frozen.hashes(),
            source_archive=frozen.archive(),
        )
        cases = tuple(
            case_from_dict(decode_json(line))
            for line in (ROOT / DATA).read_text().splitlines()
        )
        if len(cases) != 77 or _input_digest(cases) != INPUT_SHA:
            raise ValueError("All original ordered77 cases required")
        for offset, case_id, _ in CASE_SELECTION:
            if cases[offset].id != case_id:
                raise ValueError("Fixed real case identity changed")
        write()
        artifact = load_artifact(model, 512)
        if artifact.model_id != MODEL_ID:
            raise ValueError("Original checkpoint identity changed")
        inputs = latency.ReferenceInput(
            artifact.model_id,
            KaiEncoder.from_artifact(artifact, max_length=512, token_cache_size=0),
        )
        reference = read_reference(
            ROOT / REFERENCE, cases, inputs, dataset_sha256=DATA_SHA
        )
        cuda = control_cycle(control, cases)
        if not compare_cycles((reference,), (cuda,), QualityGate()).passed:
            raise ValueError("Original CUDA/CPU control quality changed")
        for offset, _, length in CASE_SELECTION:
            if len(inputs.encode_request(cases[offset].request).ids) != length:
                raise ValueError("Fixed exact token length changed")
        history = admit_history(reference, cuda, cases)
        payload["history_sha256"] = history
        traces = output.with_suffix(".trace")
        traces.mkdir()

        def verify() -> None:
            if (
                any(digest(Path(item.path)) != item.sha256 for item in frozen.files)
                or any(digest(ROOT / name) != sha for name, sha in history.items())
                or digest(control) != latency.CONTROL_SHA
                or digest(control.with_suffix(".wall.json")) != latency.CONTROL_WALL_SHA
            ):
                raise ValueError("Consumed source/history/control changed")

        payload["occupancy_before_load"] = occupancy()
        torch.set_num_threads(8)
        base = KaiScorer.from_directory(
            model, device="cpu", max_length=512, token_cache_size=0
        )
        read_reference(ROOT / REFERENCE, cases, base, dataset_sha256=DATA_SHA)
        payload["occupancy_before_allocation"] = occupancy()
        with ieee_precision():
            base.device = torch.device("cuda:0")
            cast(nn.Module, base.backbone).to(base.device)
            base.head.to(base.device)
            require_fp32(base)
            scorers: dict[Arm, Scorer] = {
                "math": FP32Scorer(base),
                "efficient": efficient_scorer(base),
            }
            previous: dict[tuple[Phase, int, Arm], BenchmarkCycle] = {}
            profiles = cast(dict[str, dict[str, object]], payload["profiles"])
            completed = cast(list[dict[str, object]], payload["cycles"])
            for probe in probe_schedule():
                active_phase = probe.phase
                phase_starts.setdefault(probe.phase, time.perf_counter_ns())
                verify()
                snapshot = occupancy(own_pid=os.getpid())
                case = cases[probe.offset]
                payload["phase"] = probe.key

                def retain(
                    cycle: BenchmarkCycle,
                    observed: dict[str, object],
                    *,
                    probe: Probe = probe,
                    case: EvaluationCase = case,
                    snapshot: dict[str, object] = snapshot,
                ) -> None:
                    completed.append(
                        {
                            "key": probe.key,
                            "cycle": latency.cycle_data(cycle),
                            "ownership": snapshot,
                        }
                    )
                    if observed:
                        profiles[probe.key] = observed
                    pending[probe.key] = (
                        [] if case.id in {row.id for row in cycle.rows} else [case.id]
                    )
                    write()

                if probe.phase == "profile":
                    length = len(base.encode_request(case.request).ids)
                    observed = profile_one(
                        scorers[probe.arm],
                        case,
                        name=f"{case.id}:{probe.arm}:L{length}",
                        trace_path=traces / f"{case.id}-{probe.arm}.json",
                        retain=retain,
                    )
                    profiles[probe.key] = observed
                    cycle = latency.read_cycle(completed[-1]["cycle"], (case,))
                    if probe.arm == "efficient" and not efficient_dispatch_gate(
                        observed, batch_size=1, length=length
                    ):
                        raise ValueError("Reviewed efficient dispatch unsupported")
                    if probe.arm == "math" and not math_dispatch_gate(observed):
                        raise ValueError("Profiled comparator is not the math backend")
                else:
                    cycle = _run(
                        BenchmarkEngine(
                            probe.arm,
                            Model(scorers[probe.arm], MODEL_ID),
                            batch_size=1,
                            synchronize=torch.cuda.synchronize,
                        ),
                        (case,),
                    )
                    retain(cycle, {})
                require_finite_timing(cycle)
                passed, drift = check_cycle(
                    cycle,
                    replace(reference, rows=(reference.rows[probe.offset],)),
                    replace(cuda, rows=(cuda.rows[probe.offset],)),
                )
                completed[-1]["drift"] = drift
                write()
                if not passed:
                    raise ValueError(
                        "Real-shape output fails unchanged numerical gates"
                    )
                previous[probe.phase, probe.offset, probe.arm] = cycle
                other = previous.get(
                    (
                        probe.phase,
                        probe.offset,
                        "efficient" if probe.arm == "math" else "math",
                    )
                )
                if (
                    other is not None
                    and not compare_cycles((other,), (cycle,), QualityGate()).passed
                ):
                    raise ValueError("Real-shape paired quality failed")
                phase_wall_ms[probe.phase] = (
                    time.perf_counter_ns() - phase_starts[probe.phase]
                ) / 1e6
                write()
            require_fp32(base)
            payload["occupancy_after"] = occupancy(own_pid=os.getpid())
        verify()
        if (
            [row["key"] for row in completed] != [p.key for p in probe_schedule()]
            or any(pending.values())
            or set(profiles)
            != {p.key for p in probe_schedule() if p.phase == "profile"}
        ):
            raise ValueError("Every fixed output and capture must be retained")
        for observed in profiles.values():
            chrome = cast(dict[str, object], observed["chrome"])
            trace = Path(cast(str, chrome["path"]))
            if trace_metadata(trace) != chrome:
                raise ValueError("Native trace bytes changed after export")
        if (
            admit(manifest) != admission
            or admit_sources(sources, sources_sha256) != new_hashes
        ):
            raise ValueError("Final immutable admission changed")
        payload.update(
            completed=True,
            quality_passed=True,
            dispatch_passed=True,
            phase="completed",
            worker_body_wall_ms=(time.perf_counter_ns() - started) / 1e6,
        )
        write()
        return True
    except Exception as error:
        for phase, phase_started in phase_starts.items():
            if phase == active_phase or phase not in phase_wall_ms:
                phase_wall_ms[phase] = (time.perf_counter_ns() - phase_started) / 1e6
        payload["worker_body_wall_ms"] = (time.perf_counter_ns() - started) / 1e6
        payload.update(
            completed=False,
            quality_passed=False,
            dispatch_passed=False,
            accepted=False,
            phase="failed",
            error=f"{type(error).__name__}: {error}",
        )
        write()
        return False

"""Capture an actual maintained gate input, then detach it through host storage."""

from __future__ import annotations

import hashlib
import time
from collections.abc import Callable, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from typing import TYPE_CHECKING, Protocol, cast

import numpy as np

from wyat.benchmark import BenchmarkCycle, BenchmarkEngine, _run
from wyat.core import Model
from wyat.evaluation import EvaluationCase

if TYPE_CHECKING:
    import mlx.core as mx

    from wyat.backends.kai.mlx import MLXKaiScorer
    from wyat.backends.kai.prefix import PrefixScorer


@dataclass(frozen=True, slots=True)
class CapturedInput:
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]]
    cycle: BenchmarkCycle
    copy_elapsed_ms: float

    def metadata(self) -> dict[str, object]:
        return {
            "copy_materialization_elapsed_ms": self.copy_elapsed_ms,
            "shape": list(self.values.shape),
            "dtype": str(self.values.dtype),
            "host_strides_bytes": list(self.values.strides),
            "sha256": hashlib.sha256(self.values.tobytes()).hexdigest(),
            "nbytes": self.values.nbytes,
        }


class CaptureFailure(ValueError):
    def __init__(self, message: str, cycle: BenchmarkCycle) -> None:
        super().__init__(message)
        self.cycle = cycle


class CaptureProjection:
    """Call the unchanged projection and observe its exact argument once."""

    def __init__(self, original: Callable[[mx.array], mx.array]) -> None:
        self.original = original
        self.inputs: list[mx.array] = []

    def __call__(self, value: mx.array) -> mx.array:
        self.inputs.append(value)
        return self.original(value)


class ProjectionOwner(Protocol):
    gate_proj: Callable[[mx.array], mx.array]


@contextmanager
def observe_projection(owner: ProjectionOwner) -> Iterator[CaptureProjection]:
    original = owner.gate_proj
    observer = CaptureProjection(original)
    owner.gate_proj = observer
    try:
        yield observer
    finally:
        owner.gate_proj = original


def detached_float32(
    value: mx.array,
) -> np.ndarray[tuple[int, int], np.dtype[np.float32]]:
    """A host-owned copy cannot retain a lazy model graph or checkpoint owner."""
    import mlx.core as mx

    if value.dtype != mx.float32 or len(value.shape) not in (2, 3):
        raise ValueError("Capture requires a rank2/3 FP32 activation")
    mx.eval(value)
    host = np.array(value, dtype=np.float32, copy=True).reshape(-1, value.shape[-1])
    if not np.isfinite(host).all():
        raise ValueError("Actual capture contains nonfinite activations")
    return np.ascontiguousarray(host)


def capture_input(
    base: MLXKaiScorer,
    scorer: MLXKaiScorer | PrefixScorer,
    cases: tuple[EvaluationCase, ...],
    *,
    batch_size: int,
    expected_rows: int,
) -> CapturedInput:
    """One declared batch only; prefix construction must precede this hook."""
    if not cases or len(cases) != batch_size:
        raise ValueError("Capture requires one complete declared batch")
    with observe_projection(
        cast(ProjectionOwner, base.backbone.layers[0].mlp)
    ) as observer:
        cycle = _run(
            BenchmarkEngine(
                "actual-activation-capture", Model(scorer, base.model_id), batch_size
            ),
            cases,
        )
        if cycle.failed or len(observer.inputs) != 1:
            raise CaptureFailure(
                "Capture did not visit exactly one successful gate call", cycle
            )
        started = time.perf_counter_ns()
        values = detached_float32(observer.inputs[0])
        copy_elapsed_ms = (time.perf_counter_ns() - started) / 1e6
        if values.shape != (expected_rows, 1024):
            raise CaptureFailure(
                "Actual projection input differs from declared geometry", cycle
            )
    return CapturedInput(values, cycle, copy_elapsed_ms)


def exact_bfloat_bits(
    values: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> bool:
    """BF16 decode preserves FP32 bits, including the sign of zero."""
    return bool(
        np.isfinite(values).all() and np.all((values.view(np.uint32) & 0xFFFF) == 0)
    )


def projection_quality(
    reference: np.ndarray[tuple[int, int], np.dtype[np.float32]],
    candidate: np.ndarray[tuple[int, int], np.dtype[np.float32]],
) -> dict[str, object]:
    if (
        reference.shape != candidate.shape
        or reference.dtype != candidate.dtype
        or reference.dtype != np.float32
    ):
        raise ValueError("Projection quality requires matching FP32 shapes")
    finite = bool(np.isfinite(reference).all() and np.isfinite(candidate).all())
    difference = np.abs(candidate.astype(np.float64) - reference.astype(np.float64))
    failures = (~np.isfinite(difference)) | (
        difference > 1e-4 + 1e-4 * np.abs(reference.astype(np.float64))
    )
    return {
        "passed": finite and not bool(failures.any()),
        "finite": finite,
        "failing_elements": int(failures.sum()),
        "total_elements": reference.size,
        "max_abs_error": float(difference.max()) if finite else None,
        "atol": 1e-4,
        "rtol": 1e-4,
    }

"""One fixed tile policy: float SIMD arithmetic with independent weight storage.

Preparation checks actual device strides without asking MLX to copy inputs.
Only the public custom Metal API and Metal SIMD matrix operations are used.
This experiment does not replace production matmul.
"""

from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol, cast

import mlx.core as mx

TILE = 32
THREADS = 128
SHARED_BYTES = 3 * TILE * TILE * 4
HEADER = """
#include <metal_simdgroup>
#include <metal_simdgroup_matrix>
"""
SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 32;
const uint col_start = threadgroup_position_in_grid.x * 32;
const uint group_row = (group / 2) * 16;
const uint group_col = (group % 2) * 16;

threadgroup float x_tile[1024];
threadgroup float w_tile[1024];
threadgroup float output_tile[1024];
simdgroup_float8x8 accumulators[4];
for (uint i = 0; i < 4; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 1024; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // Stage W.T in float; no complete FP32 weight allocation.
        w_tile[local_col * 32 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[2];
        simdgroup_float8x8 b[2];
        for (uint i = 0; i < 2; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 32
                + group_col + i * 8, 32);
        }
        for (uint row = 0; row < 2; ++row) {
            for (uint col = 0; col < 2; ++col) {
                const uint i = row * 2 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    // No thread overwrites staged operands before every SIMD group finishes.
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

for (uint row = 0; row < 2; ++row) {
    for (uint col = 0; col < 2; ++col) {
        simdgroup_store(accumulators[row * 2 + col], output_tile
            + (group_row + row * 8) * 32 + group_col + col * 8, 32);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 1024; i += 128) {
    const uint row = row_start + i / 32;
    const uint col = col_start + i % 32;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""

LAYOUT_SOURCE = """
if (thread_position_in_grid.x == 0) {
    layout[0] = X_strides[0];
    layout[1] = X_strides[1];
    layout[2] = W_strides[0];
    layout[3] = W_strides[1];
}
"""


class MetalKernel(Protocol):
    def __call__(
        self,
        *,
        inputs: Sequence[mx.array],
        grid: tuple[int, int, int],
        threadgroup: tuple[int, int, int],
        output_shapes: Sequence[tuple[int, ...]],
        output_dtypes: Sequence[mx.Dtype],
    ) -> list[mx.array]: ...


@dataclass(frozen=True)
class PreparedProjection:
    """Validated inputs held ready; run excludes preparation and layout dispatch."""

    x: mx.array
    weight: mx.array
    kernel: MetalKernel

    def run(self) -> mx.array:
        rows, _ = self.x.shape
        columns, _ = self.weight.shape
        return self.kernel(
            inputs=[self.x, self.weight],
            grid=(
                THREADS * ((columns + TILE - 1) // TILE),
                (rows + TILE - 1) // TILE,
                1,
            ),
            threadgroup=(THREADS, 1, 1),
            output_shapes=[(rows, columns)],
            output_dtypes=[mx.float32],
        )[0]


class ProjectionKernel:
    """Build once; MLX compiles specializations lazily on evaluated dispatch."""

    def __init__(self) -> None:
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )
        self._layout = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_mixed_layout",
                input_names=["X", "W"],
                output_names=["layout"],
                source=LAYOUT_SOURCE,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        if x.dtype != mx.float32 or weight.dtype not in (mx.float32, mx.bfloat16):
            raise ValueError("Projection requires FP32 X and FP32 or BF16 W")
        if x.ndim != 2 or weight.ndim != 2:
            raise ValueError("Projection requires rank-two X[M,K] and W[N,K]")
        if any(d <= 0 or d > 2**31 - 1 for d in (*x.shape, *weight.shape)):
            raise ValueError("Projection dimensions must be positive int32 values")
        if x.shape[1] != weight.shape[1]:
            raise ValueError("Projection reduction dimensions differ")
        layout = self._layout(
            inputs=[x, weight],
            grid=(1, 1, 1),
            threadgroup=(1, 1, 1),
            output_shapes=[(4,)],
            output_dtypes=[mx.int64],
        )[0]
        mx.eval(layout)
        observed = cast(list[int], layout.tolist())
        expected = [x.shape[1], 1, weight.shape[1], 1]
        if observed != expected:
            raise ValueError(f"Projection requires row-contiguous inputs: {observed}")
        return PreparedProjection(x, weight, self._projection)

"""Read-only admission of the audited initial projection and exact captured bytes."""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from pathlib import Path

from wyat.backends.kai.artifact import load_artifact
from wyat.wire import JsonObject, JsonValue, read_object

ROOT = Path(__file__).resolve().parents[4]
INITIAL = ROOT / "benchmarks/analysis/results/mlx-mixed-gate.json"
REVIEW = INITIAL.with_name("mlx-mixed-gate-review.json")
VERIFICATION = ROOT / "benchmarks/real/mlx-mixed-tooling-verification.json"
IDENTITIES = {
    INITIAL: "fb8bde4a9a7d0c5b24c40a67183f582dc46c56c8d3ccbb79461d87065c023b8c",
    REVIEW: "08d8b0bd6f60b8f24a2374a1ead6a43cc32d0228d10c77b3f714379314c9e985",
    VERIFICATION: "e332f2fafda3712eca17f5637cc0490165349021a7f7b826432e84e0c7cd681b",
}
DOC = "docs/analysis/mixed.md"
DOC_SHA256 = "ab0ce4e460dd7614e6ee63a5bf839671902b446ccb9bb26044c33218d29d0f59"


def object_value(value: JsonValue) -> JsonObject:
    if not isinstance(value, dict):
        raise ValueError("Expected object")
    return value


def string(value: JsonValue) -> str:
    if not isinstance(value, str):
        raise ValueError("Expected string")
    return value


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def checked_file(record: JsonValue) -> Path:
    entry = object_value(record)
    path = Path(string(entry["path"]))
    if digest(path) != string(entry["sha256"]):
        raise ValueError(f"Frozen artifact changed: {path.name}")
    return path


def archive(record: JsonValue, hashes: JsonObject, count: int) -> dict[str, Path]:
    """Archive text is immutable; only the named documentation may now differ."""
    value = read_object(checked_file(record))
    entries = value["files"]
    if not isinstance(entries, list) or len(entries) != count or len(hashes) != count:
        raise ValueError("Frozen source inventory changed")
    paths: dict[str, Path] = {}
    for part in entries:
        entry = object_value(part)
        name, text = string(entry["name"]), string(entry["text"])
        expected = string(entry["sha256"])
        if name in paths or hashlib.sha256(text.encode()).hexdigest() != expected:
            raise ValueError("Invalid archived source text or repeated name")
        if hashes.get(name) != expected:
            raise ValueError("Source archive differs from recorded inventory")
        path = Path(string(entry["path"]))
        if name == DOC and (
            digest(path) != DOC_SHA256 or not path.read_text().startswith(text)
        ):
            raise ValueError("Only the audited documentation append is admitted")
        if name != DOC and digest(path) != expected:
            raise ValueError(f"Frozen executable source changed: {name}")
        paths[name] = path
    if set(paths) != set(hashes):
        raise ValueError("Frozen source names changed")
    return paths


@dataclass(frozen=True, slots=True)
class Admission:
    initial: JsonObject
    inputs: Path
    cold: Path
    sources: dict[str, Path]


def admit(model: Path) -> Admission:
    for path, expected in IDENTITIES.items():
        if digest(path) != expected:
            raise ValueError(f"Frozen admission receipt changed: {path.name}")
    initial, review, verification = map(read_object, IDENTITIES)
    if (
        initial["completed"] is not True
        or initial["capture_quality_passed"] is not True
        or initial["projection_quality_passed"] is not True
        or review["audit_passed"] is not True
        or verification["completed"] is not True
    ):
        raise ValueError("Initial projection evidence is incomplete")
    sources = archive(
        initial["source_archive"], object_value(initial["source_hashes"]), 43
    )
    sources.update(
        archive(
            verification["source_archive"],
            object_value(verification["source_sha256"]),
            104,
        )
    )
    artifacts = object_value(review["artifacts"])
    for record in artifacts.values():
        checked_file(record)
    inputs, cold = (
        checked_file(initial["captured_bytes"]),
        checked_file(initial["cold_outputs"]),
    )
    if inputs != checked_file(artifacts["inputs"]) or cold != checked_file(
        artifacts["cold_outputs"]
    ):
        raise ValueError("Independent audit names different tensor artifacts")
    artifact = load_artifact(model, max_length=512)
    if artifact.model_id != initial["model_id"]:
        raise ValueError("Frozen checkpoint identity changed")
    for path, field in (
        (ROOT / "benchmarks/real/banking77-train-dev-menu6.jsonl", "dataset_sha256"),
        (ROOT / "benchmarks/real/torch-fp32-reference77.json", "reference_sha256"),
    ):
        if digest(path) != initial[field]:
            raise ValueError("Frozen data/reference identity changed")
    return Admission(initial, inputs, cold, sources)

"""One 64×64×32 output-reuse hypothesis, with the frozen admission contract.

Sixteen float SIMD accumulators per SIMD group and 32 KiB of shared storage
are explicit costs. The initial 32-tile implementation remains untouched.
"""

from dataclasses import dataclass
from typing import cast

import mlx.core as mx

from benchmarks.analysis.mlx.mixed.kernel import HEADER, MetalKernel
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as Admission

TILE = 64
REDUCTION = 32
THREADS = 128
SHARED_BYTES = (2 * TILE * REDUCTION + TILE * TILE) * 4
SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 64;
const uint col_start = threadgroup_position_in_grid.x * 64;
const uint group_row = (group / 2) * 32;
const uint group_col = (group % 2) * 32;

threadgroup float x_tile[2048];
threadgroup float w_tile[2048];
threadgroup float output_tile[4096];
simdgroup_float8x8 accumulators[16];
for (uint i = 0; i < 16; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 2048; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // The weight storage changes; float staged operands do not.
        w_tile[local_col * 64 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[4];
        simdgroup_float8x8 b[4];
        for (uint i = 0; i < 4; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 64
                + group_col + i * 8, 64);
        }
        for (uint row = 0; row < 4; ++row) {
            for (uint col = 0; col < 4; ++col) {
                const uint i = row * 4 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

for (uint row = 0; row < 4; ++row) {
    for (uint col = 0; col < 4; ++col) {
        simdgroup_store(accumulators[row * 4 + col], output_tile
            + (group_row + row * 8) * 64 + group_col + col * 8, 64);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 4096; i += 128) {
    const uint row = row_start + i / 64;
    const uint col = col_start + i % 64;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""


@dataclass(frozen=True)
class PreparedProjection:
    """Ready immutable operands; no admission check or input copy inside run."""

    x: mx.array
    weight: mx.array
    kernel: MetalKernel

    def run(self) -> mx.array:
        rows, _ = self.x.shape
        columns, _ = self.weight.shape
        return self.kernel(
            inputs=[self.x, self.weight],
            grid=(
                THREADS * ((columns + TILE - 1) // TILE),
                (rows + TILE - 1) // TILE,
                1,
            ),
            threadgroup=(THREADS, 1, 1),
            output_shapes=[(rows, columns)],
            output_dtypes=[mx.float32],
        )[0]


class ProjectionKernel:
    """Share the live 32-tile control's public validator; compile lazily once."""

    def __init__(self, admission: Admission) -> None:
        self._admission = admission
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_tile_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        admitted = self._admission.prepare(x, weight)
        return PreparedProjection(admitted.x, admitted.weight, self._projection)

"""Fixed64 reuse trial on admitted prior activations; no model recapture."""

from __future__ import annotations

import hashlib
import itertools
import os
import time
from collections.abc import Callable
from pathlib import Path
from typing import cast

import mlx.core as mx
import numpy as np
from safetensors.numpy import load, save_file

from benchmarks.analysis.evidence import freeze_sources
from benchmarks.analysis.mlx.endpoints import memory
from benchmarks.analysis.mlx.mixed.capture import (
    detached_float32,
    exact_bfloat_bits,
    projection_quality,
)
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as FrozenKernel
from benchmarks.analysis.mlx.mixed.study import ARMS as ORIGINAL_ARMS
from benchmarks.analysis.mlx.mixed.study import (
    SHAPES,
    output_digest,
    performance,
    restored_cache,
    save,
)

from .admit import IDENTITIES, ROOT, Admission, digest, object_value

type Array = np.ndarray[tuple[int, int], np.dtype[np.float32]]
type Operation = Callable[[], mx.array]
ARMS = ("maintained", "tile32-bf16", "tile64-bf16")
ORDERS = tuple(itertools.permutations(ARMS))
CONTROL = "tile64-fp32"


def read_arrays(admission: Admission) -> tuple[dict[str, Array], dict[str, Array]]:
    def consumed(path: Path, field: str) -> dict[str, Array]:
        raw = path.read_bytes()
        expected = object_value(admission.initial[field])["sha256"]
        if hashlib.sha256(raw).hexdigest() != expected:
            raise ValueError("Captured tensor artifact changed before consumption")
        return cast(dict[str, Array], load(raw))

    inputs = consumed(admission.inputs, "captured_bytes")
    cold = consumed(admission.cold, "cold_outputs")
    if set(inputs) != {"weight", *(name for name, _, _ in SHAPES)} or set(cold) != {
        name + "-" + arm for name, _, _ in SHAPES for arm in ORIGINAL_ARMS
    }:
        raise ValueError("Frozen tensor inventory changed")
    checks = [("weight", (3072, 1024), object_value(admission.initial["weight"]))]
    captures = object_value(admission.initial["captures"])
    checks.extend(
        (name, (rows, 1024), object_value(captures[name])) for name, _, rows in SHAPES
    )
    for name, shape, record in checks:
        value = inputs[name]
        if (
            value.dtype != np.float32
            or value.shape != shape
            or not np.isfinite(value).all()
            or hashlib.sha256(value.tobytes()).hexdigest() != record["sha256"]
        ):
            raise ValueError("Frozen input geometry or bytes changed")
    if not exact_bfloat_bits(inputs["weight"]):
        raise ValueError("Captured weight is not bitwise BF16 decodable")
    shapes = object_value(admission.initial["shapes"])
    for name, _, rows in SHAPES:
        hashes = object_value(object_value(shapes[name])["cold_output_sha256"])
        for arm in ORIGINAL_ARMS:
            value = cold[name + "-" + arm]
            if (
                value.dtype != np.float32
                or value.shape != (rows, 3072)
                or not np.isfinite(value).all()
                or hashlib.sha256(value.tobytes()).hexdigest() != hashes[arm]
            ):
                raise ValueError("Frozen cold outputs changed")
    return inputs, cold


def comparison(blocks: list[dict[str, object]], baseline: str) -> dict[str, object]:
    """Reuse the original six-permutation gate; keep32 comparison descriptive."""
    translated: list[dict[str, object]] = []
    original_orders = tuple(itertools.permutations(ORIGINAL_ARMS))
    for block, expected, original_order in zip(
        blocks, ORDERS, original_orders, strict=True
    ):
        if tuple(cast(list[str], block["order"])) != expected:
            raise ValueError("Balanced execution order changed")
        timings = cast(dict[str, list[int]], block["dispatch_ns"])
        if set(timings) != set(ARMS):
            raise ValueError("Missing timed arm")
        translated.append(
            {
                "order": list(original_order),
                "dispatch_ns": {
                    "maintained": timings[baseline],
                    "custom-fp32": timings["tile32-bf16"],
                    "custom-bf16": timings["tile64-bf16"],
                },
            }
        )
    report = performance(translated)
    if baseline != "maintained":
        report.pop("passed")
    return report


def timed_blocks(
    calls: dict[str, Operation],
    cold: dict[str, str],
    result: dict[str, object],
    progress: Callable[[], None],
) -> None:
    warm: dict[str, str] = {}
    for arm in ARMS:
        y = calls[arm]()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        warm[arm] = output_digest(y)
        del y
    result["warm_output_sha256"] = warm
    progress()
    if warm != cold:
        raise ValueError("Warm outputs changed from cold")
    blocks: list[dict[str, object]] = []
    result["blocks"] = blocks
    for order in ORDERS:
        timings: dict[str, list[int]] = {}
        hashes: dict[str, list[str]] = {}
        block: dict[str, object] = {
            "order": list(order),
            "dispatch_ns": timings,
            "output_sha256": hashes,
            "completed": False,
            "outputs_reproduce_cold": False,
            "memory_before": memory(),
        }
        blocks.append(block)
        for arm in order:
            timings[arm], hashes[arm] = [], []
            for _ in range(10):
                mx.synchronize(mx.gpu)
                start = time.perf_counter_ns()
                y = calls[arm]()
                mx.eval(y)
                mx.synchronize(mx.gpu)
                timings[arm].append(time.perf_counter_ns() - start)
                hashes[arm].append(output_digest(y))
                del y
            progress()
        reproduced = all(
            value == cold[arm] for arm, values in hashes.items() for value in values
        )
        block.update(
            completed=True, outputs_reproduce_cold=reproduced, memory_after=memory()
        )
        progress()
        if not reproduced:
            raise ValueError("Timed outputs changed from cold")
    result["performance"] = comparison(blocks, "maintained")
    result["tile32_over_tile64"] = comparison(blocks, "tile32-bf16")
    progress()


def screen(
    calls: dict[str, Operation], original: dict[str, Array], name: str
) -> tuple[dict[str, object], dict[str, Array]]:
    values: dict[str, Array] = {}
    cold_ms: dict[str, float] = {}
    for arm, call in calls.items():
        mx.synchronize(mx.gpu)
        start = time.perf_counter_ns()
        y = call()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        cold_ms[arm] = (time.perf_counter_ns() - start) / 1e6
        values[arm] = detached_float32(y)
        del y
    hashes = {
        arm: hashlib.sha256(value.tobytes()).hexdigest()
        for arm, value in values.items()
    }
    history = all(
        np.array_equal(
            values[arm].view(np.uint32), original[name + "-" + old].view(np.uint32)
        )
        for arm, old in (("maintained", "maintained"), ("tile32-bf16", "custom-bf16"))
    )
    storage = np.array_equal(
        values[CONTROL].view(np.uint32), values["tile64-bf16"].view(np.uint32)
    )
    quality = {
        arm: projection_quality(values["maintained"], values[arm])
        for arm in (*ARMS[1:], CONTROL)
    }
    result: dict[str, object] = {
        "cold_dispatch_ms": cold_ms,
        "cold_output_sha256": hashes,
        "original_cold_outputs_reproduced": history,
        "custom_storage_bitwise_equal": storage,
        "quality": quality,
        "passed": history
        and storage
        and all(gate["passed"] is True for gate in quality.values()),
        "blocks": [],
    }
    return result, values


def study(admission: Admission, output: Path) -> bool:
    if output.exists():
        raise FileExistsError("Preserve prior tile receipts")
    if os.environ.get("MLX_ENABLE_TF32") != "0":
        raise ValueError("Disable TF32 before importing MLX")
    payload: dict[str, object] = {
        "completed": False,
        "accepted": False,
        "phase": "admission",
        "scope": (
            "Archived first-layer gate projection only;8 development cases; "
            "no model recapture or complete inference claim"
        ),
        "protocol": {
            "shapes": SHAPES,
            "arms": ARMS,
            "cold_control": CONTROL,
            "orders": ORDERS,
            "dispatches_per_arm_block": 10,
            "warm_dispatches": 1,
            "cold_dispatches": 1,
            "timeout_seconds": 180,
            "cache_cap_bytes": 512 << 20,
            "atol": 1e-4,
            "rtol": 1e-4,
            "median_minimum": 1.05,
            "p05_exclusive_minimum": 1.0,
            "bitwise_storage_controls": True,
            "partial_receipt": (
                "Complete arms saved; interruption during ten dispatches "
                "leaves partial arm unknown"
            ),
            "observation": (
                "Every warm/timed output hashed outside its timer against cold; "
                "observations separate dispatches, not unobserved throughput"
            ),
        },
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    save(output, payload)
    try:
        from .kernel import ProjectionKernel

        sources = {
            **admission.sources,
            **{
                str(path.relative_to(ROOT)): path
                for path in Path(__file__).parent.glob("*.py")
            },
        }
        sources["docs/analysis/tile.md"] = ROOT / "docs/analysis/tile.md"
        sources["tests/analysis/test_mlx_tile_protocol.py"] = (
            ROOT / "tests/analysis/test_mlx_tile_protocol.py"
        )
        sources["tests/analysis/test_mlx_tile_kernel.py"] = (
            ROOT / "tests/analysis/test_mlx_tile_kernel.py"
        )
        frozen = freeze_sources(sources, output)
        inputs, original = read_arrays(admission)
        payload.update(
            source_hashes=frozen.hashes(),
            source_archive=frozen.archive(),
            reused_inputs={
                "path": str(admission.inputs),
                "sha256": digest(admission.inputs),
            },
            prior_receipts={
                str(path): expected for path, expected in IDENTITIES.items()
            },
            initial_cold_outputs=admission.initial["cold_outputs"],
            model_id=admission.initial["model_id"],
            dataset_sha256=admission.initial["dataset_sha256"],
            reference_sha256=admission.initial["reference_sha256"],
            input_sha256=admission.initial["input_sha256"],
            device=mx.device_info(mx.gpu),
        )
        with restored_cache(payload), mx.stream(mx.gpu):
            fixed32 = FrozenKernel()
            fixed64 = ProjectionKernel(fixed32)
            w32 = mx.array(inputs["weight"], dtype=mx.float32)
            w16 = w32.astype(mx.bfloat16)
            mx.eval(w32, w16)
            if not np.array_equal(
                detached_float32(w16.astype(mx.float32)).view(np.uint32),
                inputs["weight"].view(np.uint32),
            ):
                raise ValueError("Device BF16 reconstruction changed weight bits")
            results: dict[str, dict[str, object]] = {}
            calls_by_shape: dict[str, dict[str, Operation]] = {}
            cold_values: dict[str, Array] = {}
            payload.update(phase="screen", shapes=results)
            for name, _, _ in SHAPES:
                x = mx.array(inputs[name], dtype=mx.float32)
                mx.eval(x)
                ready32 = fixed32.prepare(x, w16)
                ready64 = fixed64.prepare(x, w16)
                control = fixed64.prepare(x, w32)

                def maintained(x: mx.array = x) -> mx.array:
                    return x @ w32.T

                calls = {
                    "maintained": maintained,
                    "tile32-bf16": ready32.run,
                    "tile64-bf16": ready64.run,
                    CONTROL: control.run,
                }
                results[name], values = screen(calls, original, name)
                cold_values.update(
                    {name + "-" + arm: value for arm, value in values.items()}
                )
                calls_by_shape[name] = {arm: calls[arm] for arm in ARMS}
                save(output, payload)
            cold_path = output.with_suffix(".outputs.tensors.safetensors")
            if cold_path.exists():
                raise FileExistsError("Preserve cold outputs")
            save_file(cold_values, str(cold_path))
            payload["cold_outputs"] = {
                "path": str(cold_path),
                "sha256": digest(cold_path),
            }
            numerical = all(result["passed"] is True for result in results.values())
            payload["projection_quality_passed"] = numerical
            if numerical:
                if any(digest(Path(item.path)) != item.sha256 for item in frozen.files):
                    raise ValueError("Frozen trial sources changed")
                payload["phase"] = "timing"
                for name, _, _ in SHAPES:
                    hashes = cast(dict[str, str], results[name]["cold_output_sha256"])
                    timed_blocks(
                        calls_by_shape[name],
                        {arm: hashes[arm] for arm in ARMS},
                        results[name],
                        lambda: save(output, payload),
                    )
            payload.update(
                completed=True,
                phase="complete",
                accepted=numerical
                and all(
                    cast(dict[str, object], results[name].get("performance", {})).get(
                        "passed"
                    )
                    is True
                    for name in ("prefix-b1", "prefix-b8")
                ),
            )
    except BaseException as error:
        payload.update(
            completed=False, accepted=False, error=f"{type(error).__name__}: {error}"
        )
    finally:
        try:
            save(output, payload)
        except Exception as error:
            payload.update(
                completed=False,
                accepted=False,
                final_write_error=f"{type(error).__name__}: {error}",
            )
            save(output, payload)
    return payload["completed"] is True and payload["accepted"] is True

"""Request static fragment indexing without changing the 64-tile policy.

An unroll pragma is a compiler request, not evidence of removed spills.
The historical 32/64 policies remain untouched and executable controls.
"""

from typing import cast

import mlx.core as mx

from benchmarks.analysis.mlx.mixed.kernel import HEADER, MetalKernel
from benchmarks.analysis.mlx.tile.kernel import PreparedProjection
from benchmarks.analysis.mlx.tile.kernel import ProjectionKernel as Admission

SOURCE = """
const uint M = X_shape[0];
const uint K = X_shape[1];
const uint N = W_shape[0];
const uint tid = thread_index_in_threadgroup;
const uint group = simdgroup_index_in_threadgroup;
const uint row_start = threadgroup_position_in_grid.y * 64;
const uint col_start = threadgroup_position_in_grid.x * 64;
const uint group_row = (group / 2) * 32;
const uint group_col = (group % 2) * 32;

threadgroup float x_tile[2048];
threadgroup float w_tile[2048];
threadgroup float output_tile[4096];
simdgroup_float8x8 accumulators[16];
#pragma clang loop unroll(full)
for (uint i = 0; i < 16; ++i) {
    accumulators[i] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
}

for (uint start = 0; start < K; start += 32) {
    for (uint i = tid; i < 2048; i += 128) {
        const uint local_row = i / 32;
        const uint local_col = i % 32;
        const uint row = row_start + local_row;
        const uint col = col_start + local_row;
        const uint reduction = start + local_col;
        x_tile[i] = (row < M && reduction < K)
            ? float(X[size_t(row) * K + reduction]) : 0.0f;
        // The weight storage changes; float staged operands do not.
        w_tile[local_col * 64 + local_row] = (col < N && reduction < K)
            ? float(W[size_t(col) * K + reduction]) : 0.0f;
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
    #pragma clang loop unroll(full)
    for (uint reduction = 0; reduction < 32; reduction += 8) {
        simdgroup_float8x8 a[4];
        simdgroup_float8x8 b[4];
        #pragma clang loop unroll(full)
        for (uint i = 0; i < 4; ++i) {
            simdgroup_load(a[i], x_tile + (group_row + i * 8) * 32
                + reduction, 32);
            simdgroup_load(b[i], w_tile + reduction * 64
                + group_col + i * 8, 64);
        }
        #pragma clang loop unroll(full)
        for (uint row = 0; row < 4; ++row) {
            #pragma clang loop unroll(full)
            for (uint col = 0; col < 4; ++col) {
                const uint i = row * 4 + col;
                simdgroup_multiply_accumulate(accumulators[i], a[row], b[col],
                    accumulators[i]);
            }
        }
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}

#pragma clang loop unroll(full)
for (uint row = 0; row < 4; ++row) {
    #pragma clang loop unroll(full)
    for (uint col = 0; col < 4; ++col) {
        simdgroup_store(accumulators[row * 4 + col], output_tile
            + (group_row + row * 8) * 64 + group_col + col * 8, 64);
    }
}
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint i = tid; i < 4096; i += 128) {
    const uint row = row_start + i / 64;
    const uint col = col_start + i % 64;
    if (row < M && col < N) {
        Y[size_t(row) * N + col] = output_tile[i];
    }
}
"""


class ProjectionKernel:
    """Share prior 64-tile admission and ready dispatch; compile lazily once."""

    def __init__(self, admission: Admission) -> None:
        self._admission = admission
        self._projection = cast(
            MetalKernel,
            mx.fast.metal_kernel(
                name="wyat_unroll_projection",
                input_names=["X", "W"],
                output_names=["Y"],
                source=SOURCE,
                header=HEADER,
                ensure_row_contiguous=False,
                compile_options={"math_mode": "safe"},
            ),
        )

    def prepare(self, x: mx.array, weight: mx.array) -> PreparedProjection:
        admitted = self._admission.prepare(x, weight)
        return PreparedProjection(admitted.x, admitted.weight, self._projection)

"""Compare maintained, frozen64 and explicitly unrolled64 on exact prior inputs."""

from __future__ import annotations

import hashlib
import itertools
import os
import time
from collections.abc import Callable, Mapping
from pathlib import Path
from typing import cast

import mlx.core as mx
import numpy as np
from safetensors.numpy import load, save_file

from benchmarks.analysis.evidence import freeze_sources
from benchmarks.analysis.mlx.endpoints import memory
from benchmarks.analysis.mlx.mixed.capture import detached_float32, projection_quality
from benchmarks.analysis.mlx.mixed.kernel import ProjectionKernel as OriginalKernel
from benchmarks.analysis.mlx.mixed.study import (
    SHAPES,
    output_digest,
    restored_cache,
    save,
)
from benchmarks.analysis.mlx.tile.admit import ROOT, digest, object_value
