from .run import PINNED, Context

ARMS = ("maintained", "tile64-bf16", "unroll64-bf16")
ORDERS = tuple(itertools.permutations(ARMS))
CONTROL = "unroll64-fp32"


def comparison(blocks: list[dict[str, object]], baseline: str) -> dict[str, object]:
    ratios: list[float] = []
    for block, expected in zip(blocks, ORDERS, strict=True):
        if tuple(cast(list[str], block["order"])) != expected:
            raise ValueError("Balanced execution order changed")
        timings = cast(dict[str, list[int]], block["dispatch_ns"])
        if set(timings) != set(ARMS) or any(
            len(values) != 10
            or any(type(value) is not int or value <= 0 for value in values)
            for values in timings.values()
        ):
            raise ValueError("Requires all30 positive timings per block")
        ratios.append(sum(timings[baseline]) / sum(timings[ARMS[2]]))
    median, p05 = percentile(ratios, 0.5), percentile(ratios, 0.05)
    report: dict[str, object] = {
        "paired_ratios": ratios,
        "paired_median": median,
        "paired_p05": p05,
    }
    if baseline == ARMS[0]:
        report["passed"] = median >= 1.05 and p05 > 1
    return report


def measure(
    calls: Mapping[str, Operation],
    cold: Mapping[str, str],
    result: dict[str, object],
    progress: Callable[[], None],
) -> None:
    """Fresh synchronized dispatches; output observations occur after each timer."""
    warm: dict[str, str] = {}
    for arm in ARMS:
        y = calls[arm]()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        warm[arm] = output_digest(y)
        del y
    result["warm_output_sha256"] = warm
    progress()
    if warm != cold:
        raise ValueError("Warm outputs changed from cold")
    blocks: list[dict[str, object]] = []
    result["blocks"] = blocks
    for order in ORDERS:
        timings: dict[str, list[int]] = {}
        hashes: dict[str, list[str]] = {}
        block: dict[str, object] = {
            "order": list(order),
            "dispatch_ns": timings,
            "output_sha256": hashes,
            "completed": False,
            "outputs_reproduce_cold": False,
            "memory_before": memory(),
        }
        blocks.append(block)
        for arm in order:
            timings[arm], hashes[arm] = [], []
            for _ in range(10):
                mx.synchronize(mx.gpu)
                start = time.perf_counter_ns()
                y = calls[arm]()
                mx.eval(y)
                mx.synchronize(mx.gpu)
                timings[arm].append(time.perf_counter_ns() - start)
                hashes[arm].append(output_digest(y))
                del y
            progress()
        reproduced = all(
            value == cold[arm] for arm, values in hashes.items() for value in values
        )
        block.update(
            completed=True, outputs_reproduce_cold=reproduced, memory_after=memory()
        )
        progress()
        if not reproduced:
            raise ValueError("Timed outputs changed from cold")
    result["performance"] = comparison(blocks, ARMS[0])
    result["tile64_over_unroll64"] = comparison(blocks, ARMS[1])
    progress()


def previous_outputs(context: Context) -> dict[str, Array]:
    raw = context.cold.read_bytes()
    if (
        hashlib.sha256(raw).hexdigest()
        != object_value(context.prior["cold_outputs"])["sha256"]
    ):
        raise ValueError("Frozen64 output artifact changed before consumption")
    arrays = cast(dict[str, Array], load(raw))
    prior_arms = ("maintained", "tile32-bf16", "tile64-bf16", "tile64-fp32")
    if set(arrays) != {name + "-" + arm for name, _, _ in SHAPES for arm in prior_arms}:
        raise ValueError("Frozen64 output inventory changed")
    for name, _, rows in SHAPES:
        hashes = object_value(
            object_value(object_value(context.prior["shapes"])[name])[
                "cold_output_sha256"
            ]
        )
        for arm in prior_arms:
            value = arrays[name + "-" + arm]
            if (
                value.dtype != np.float32
                or value.shape != (rows, 3072)
                or not np.isfinite(value).all()
                or hashlib.sha256(value.tobytes()).hexdigest() != hashes[arm]
            ):
                raise ValueError("Frozen64 output tensor changed")
    return arrays


def screen(
    calls: Mapping[str, Operation], original: Mapping[str, Array], name: str
) -> tuple[dict[str, object], dict[str, Array]]:
    values: dict[str, Array] = {}
    cold_ms: dict[str, float] = {}
    for arm, call in calls.items():
        mx.synchronize(mx.gpu)
        start = time.perf_counter_ns()
        y = call()
        mx.eval(y)
        mx.synchronize(mx.gpu)
        cold_ms[arm] = (time.perf_counter_ns() - start) / 1e6
        values[arm] = detached_float32(y)
        del y
    reproduced = all(
        np.array_equal(
            values[arm].view(np.uint32), original[name + "-" + arm].view(np.uint32)
        )
        for arm in ARMS[:2]
    )
    storage_equal = np.array_equal(
        values[CONTROL].view(np.uint32), values[ARMS[2]].view(np.uint32)
    )
    quality = {
        arm: projection_quality(values[ARMS[0]], values[arm])
        for arm in (*ARMS[1:], CONTROL)
    }
    return {
        "cold_dispatch_ms": cold_ms,
        "cold_output_sha256": {
            arm: hashlib.sha256(value.tobytes()).hexdigest()
            for arm, value in values.items()
        },
        "original_cold_outputs_reproduced": reproduced,
        "custom_storage_bitwise_equal": storage_equal,
        "quality": quality,
        "passed": reproduced
        and storage_equal
        and all(gate["passed"] is True for gate in quality.values()),
        "blocks": [],
    }, values


def study(context: Context, output: Path) -> bool:
    if output.exists():
        raise FileExistsError("Preserve prior unroll receipts")
    if os.environ.get("MLX_ENABLE_TF32") != "0":
        raise ValueError("Disable TF32 before importing MLX")
    payload: dict[str, object] = {
        "completed": False,
        "accepted": False,
        "phase": "admission",
        "scope": (
            "Exact archived first-layer gate projection; no model recapture "
            "or complete inference speed claim"
        ),
        "protocol": {
            "shapes": SHAPES,
            "arms": ARMS,
            "cold_control": CONTROL,
            "orders": ORDERS,
            "dispatches_per_arm_block": 10,
            "warm_dispatches": 1,
            "cold_dispatches": 1,
            "timeout_seconds": 180,
            "cache_cap_bytes": 512 << 20,
            "atol": 1e-4,
            "rtol": 1e-4,
            "median_minimum": 1.05,
            "p05_exclusive_minimum": 1.0,
            "bitwise_storage_controls": True,
            "partial_receipt": (
                "Complete arms saved; interruption during ten dispatches "
                "leaves partial arm unknown"
            ),
            "observation": (
                "Every warm/timed output hashed after its timer; "
                "observations separate dispatches, not unobserved throughput"
            ),
        },
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    save(output, payload)
    try:
        from .kernel import ProjectionKernel

        sources = {
            **context.sources,
            **{
                str(path.relative_to(ROOT)): path
                for path in Path(__file__).parent.glob("*.py")
            },
        }
        sources.update(
            {
                name: ROOT / name
                for name in (
                    "docs/analysis/unroll.md",
                    "pyproject.toml",
                    "tests/analysis/test_mlx_unroll_protocol.py",
                    "tests/analysis/test_mlx_unroll_kernel.py",
                )
            }
        )
        frozen = freeze_sources(sources, output)
        inputs, obsolete_cold = read_arrays(context.original)
        del obsolete_cold
        original = previous_outputs(context)
        payload.update(
            source_hashes=frozen.hashes(),
            source_archive=frozen.archive(),
            reused_inputs={
                "path": str(context.original.inputs),
                "sha256": digest(context.original.inputs),
            },
            prior_receipts={str(path): sha for path, sha in PINNED.items()},
            prior_cold_outputs=context.prior["cold_outputs"],
            **{
                field: context.prior[field]
                for field in (
                    "model_id",
                    "dataset_sha256",
                    "reference_sha256",
                    "input_sha256",
                )
            },
            device=mx.device_info(mx.gpu),
        )
        with restored_cache(payload), mx.stream(mx.gpu):
            frozen64 = FrozenKernel(OriginalKernel())
            unroll64 = ProjectionKernel(frozen64)
            w32 = mx.array(inputs["weight"], dtype=mx.float32)
            w16 = w32.astype(mx.bfloat16)
            mx.eval(w32, w16)
            if not np.array_equal(
                detached_float32(w16.astype(mx.float32)).view(np.uint32),
                inputs["weight"].view(np.uint32),
            ):
                raise ValueError("Device BF16 reconstruction changed weight bits")
            results: dict[str, dict[str, object]] = {}
            operations: dict[str, dict[str, Operation]] = {}
            cold_values: dict[str, Array] = {}
            payload.update(phase="screen", shapes=results)
            for name, _, _ in SHAPES:
                x = mx.array(inputs[name], dtype=mx.float32)
                mx.eval(x)
                ready_old = frozen64.prepare(x, w16)
                ready_new = unroll64.prepare(x, w16)
                control = unroll64.prepare(x, w32)

                def maintained(x: mx.array = x) -> mx.array:
                    return x @ w32.T

                calls = {
                    ARMS[0]: maintained,
                    ARMS[1]: ready_old.run,
                    ARMS[2]: ready_new.run,
                    CONTROL: control.run,
                }
                results[name], values = screen(calls, original, name)
                cold_values.update(
                    {name + "-" + arm: value for arm, value in values.items()}
                )
                operations[name] = {arm: calls[arm] for arm in ARMS}
                save(output, payload)
            cold_path = output.with_suffix(".outputs.tensors.safetensors")
            if cold_path.exists():
                raise FileExistsError("Preserve cold outputs")
            save_file(cold_values, str(cold_path))
            payload["cold_outputs"] = {
                "path": str(cold_path),
                "sha256": digest(cold_path),
            }
            numerical = all(result["passed"] is True for result in results.values())
            payload["projection_quality_passed"] = numerical
            if numerical:
                if any(digest(Path(item.path)) != item.sha256 for item in frozen.files):
                    raise ValueError("Frozen trial source changed")
                payload["phase"] = "timing"
                for name, _, _ in SHAPES:
                    hashes = cast(dict[str, str], results[name]["cold_output_sha256"])
                    measure(
                        operations[name],
                        {arm: hashes[arm] for arm in ARMS},
                        results[name],
                        lambda: save(output, payload),
                    )
            payload.update(
                completed=True,
                phase="complete",
                accepted=numerical
                and all(
                    cast(dict[str, object], results[name].get("performance", {})).get(
                        "passed"
                    )
                    is True
                    for name in ("prefix-b1", "prefix-b8")
                ),
            )
    except BaseException as error:
        payload.update(
            completed=False, accepted=False, error=f"{type(error).__name__}: {error}"
        )
    finally:
        try:
            save(output, payload)
        except Exception as error:
            payload.update(
                completed=False,
                accepted=False,
                final_write_error=f"{type(error).__name__}: {error}",
            )
            save(output, payload)
    return payload["completed"] is True and payload["accepted"] is True

"""Pure post-run audit of every endpoint cycle against frozen CPU scores."""

from __future__ import annotations

import hashlib
import json
from dataclasses import asdict
from pathlib import Path
from typing import cast

from wyat.benchmark import BenchmarkCycle, QualityGate, compare_cycles
from wyat.core import decision_from_logits
from wyat.evaluation import EvaluationCase, EvaluationRow, case_from_dict
from wyat.wire import decode_json, read_object


def object_value(value: object) -> dict[str, object]:
    if not isinstance(value, dict):
        raise ValueError("Expected object")
    return cast(dict[str, object], value)


def sequence(value: object) -> list[object]:
    if not isinstance(value, list):
        raise ValueError("Expected list")
    return cast(list[object], value)


def cycle(
    raw: object, cases: tuple[EvaluationCase, ...], model_id: str
) -> BenchmarkCycle:
    rows = sequence(object_value(raw)["rows"])
    if len(rows) != len(cases):
        raise ValueError("Cycle must contain every declared request")
    result: list[EvaluationRow] = []
    for case, item in zip(cases, rows, strict=True):
        row = object_value(item)
        if (
            row["id"] != case.id
            or row["expected"] != list(case.expected)
            or row.get("status", "ok") != "ok"
        ):
            raise ValueError("Cycle IDs, labels and successful coverage must match")
        prediction = row.get("prediction")
        if prediction is None:
            scores = sequence(row["legacy_logits"])
            if row["candidate_ids"] != [
                option.id for option in case.request.candidates
            ]:
                raise ValueError("Frozen candidate ordering changed")
        else:
            scores = sequence(object_value(prediction)["scores"])
        if any(type(score) not in (int, float) for score in scores):
            raise ValueError("Every score must be numeric")
        decision = decision_from_logits(
            case.request, tuple(float(cast(float, score)) for score in scores), model_id
        )
        if prediction is not None:
            recorded = object_value(prediction)
            if (
                recorded["model_id"] != model_id
                or recorded["selected"] != decision.selected
                or recorded["ranking"] != list(decision.ranking)
                or recorded["probabilities"] != list(decision.probabilities)
                or row["correct"] != (decision.selected in case.expected)
            ):
                raise ValueError("Recorded prediction differs from canonical scores")
        result.append(
            EvaluationRow(
                case.id,
                case.expected,
                "ok",
                decision,
                decision.selected in case.expected,
                0,
                None,
            )
        )
    return BenchmarkCycle(0, tuple(result), 0, 0)


def main() -> None:
    root = Path(__file__).resolve().parents[3]
    dataset = root / "benchmarks/real/banking77-train-dev-menu6.jsonl"
    reference_path = root / "benchmarks/real/torch-fp32-reference77.json"
    reference = object_value(read_object(reference_path))
    cases = tuple(
        case_from_dict(decode_json(line)) for line in dataset.read_text().splitlines()
    )
    model_id = cast(str, reference["model_id"])
    frozen = cycle(reference, cases, model_id)
    audits: dict[str, object] = {}
    for batch in (8, 1):
        path = root / f"benchmarks/analysis/results/mlx-endpoints77-b{batch}.json"
        receipt = object_value(read_object(path))
        if (
            receipt["passed"] is not True
            or receipt["completed"] is not True
            or receipt["reference_sha256"]
            != hashlib.sha256(reference_path.read_bytes()).hexdigest()
            or receipt["dataset_sha256"]
            != hashlib.sha256(dataset.read_bytes()).hexdigest()
            or receipt["model_id"] != model_id
        ):
            raise ValueError("Receipt identity or completion mismatch")
        paired = object_value(receipt["paired"])
        warmup = object_value(paired["warmup"])
        arms: dict[str, object] = {}
        for arm in ("baseline", "candidate"):
            warm = sequence(warmup[f"{arm}_cycles"])
            measured = sequence(object_value(paired[arm])["cycles"])
            if len(warm) != 1 or len(measured) != 5:
                raise ValueError("Expected one warmup and five complete cycles")
            cycles = tuple(cycle(raw, cases, model_id) for raw in warm + measured)
            gate = compare_cycles((frozen,) * len(cycles), cycles, QualityGate())
            arms[arm] = asdict(gate)
            if not gate.passed:
                raise ValueError(f"CPU reference gate failed: batch{batch}/{arm}")
        audits[f"batch{batch}"] = {
            "receipt_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "cycles_per_arm": 6,
            "arms": arms,
        }
    output = Path(__file__).with_name("mlx-endpoints-reference-audit.json")
    payload = {
        "passed": True,
        "audits": audits,
        "reference_sha256": hashlib.sha256(reference_path.read_bytes()).hexdigest(),
        "source_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "scope": "Pure post-run audit; no additional model execution or timing",
    }
    output.write_text(json.dumps(payload, indent=2) + "\n")
    print(json.dumps(payload))


if __name__ == "__main__":
    main()

"""Exact CPU FP32 prefix state; maintained cached model and full final block."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Protocol, cast

import torch
from transformers import Qwen3Config
from transformers.cache_utils import DynamicCache, DynamicLayer
from transformers.modeling_outputs import BaseModelOutputWithPast

from wyat.backends.kai.encoding import EncodedRequest
from wyat.backends.kai.torch import KaiScorer
from wyat.core import Request

type KVState = tuple[torch.Tensor, torch.Tensor]


class CacheConstructor(Protocol):
    def __call__(
        self,
        *,
        config: Qwen3Config,
        ddp_cache_data: tuple[KVState, ...] | None = None,
    ) -> DynamicCache: ...


# The maintained cache constructor is untyped; narrow this external boundary.
new_cache = cast(CacheConstructor, DynamicCache)


class PrefixScorer:
    """Fixed weights/config/device/encoder for one immutable prefix lifetime.

    Each invocation owns its DynamicCache. Seeding and suffix updates concatenate
    into private storage; no suffix state survives the invocation. Callers must
    keep the base in eval mode and never mutate its weights, config or encoder.
    Mismatched/overlapping batches fall back intact, including admission checks.
    """

    def __init__(self, base: KaiScorer, prefix: tuple[int, ...]) -> None:
        if not isinstance(base, KaiScorer):
            raise TypeError("CPU prefix requires a KaiScorer base")
        if type(prefix) is not tuple:
            raise TypeError("Prefix must be an exact immutable token tuple")
        config = base.backbone.config
        rotary = config.rope_parameters
        if (
            not isinstance(rotary, dict)
            or rotary.get("rope_type", "default") != "default"
        ):
            raise ValueError("CPU prefix requires default unscaled RoPE")
        if (
            base.device.type != "cpu"
            or config._attn_implementation != "sdpa"
            or any(module.training for module in base.backbone.modules())
            or any(module.training for module in base.head.modules())
            or any(
                value.device.type != "cpu" or value.dtype != torch.float32
                for value in (*base.backbone.parameters(), *base.head.parameters())
            )
            or any(value.device.type != "cpu" for value in base.backbone.buffers())
            or base.backbone.has_sliding_layers
        ):
            raise ValueError("CPU prefix requires eval FP32 CPU SDPA full attention")
        if (
            not prefix
            or len(prefix) >= base.max_length
            or any(
                type(token) is not int or not 0 <= token < config.vocab_size
                for token in prefix
            )
        ):
            raise ValueError("Prefix requires valid nonempty tokens below max_length")
        self.base = base
        self.model_id = base.model_id
        self._prefix = prefix
        with torch.inference_mode():
            cache = new_cache(config=config)
            base.backbone(
                input_ids=torch.tensor([prefix], dtype=torch.long),
                past_key_values=cache,
                use_cache=True,
            )
            states: list[KVState] = []
            for layer in cache.layers:
                if not isinstance(layer, DynamicLayer):
                    raise ValueError(
                        "CPU prefix requires maintained DynamicLayer state"
                    )
                keys, values = layer.keys, layer.values
                if (
                    keys is None
                    or values is None
                    or keys.shape != values.shape
                    or tuple(keys.shape)
                    != (1, config.num_key_value_heads, len(prefix), config.head_dim)
                    or keys.dtype != torch.float32
                    or values.dtype != torch.float32
                    or keys.stride(-1) != 1
                    or values.stride(-1) != 1
                    or not torch.isfinite(keys).all().item()
                    or not torch.isfinite(values).all().item()
                ):
                    raise ValueError(
                        "Maintained cache did not retain exact FP32 prefix"
                    )
                states.append(
                    (
                        keys.detach().clone().contiguous(),
                        values.detach().clone().contiguous(),
                    )
                )
            if len(states) != config.num_hidden_layers:
                raise ValueError("Maintained cache omitted a prefix layer")
            self._states = tuple(states)

    @property
    def prefix(self) -> tuple[int, ...]:
        return self._prefix

    @property
    def prefix_state_bytes(self) -> int:
        return sum(
            value.numel() * value.element_size()
            for pair in self._states
            for value in pair
        )

    def admits(self, row: EncodedRequest) -> bool:
        length = len(self.prefix)
        return (
            len(row.ids) > length
            and row.ids[:length] == self.prefix
            and row.query_position >= length
            and all(position >= length for position in row.candidate_positions)
        )

    def fork(self, batch_size: int) -> DynamicCache:
        """Maintained update/cat allocates batch-private K/V from prefix views."""
        if type(batch_size) is not int or batch_size < 1:
            raise ValueError("Cache batch size must be a positive integer")
        states = tuple(
            (keys.expand(batch_size, -1, -1, -1), values.expand(batch_size, -1, -1, -1))
            for keys, values in self._states
        )
        return new_cache(config=self.base.backbone.config, ddp_cache_data=states)

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        if not requests:
            return []
        # Admission applies to the complete original input before prefix removal.
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self.admits(row) for row in encoded):
            return self.base.score_many(requests)
        prefix_length = len(self.prefix)
        batch_size = len(encoded)
        length = max(len(row.ids) for row in encoded) - prefix_length
        width = max(len(row.candidate_positions) for row in encoded)
        ids = torch.full((batch_size, length), self.base.pad_id, dtype=torch.long)
        endpoints = torch.zeros((batch_size, width), dtype=torch.long)
        for index, row in enumerate(encoded):
            suffix = row.ids[prefix_length:]
            ids[index, : len(suffix)] = torch.tensor(suffix, dtype=torch.long)
            endpoints[index, : len(row.candidate_positions)] = torch.tensor(
                [position - prefix_length for position in row.candidate_positions]
            )
        rows = torch.arange(batch_size)
        positions = torch.tensor(
            [row.query_position - prefix_length for row in encoded]
        )
        with torch.inference_mode():
            # Keep maintained offset mask/RoPE: rectangular is_causal alone is wrong.
            output = cast(
                BaseModelOutputWithPast,
                self.base.backbone(
                    input_ids=ids, past_key_values=self.fork(batch_size), use_cache=True
                ),
            )
            hidden = output.last_hidden_state
            if hidden is None:
                raise ValueError("Kai backbone did not return suffix hidden states")
            logits = cast(
                torch.Tensor,
                self.base.head(
                    hidden[rows[:, None], endpoints], hidden[rows, positions]
                ),
            )
            values = cast(list[list[float]], logits.float().cpu().tolist())
        return [
            row[: len(item.candidate_positions)]
            for row, item in zip(values, encoded, strict=True)
        ]

"""One common prefix path with retained or one-use maintained cache owners."""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass
from typing import Literal, cast

import torch
from transformers import Qwen3Config
from transformers.cache_utils import DynamicCache, DynamicLayer
from transformers.modeling_outputs import BaseModelOutputWithPast

from benchmarks.analysis.torch.prefix.cache import PrefixScorer
from benchmarks.analysis.torch.prefix.lifetime import OneUseCache
from wyat.backends.kai.torch import KaiScorer
from wyat.core import Request

type Arm = Literal["retained", "one-use"]
type KVState = tuple[torch.Tensor, torch.Tensor]


@dataclass(frozen=True)
class StorageObservation:
    layer: int | None
    cache_owned_bytes: int
    returned_logical_bytes: int
    combined_unique_storage_bytes: int


def storage_bytes(tensors: Sequence[torch.Tensor]) -> int:
    """Deduplicate actual underlying CPU allocations, including aliased views."""
    allocations = {
        (tensor.untyped_storage().data_ptr(), tensor.untyped_storage().nbytes())
        for tensor in tensors
    }
    return sum(size for _, size in allocations)


def observe_storage(
    cache: DynamicCache,
    seeds: tuple[KVState, ...],
    returned: KVState | None,
    layer: int | None,
) -> StorageObservation:
    owned: list[torch.Tensor] = []
    for state in cache.layers:
        if not isinstance(state, DynamicLayer):
            raise ValueError("Observer requires maintained DynamicLayer")
        owned.extend(
            tensor for tensor in (state.keys, state.values) if tensor is not None
        )
    current = list(returned or ())
    return StorageObservation(
        layer,
        storage_bytes(owned),
        sum(tensor.numel() * tensor.element_size() for tensor in current),
        storage_bytes(
            [*owned, *current, *(tensor for pair in seeds for tensor in pair)]
        ),
    )


type Observer = Callable[[StorageObservation], None]


class ObservedRetained(DynamicCache):
    """Intrusive memory-cycle owner only; ordinary calls use stock DynamicCache."""

    def __init__(
        self,
        config: Qwen3Config,
        states: tuple[KVState, ...],
        seeds: tuple[KVState, ...],
        observer: Observer,
    ) -> None:
        initialize = cast(Callable[..., None], super().__init__)
        initialize(config=config, ddp_cache_data=states)
        self.seeds, self.observer = seeds, observer
        observer(observe_storage(self, seeds, None, None))

    def update(
        self,
        key_states: torch.Tensor,
        value_states: torch.Tensor,
        layer_idx: int,
        *args: object,
        **kwargs: object,
    ) -> KVState:
        update = cast(Callable[..., KVState], super().update)
        returned = update(key_states, value_states, layer_idx, *args, **kwargs)
        self.observer(observe_storage(self, self.seeds, returned, layer_idx))
        return returned


class ObservedOneUse(OneUseCache):
    """Observe after maintained concatenation and one-use reference release."""

    def __init__(
        self,
        config: Qwen3Config,
        states: tuple[KVState, ...],
        seeds: tuple[KVState, ...],
        observer: Observer,
    ) -> None:
        super().__init__(config, states)
        self.seeds, self.observer = seeds, observer
        observer(observe_storage(self, seeds, None, None))

    def update(
        self,
        key_states: torch.Tensor,
        value_states: torch.Tensor,
        layer_idx: int,
        *args: object,
        **kwargs: object,
    ) -> KVState:
        returned = super().update(key_states, value_states, layer_idx, *args, **kwargs)
        self.observer(observe_storage(self, self.seeds, returned, layer_idx))
        return returned


class MemoryScorer(PrefixScorer):
    """Both arms suppress output cache, but keep their private owner through head.

    Prefix validation, snapshots and fallback reuse the frozen prefix scorer.
    Only cache factory/layer reference lifetime differs; neither returns a cache.
    Weights/config/device/encoder stay fixed and eval for this resource lifetime.
    """

    def __init__(self, base: KaiScorer, prefix: tuple[int, ...], arm: Arm) -> None:
        if arm not in ("retained", "one-use"):
            raise ValueError("Cache arm must be retained or one-use")
        super().__init__(base, prefix)
        self.arm = arm

    def fork(self, batch_size: int) -> DynamicCache:
        if type(batch_size) is not int or batch_size < 1:
            raise ValueError("Cache batch size must be a positive integer")
        if self.arm == "retained":
            return super().fork(batch_size)
        states = tuple(
            (keys.expand(batch_size, -1, -1, -1), values.expand(batch_size, -1, -1, -1))
            for keys, values in self._states
        )
        return OneUseCache(self.base.backbone.config, states)

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        return self.score_observed(requests)

    def score_observed(
        self,
        requests: Sequence[Request],
        observer: Observer | None = None,
    ) -> list[list[float]]:
        """Observer includes only cache/returned KV/immutable seeds, not all tensors.

        It runs only in a separate intrusive memory cycle. Returned KV remains
        counted after OneUse reset; callbacks retain numbers, never tensors.
        """
        if not requests:
            return []
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self.admits(row) for row in encoded):
            return self.base.score_many(requests)
        prefix_length = len(self.prefix)
        batch_size = len(encoded)
        length = max(len(row.ids) for row in encoded) - prefix_length
        width = max(len(row.candidate_positions) for row in encoded)
        ids = torch.full((batch_size, length), self.base.pad_id, dtype=torch.long)
        endpoints = torch.zeros((batch_size, width), dtype=torch.long)
        for index, row in enumerate(encoded):
            suffix = row.ids[prefix_length:]
            ids[index, : len(suffix)] = torch.tensor(suffix, dtype=torch.long)
            endpoints[index, : len(row.candidate_positions)] = torch.tensor(
                [position - prefix_length for position in row.candidate_positions]
            )
        rows = torch.arange(batch_size)
        positions = torch.tensor(
            [row.query_position - prefix_length for row in encoded]
        )
        with torch.inference_mode():
            if observer is None:
                owner = self.fork(batch_size)
            else:
                states = tuple(
                    (
                        keys.expand(batch_size, -1, -1, -1),
                        values.expand(batch_size, -1, -1, -1),
                    )
                    for keys, values in self._states
                )
                factory = ObservedRetained if self.arm == "retained" else ObservedOneUse
                owner = factory(
                    self.base.backbone.config, states, self._states, observer
                )
            output = cast(
                BaseModelOutputWithPast,
                self.base.backbone(
                    input_ids=ids, past_key_values=owner, use_cache=False
                ),
            )
            if output.past_key_values is not None or (
                isinstance(owner, OneUseCache) and not owner.consumed
            ):
                raise ValueError(
                    "Private cache must be consumed without returned state"
                )
            hidden = output.last_hidden_state
            if hidden is None:
                raise ValueError("Kai backbone did not return suffix hidden states")
            logits = cast(
                torch.Tensor,
                self.base.head(
                    hidden[rows[:, None], endpoints], hidden[rows, positions]
                ),
            )
            values = cast(list[list[float]], logits.float().cpu().tolist())
        return [
            row[: len(item.candidate_positions)]
            for row, item in zip(values, encoded, strict=True)
        ]

"""One packed allocation shared by separate, KV and QKV linear operations."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Literal, cast

import torch
from torch.nn import functional as F

type Arm = Literal["separate", "kv", "qkv"]
type Outputs = tuple[torch.Tensor, torch.Tensor, torch.Tensor]


def require_fp32(value: torch.Tensor) -> None:
    if (
        value.device.type != "cpu"
        or value.dtype != torch.float32
        or value.requires_grad
        or torch.is_autocast_enabled("cpu")
    ):
        raise ValueError("Projection requires CPU FP32 without gradients/autocast")


@dataclass(frozen=True)
class PackedQKV:
    weight: torch.Tensor
    query_width: int
    kv_width: int

    @classmethod
    def from_weights(
        cls, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor
    ) -> PackedQKV:
        for item in (query, key, value):
            require_fp32(item)
            if item.ndim != 2 or not torch.isfinite(item).all().item():
                raise ValueError("Projection weights require finite matrices")
        if (
            key.shape != value.shape
            or query.shape[1] != key.shape[1]
            or query.shape[0] != 2 * key.shape[0]
            or min(key.shape) <= 0
        ):
            raise ValueError("Packing requires biasless Q16/KV8 width geometry")
        return cls(torch.cat((query, key, value)), query.shape[0], key.shape[0])

    @property
    def views(self) -> Outputs:
        return cast(
            Outputs,
            torch.split(self.weight, [self.query_width, self.kv_width, self.kv_width]),
        )

    def project(self, value: torch.Tensor, arm: Arm) -> Outputs:
        require_fp32(value)
        if value.ndim not in (2, 3) or value.shape[-1] != self.weight.shape[1]:
            raise ValueError("Projection input width/rank differs")
        if arm == "separate":
            query, key, values = self.views
            return F.linear(value, query), F.linear(value, key), F.linear(value, values)
        if arm == "kv":
            query = F.linear(value, self.views[0])
            key, values = torch.split(
                F.linear(value, self.weight[self.query_width :]), self.kv_width, dim=-1
            )
            return query, key, values
        if arm == "qkv":
            return cast(
                Outputs,
                torch.split(
                    F.linear(value, self.weight),
                    [self.query_width, self.kv_width, self.kv_width],
                    dim=-1,
                ),
            )
        raise ValueError("Unknown projection arm")


def quality(reference: Outputs, actual: Outputs) -> dict[str, object]:
    """Symmetric max tolerance; projection evidence is not full-model quality."""
    failures = 0
    maximum = 0.0
    relative = 0.0
    for expected, observed in zip(reference, actual, strict=True):
        require_fp32(expected)
        require_fp32(observed)
        if expected.shape != observed.shape:
            raise ValueError("Projection output geometry differs")
        # FP64 computes the gate without rounding its FP32 operands/tolerance.
        left, right = expected.double(), observed.double()
        error = (left - right).abs()
        scale = torch.maximum(left.abs(), right.abs())
        finite = torch.isfinite(left) & torch.isfinite(right)
        failures += int((~finite | (error > (scale * 1e-3).clamp_min(1e-3))).sum())
        if finite.all().item():
            maximum = max(maximum, float(error.max()))
            relative = max(relative, float((error / scale.clamp_min(1e-300)).max()))
        else:
            return {
                "passed": False,
                "finite": False,
                "failed_elements": failures,
                "max_absolute_error": None,
                "max_relative_error": None,
            }
    return {
        "passed": failures == 0,
        "finite": True,
        "failed_elements": failures,
        "max_absolute_error": maximum,
        "max_relative_error": relative,
        "atol": 1e-3,
        "rtol": 1e-3,
        "rule": "abs(a-b)<=max(atol,rtol*max(abs(a),abs(b)))",
    }

"""Independent public-payload oracle; runtime dependencies are Python stdlib only.

For acyclic monotone AND/OR expressions, the all-false and all-true completions
bound every completion of missing primitive observations. Equal bounds prove
met/violated; differing bounds establish unknown. This implementation does not
import the benchmark parser, status evaluator, transition function or planner.
"""

from __future__ import annotations

import json
import re
from collections import deque
from typing import Any

_NAME = re.compile(r"[a-z][a-z0-9_]*\Z")


def _object_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def _name(value: Any) -> str:
    if not isinstance(value, str) or _NAME.fullmatch(value) is None:
        raise ValueError("invalid identifier")
    return value


def _names(value: Any, *, empty: bool = True) -> tuple[str, ...]:
    if not isinstance(value, list) or (not empty and not value):
        raise ValueError("identifier list required")
    names = tuple(_name(item) for item in value)
    if len(set(names)) != len(names):
        raise ValueError("duplicate identifier in list")
    return names


def _fields(value: Any, expected: set[str]) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != expected:
        raise ValueError("unexpected or missing public fields")
    return value


def _parse(payload: str) -> tuple[str, dict[str, bool], list[dict[str, Any]], list[dict[str, Any]]]:
    if not isinstance(payload, str):
        raise ValueError("public JSON text required")
    try:
        raw = json.loads(payload, object_pairs_hook=_object_pairs)
    except (json.JSONDecodeError, RecursionError) as error:
        raise ValueError("invalid public JSON") from error
    raw = _fields(raw, {"goal", "facts", "rules", "actions"})
    goal = _name(raw["goal"])
    if not isinstance(raw["facts"], dict):
        raise ValueError("facts object required")
    facts = {_name(name): value for name, value in raw["facts"].items()}
    if any(type(value) is not bool for value in facts.values()):
        raise ValueError("observations must be Boolean; omit unknown observations")
    if not isinstance(raw["rules"], list) or len(raw["rules"]) > 16:
        raise ValueError("bounded rule list required")
    rules = []
    derived: set[str] = set()
    atoms = {goal, *facts}
    for item in raw["rules"]:
        item = _fields(item, {"name", "operator", "inputs"})
        name = _name(item["name"])
        if name in derived or name in facts:
            raise ValueError("duplicate or observed derived rule")
        if item["operator"] not in ("AND", "OR"):
            raise ValueError("only AND/OR rules supported")
        inputs = _names(item["inputs"], empty=False)
        derived.add(name)
        atoms.update(inputs)
        rules.append({"name": name, "operator": item["operator"], "inputs": inputs})
    if goal in derived:
        raise ValueError("goal must be primitive")
    if not isinstance(raw["actions"], list) or not 2 <= len(raw["actions"]) <= 256:
        raise ValueError("2 to 256 actions required")
    actions = []
    ids: set[str] = set()
    effects: set[str] = set()
    for item in raw["actions"]:
        item = _fields(item, {"id", "requires", "effects"})
        identifier = _name(item["id"])
        if identifier in ids:
            raise ValueError("duplicate action ID")
        ids.add(identifier)
        requires = _names(item["requires"])
        produced = _names(item["effects"], empty=False)
        if any(name in derived or facts.get(name) is False for name in produced):
            raise ValueError("effects cannot write derived or immutable false observations")
        atoms.update(requires)
        atoms.update(produced)
        effects.update(produced)
        actions.append({"id": identifier, "requires": requires, "effects": produced})
    if len(atoms - derived) > 16 or len(effects) > 12:
        raise ValueError("world exceeds primitive or effect bounds")
    # Resolve an independent topological order; forward declarations are permitted.
    ordered = []
    pending = rules[:]
    resolved: set[str] = set()
    while pending:
        ready = [item for item in pending if not (set(item["inputs"]) & derived) - resolved]
        if not ready:
            raise ValueError("cyclic rules")
        for item in ready:
            ordered.append(item)
            resolved.add(item["name"])
            pending.remove(item)
    return goal, facts, ordered, actions


def audit_public(payload: str) -> dict[str, Any]:
    """Audit every reachable state from a strict public JSON problem.

    State transitions include every valid action, including no-ops. Unknown and
    violated requirements both block execution. Distances count unit-cost
    actions; terminal states have distance zero and no optimal next actions.
    """
    goal, initial, rules, actions = _parse(payload)
    derived = {item["name"] for item in rules}
    atoms = {goal, *initial}
    for rule in rules:
        atoms.update(rule["inputs"])
    for action in actions:
        atoms.update(action["requires"])
        atoms.update(action["effects"])
    primitive = atoms - derived

    def bounds(facts: dict[str, bool]) -> tuple[dict[str, bool], dict[str, bool]]:
        completed = []
        for missing in (False, True):
            values = {name: missing for name in primitive}
            values.update(facts)
            for rule in rules:
                children = [values[name] for name in rule["inputs"]]
                values[rule["name"]] = all(children) if rule["operator"] == "AND" else any(children)
            completed.append(values)
        return completed[0], completed[1]

    def state_key(facts: dict[str, bool]) -> tuple[tuple[str, bool], ...]:
        return tuple(sorted(facts.items()))

    first = state_key(initial)
    pending = deque([first])
    observations = {first: dict(first)}
    statuses: dict[tuple[tuple[str, bool], ...], dict[str, str]] = {}
    edges: dict[tuple[tuple[str, bool], ...], dict[str, tuple[tuple[str, bool], ...]]] = {}
    predecessors: dict[tuple[tuple[str, bool], ...], set[tuple[tuple[str, bool], ...]]] = {}
    terminals = []
    while pending:
        key = pending.popleft()
        facts = observations[key]
        lower, upper = bounds(facts)
        if lower[goal]:
            terminals.append(key)
        statuses[key] = {}
        edges[key] = {}
        for action in actions:
            lo = all(lower[name] for name in action["requires"])
            hi = all(upper[name] for name in action["requires"])
            label = "met" if lo else "violated" if not hi else "unknown"
            statuses[key][action["id"]] = label
            if label != "met":
                continue
            following = {**facts, **dict.fromkeys(action["effects"], True)}
            next_key = state_key(following)
            edges[key][action["id"]] = next_key
            predecessors.setdefault(next_key, set()).add(key)
            if next_key not in observations:
                observations[next_key] = following
                pending.append(next_key)
    distances = dict.fromkeys(terminals, 0)
    pending = deque(terminals)
    while pending:
        target = pending.popleft()
        for prior in sorted(predecessors.get(target, set())):
            if prior not in distances:
                distances[prior] = distances[target] + 1
                pending.append(prior)
    states = []
    for key in sorted(observations):
        distance = distances.get(key)
        optimal = sorted(
            identifier
            for identifier, following in edges[key].items()
            if distance is not None and distance > 0 and distances.get(following) == distance - 1
        )
        states.append(
            {
                "facts": dict(key),
                "labels": dict(sorted(statuses[key].items())),
                "distance": distance,
                "optimal": optimal,
                "transitions": {
                    identifier: dict(following)
                    for identifier, following in sorted(edges[key].items())
                },
            }
        )
    initial_state = next(state for state in states if state["facts"] == initial)
    return {
        "labels": initial_state["labels"],
        "distance": initial_state["distance"],
        "optimal": initial_state["optimal"],
        "reachable_states": len(states),
        "states": states,
    }

"""Candidate-width diagnostics that retain the original reachable state graph."""

from __future__ import annotations

import hashlib
from collections.abc import Callable
from typing import cast

from .audit import audit_public
from .core import World, validate_world
from .generate import expand_candidates
from .render import payload, render


def width_profile(
    world: World,
    widths: tuple[int, ...] = (16, 32, 64, 128, 256),
    token_length: Callable[[str], int] | None = None,
) -> list[dict[str, object]]:
    """Audit duplicate-candidate expansion independently, without model inference.

    The optional counter receives the rendered action prompt only. Its result
    does not establish the token count of an adapter's native candidate framing.
    Widths must retain every original action and stay within the safety bound.
    """
    validate_world(world)
    if (
        not isinstance(widths, tuple)
        or not widths
        or any(type(width) is not int for width in widths)
        or len(set(widths)) != len(widths)
    ):
        raise ValueError("nonempty unique integer widths required")
    original = audit_public(payload(world, tuple(action.id for action in world.actions)))
    original_states = {tuple(sorted(state["facts"].items())): state for state in original["states"]}
    result: list[dict[str, object]] = []
    for width in widths:
        expanded = expand_candidates(world, width)
        public = payload(expanded, tuple(action.id for action in expanded.actions))
        audited = audit_public(public)
        states = {tuple(sorted(state["facts"].items())): state for state in audited["states"]}
        if states.keys() != original_states.keys():
            raise ValueError("candidate expansion changed reachable fact states")
        for key, baseline in original_states.items():
            current = states[key]
            if current["distance"] != baseline["distance"]:
                raise ValueError("candidate expansion changed shortest distances")
            if set(current["optimal"]) & {action.id for action in world.actions} != set(
                baseline["optimal"]
            ):
                raise ValueError("candidate expansion changed original optimal actions")
            # Every additional optimal action must replicate an optimal original
            # requirement/effect signature in this exact state.
            actions = {action.id: action for action in expanded.actions}
            signatures = {
                (tuple(sorted(actions[name].requires)), tuple(sorted(actions[name].effects)))
                for name in baseline["optimal"]
            }
            if any(
                (tuple(sorted(actions[name].requires)), tuple(sorted(actions[name].effects)))
                not in signatures
                for name in current["optimal"]
            ):
                raise ValueError("candidate expansion introduced a distinct optimal operation")
        prompt = render(public, "action")
        effects = {name for action in expanded.actions for name in action.effects}
        optimal = cast(list[str], audited["optimal"])
        row: dict[str, object] = {
            "candidate_count": len(expanded.actions),
            "distinct_requirement_effect_signatures": len(
                {
                    (tuple(sorted(action.requires)), tuple(sorted(action.effects)))
                    for action in expanded.actions
                }
            ),
            "reachable_states": audited["reachable_states"],
            "theoretical_state_bound": 2 ** len(effects),
            "shortest_distance": audited["distance"],
            "optimal_count": len(optimal),
            "uniform_random_expected_action_accuracy": len(optimal) / len(expanded.actions),
            "prompt_characters": len(prompt),
            "input_sha256": hashlib.sha256(prompt.encode("utf-8")).hexdigest(),
        }
        if token_length is not None:
            tokens = token_length(prompt)
            if type(tokens) is not int or tokens < 0:
                raise ValueError("token counter must return a nonnegative integer")
            row["model_input_tokens"] = tokens
            row["token_count_scope"] = "rendered action prompt; native adapter framing excluded"
        result.append(row)
    return result

"""Bounded deterministic worlds with public three-valued prerequisites."""

from __future__ import annotations

import re
from collections import deque
from dataclasses import dataclass, replace

_IDENTIFIER = re.compile(r"[a-z][a-z0-9_]*\Z")


@dataclass(frozen=True)
class Rule:
    name: str
    operator: str
    inputs: tuple[str, ...]


@dataclass(frozen=True)
class Action:
    id: str
    requires: tuple[str, ...]
    effects: tuple[str, ...]


@dataclass(frozen=True)
class World:
    goal: str
    facts: tuple[tuple[str, bool], ...]
    rules: tuple[Rule, ...]
    actions: tuple[Action, ...]


def _identifier(value: object) -> None:
    if not isinstance(value, str) or _IDENTIFIER.fullmatch(value) is None:
        raise ValueError("Identifiers must match [a-z][a-z0-9_]*")


def _references(values: object, description: str, *, nonempty: bool = False) -> None:
    if not isinstance(values, tuple):
        raise ValueError(f"{description} must be a tuple")
    for value in values:
        _identifier(value)
    if len(values) != len(set(values)):
        raise ValueError(f"Duplicate {description}")
    if nonempty and not values:
        raise ValueError(f"{description} must be nonempty")


def validate_world(world: World) -> None:
    """Reject ambiguous, nonmonotone, cyclic or excessively large worlds."""
    if not isinstance(world, World):
        raise ValueError("World required")
    _identifier(world.goal)
    if not all(isinstance(value, tuple) for value in (world.facts, world.rules, world.actions)):
        raise ValueError("World collections must be tuples")
    if not 2 <= len(world.actions) <= 256:
        raise ValueError("Worlds require two to 256 actions")
    if len(world.rules) > 16:
        raise ValueError("Worlds support at most sixteen rules")
    observations: dict[str, bool] = {}
    for observation in world.facts:
        if not isinstance(observation, tuple) or len(observation) != 2:
            raise ValueError("Facts must be (name, bool) pairs")
        name, value = observation
        _identifier(name)
        if type(value) is not bool or name in observations:
            raise ValueError("Facts require unique names and Boolean values")
        observations[name] = value
    definitions: dict[str, Rule] = {}
    for rule in world.rules:
        if not isinstance(rule, Rule):
            raise ValueError("Rule required")
        _identifier(rule.name)
        if rule.operator not in ("AND", "OR"):
            raise ValueError("Rules support only AND and OR")
        _references(rule.inputs, "rule inputs", nonempty=True)
        if rule.name in definitions or rule.name in observations:
            raise ValueError("Derived names must be unique and cannot be observed")
        definitions[rule.name] = rule
    if world.goal in definitions:
        raise ValueError("Goal must be primitive")
    effects: set[str] = set()
    action_ids: set[str] = set()
    primitives = {world.goal, *observations}
    for rule in world.rules:
        primitives.update(rule.inputs)
    for action in world.actions:
        if not isinstance(action, Action):
            raise ValueError("Action required")
        _identifier(action.id)
        if action.id in action_ids:
            raise ValueError("Duplicate action IDs")
        action_ids.add(action.id)
        _references(action.requires, "action requirements")
        _references(action.effects, "action effects", nonempty=True)
        if any(name in definitions for name in action.effects):
            raise ValueError("Effects must be primitive")
        if any(observations.get(name) is False for name in action.effects):
            raise ValueError("Effects cannot contradict immutable false observations")
        effects.update(action.effects)
        primitives.update(action.requires)
        primitives.update(action.effects)
    primitives.difference_update(definitions)
    if len(primitives) > 16 or len(effects) > 12:
        raise ValueError("World exceeds sixteen primitive or twelve effect atoms")
    visiting: set[str] = set()
    complete: set[str] = set()

    def visit(name: str) -> None:
        if name in visiting:
            raise ValueError("Cyclic rule definitions")
        if name in complete or name not in definitions:
            return
        visiting.add(name)
        for child in definitions[name].inputs:
            visit(child)
        visiting.remove(name)
        complete.add(name)

    for name in definitions:
        visit(name)


def _conjunction(values: list[bool | None]) -> bool | None:
    if any(value is False for value in values):
        return False
    return None if any(value is None for value in values) else True


def _status(world: World, action: Action) -> str:
    values: dict[str, bool | None] = dict(world.facts)
    rules = {rule.name: rule for rule in world.rules}

    def evaluate(name: str) -> bool | None:
        if name not in values:
            rule = rules.get(name)
            if rule is None:
                values[name] = None
            else:
                children = [evaluate(child) for child in rule.inputs]
                if rule.operator == "AND":
                    values[name] = _conjunction(children)
                elif any(child is True for child in children):
                    values[name] = True
                else:
                    values[name] = None if any(child is None for child in children) else False
        return values[name]

    result = _conjunction([evaluate(name) for name in action.requires])
    return "met" if result is True else "violated" if result is False else "unknown"


def _action(world: World, action_id: str) -> Action:
    for action in world.actions:
        if action.id == action_id:
            return action
    raise ValueError(f"Unknown action ID: {action_id}")


def requirements_status(world: World, action_id: str) -> str:
    validate_world(world)
    return _status(world, _action(world, action_id))


def all_requirements_status(world: World) -> dict[str, str]:
    """Judge the full candidate catalog with one validation of the shared world."""
    validate_world(world)
    return {action.id: _status(world, action) for action in world.actions}


def _transition(world: World, action: Action) -> World:
    observations = dict(world.facts)
    observations.update((name, True) for name in action.effects)
    return replace(world, facts=tuple(sorted(observations.items())))


def transition(world: World, action_id: str) -> World:
    """Apply a permitted positive effect; invalid attempts are the runner's concern."""
    validate_world(world)
    action = _action(world, action_id)
    if _status(world, action) != "met":
        raise ValueError("Action requirements are not met")
    return _transition(world, action)


def all_transitions(world: World) -> dict[str, World]:
    """Return every permitted edge, including no-ops, validating the catalog once."""
    validate_world(world)
    return {
        action.id: _transition(world, action)
        for action in world.actions
        if _status(world, action) == "met"
    }


def _distance(world: World) -> int | None:
    initial = replace(world, facts=tuple(sorted(world.facts)))
    pending = deque([(initial, 0)])
    visited = {initial.facts}
    while pending:
        current, distance = pending.popleft()
        if dict(current.facts).get(current.goal) is True:
            return distance
        for action in current.actions:
            if _status(current, action) != "met":
                continue
            following = _transition(current, action)
            if following.facts not in visited:
                visited.add(following.facts)
                pending.append((following, distance + 1))
    return None


def shortest_distance(world: World) -> int | None:
    validate_world(world)
    return _distance(world)


def optimal_actions(world: World) -> tuple[str, ...]:
    """All first actions of shortest unit-cost plans; no arbitrary tie breaking."""
    validate_world(world)
    distance = _distance(world)
    if distance is None:
        raise ValueError("Goal is unreachable")
    if distance == 0:
        return ()
    # Many candidates can describe the same state transition. Solve each
    # successor once locally, while crediting every action on a shortest plan.
    distances: dict[tuple[tuple[str, bool], ...], int | None] = {
        tuple(sorted(world.facts)): distance
    }
    optimal = []
    for action in world.actions:
        if _status(world, action) != "met":
            continue
        following = _transition(world, action)
        if following.facts not in distances:
            distances[following.facts] = _distance(following)
        if distances[following.facts] == distance - 1:
            optimal.append(action.id)
    return tuple(sorted(optimal))


def world_to_dict(world: World) -> dict[str, object]:
    validate_world(world)
    return {
        "goal": world.goal,
        "facts": dict(world.facts),
        "rules": [
            {"name": rule.name, "operator": rule.operator, "inputs": list(rule.inputs)}
            for rule in world.rules
        ],
        "actions": [
            {"id": action.id, "requires": list(action.requires), "effects": list(action.effects)}
            for action in world.actions
        ],
    }


def _object(value: object, fields: set[str]) -> dict[str, object]:
    if not isinstance(value, dict) or set(value) != fields:
        raise ValueError("Unexpected object shape")
    return {name: item for name, item in value.items()}


def _strings(value: object) -> tuple[str, ...]:
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise ValueError("Expected a JSON array of strings")
    return tuple(value)


def world_from_dict(value: object) -> World:
    """Decode the exact public JSON shape; semantic validation follows decoding."""
    item = _object(value, {"goal", "facts", "rules", "actions"})
    goal, raw_facts = item["goal"], item["facts"]
    if not isinstance(goal, str) or not isinstance(raw_facts, dict):
        raise ValueError("Expected string goal and object facts")
    facts: list[tuple[str, bool]] = []
    for name, observed in raw_facts.items():
        if not isinstance(name, str) or type(observed) is not bool:
            raise ValueError("Facts must map strings to Boolean values")
        facts.append((name, observed))
    raw_rules, raw_actions = item["rules"], item["actions"]
    if not isinstance(raw_rules, list) or not isinstance(raw_actions, list):
        raise ValueError("Rules and actions must be JSON arrays")
    rules = []
    for raw in raw_rules:
        rule = _object(raw, {"name", "operator", "inputs"})
        name, operator = rule["name"], rule["operator"]
        if not isinstance(name, str) or not isinstance(operator, str):
            raise ValueError("Rule name and operator must be strings")
        rules.append(Rule(name, operator, _strings(rule["inputs"])))
    actions = []
    for raw in raw_actions:
        action = _object(raw, {"id", "requires", "effects"})
        identifier = action["id"]
        if not isinstance(identifier, str):
            raise ValueError("Action ID must be a string")
        actions.append(
            Action(identifier, _strings(action["requires"]), _strings(action["effects"]))
        )
    world = World(goal, tuple(facts), tuple(rules), tuple(actions))
    validate_world(world)
    return world

"""Frozen complete-family fixtures, integrity checks and independent reachable-state audits."""

import hashlib
import json
from collections import Counter
from pathlib import Path
from typing import cast

from . import VERSION
from .audit import audit_public
from .core import (
    World,
    all_requirements_status,
    all_transitions,
    optimal_actions,
    shortest_distance,
    world_from_dict,
    world_to_dict,
)
from .generate import generate_families
from .render import canonical, payload, renamed, render


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def semantic_identity(world: World) -> str:
    """Ignore display/order differences while retaining all supplied identifier meanings."""
    value = world_to_dict(world)
    value["rules"] = sorted(
        ({"name": r.name, "operator": r.operator, "inputs": sorted(r.inputs)} for r in world.rules),
        key=lambda r: str(r["name"]),
    )
    value["actions"] = sorted(
        (
            {"id": a.id, "requires": sorted(a.requires), "effects": sorted(a.effects)}
            for a in world.actions
        ),
        key=lambda a: str(a["id"]),
    )
    return digest(canonical(value).encode())


def _named_world_coverage(cases: list[dict[str, object]]) -> int:
    partitions: dict[str, str] = {}
    for case in cases:
        if case["presentation"] == "renamed":
            continue
        identity = semantic_identity(world_from_dict(case["world"]))
        split = str(case["split"])
        if partitions.setdefault(identity, split) != split:
            raise ValueError("exact supplied world crosses splits")
    return len(partitions)


def object_record(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or not all(isinstance(k, str) for k in value):
        raise ValueError("expected string-keyed object")
    return cast(dict[str, object], value)


def decode(text: str) -> object:
    def pairs(items: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, value in items:
            if key in result:
                raise ValueError("duplicate JSON key")
            result[key] = value
        return result

    def constant(value: str) -> object:
        raise ValueError("nonfinite JSON value: " + value)

    return cast(object, json.loads(text, object_pairs_hook=pairs, parse_constant=constant))


def records(path: Path) -> list[dict[str, object]]:
    return [object_record(decode(line)) for line in path.read_text().splitlines() if line]


def _audit(world: World, public: str) -> dict[str, object]:
    result = audit_public(public)
    expected = all_requirements_status(world)
    if result["labels"] != expected or result["optimal"] != list(optimal_actions(world)):
        raise ValueError("independent initial oracle disagreement")
    states = cast(list[dict[str, object]], result["states"])
    for state in states:
        facts = object_record(state["facts"])
        item = world_to_dict(world)
        item["facts"] = facts
        current = world_from_dict(item)
        labels = all_requirements_status(current)
        if (
            labels != state["labels"]
            or list(optimal_actions(current)) != state["optimal"]
            or shortest_distance(current) != state["distance"]
        ):
            raise ValueError("independent reachable-state oracle disagreement")
        observed = {
            name: dict(successor.facts) for name, successor in all_transitions(current).items()
        }
        if observed != state["transitions"]:
            raise ValueError("independent transition disagreement")
    return result


def _check_intervention(left: World, right: World, kind: str) -> None:
    a, b = world_to_dict(left), world_to_dict(right)
    allowed = "rules" if kind == "rule" else "facts" if kind == "fact" else ""
    if not allowed or a[allowed] == b[allowed]:
        raise ValueError("intervention must change its declared field")
    if {k: v for k, v in a.items() if k != allowed} != {k: v for k, v in b.items() if k != allowed}:
        raise ValueError("intervention changed an undeclared field")


def build(directory: Path, seed: int = 17, families_per_split: int = 64) -> dict[str, object]:
    if directory.exists():
        raise ValueError("release output already exists")
    families = generate_families(seed, families_per_split)
    cases: list[dict[str, object]] = []
    queries: list[dict[str, object]] = []
    declared: list[dict[str, object]] = []
    total_states = 0
    audit_cache: dict[str, dict[str, object]] = {}
    for family in families:
        source_cases = cast(list[dict[str, object]], family["cases"])
        source_by_id = {str(c["case_id"]): cast(World, c["world"]) for c in source_cases}
        pair_source = cast(list[dict[str, str]], family["pairs"])
        for pair in pair_source:
            _check_intervention(
                source_by_id[pair["left"]], source_by_id[pair["right"]], pair["kind"]
            )
        members = []
        pairs = []
        presentations = (
            ("compact",)
            if family["split"] == "train"
            else ("compact", "wording", "layout", "renamed")
        )
        expanded_cases = [
            {
                **source,
                "presentation": style,
                "world": renamed(cast(World, source["world"]))
                if style == "renamed"
                else source["world"],
            }
            for source in source_cases
            for style in presentations
        ]
        for source in expanded_cases:
            world = cast(World, source["world"])
            style = str(source["presentation"])
            ids = tuple(a.id for a in world.actions)
            menus = (ids, ids[1:] + ids[:1])
            for menu_index, order in enumerate(menus):
                case_id = str(source["case_id"]) + f"/{style}/menu-{menu_index}"
                public = payload(world, order, style)
                key = digest(public.encode())
                if key not in audit_cache:
                    checked = _audit(world, public)
                    audit_cache[key] = {
                        name: value for name, value in checked.items() if name != "states"
                    }
                audit = audit_cache[key]
                if audit["distance"] is None or audit["distance"] == 0:
                    raise ValueError("release requires reachable nonterminal cases")
                total_states += int(cast(int, audit["reachable_states"]))
                query_ids = [case_id + "/" + task for task in ("judgment", "action")]
                for task, query_id in zip(("judgment", "action"), query_ids, strict=True):
                    queries.append(
                        {"id": query_id, "task": task, "text": render(public, task, style)}
                    )
                cases.append(
                    {
                        "id": case_id,
                        "family_id": family["family_id"],
                        "split": family["split"],
                        "condition": family["condition"],
                        "structure": family["structure"],
                        "domain": family["domain"],
                        "variant": source["variant"],
                        "menu": menu_index,
                        "presentation": style,
                        "world": world_to_dict(world),
                        "public_world": public,
                        "query_ids": query_ids,
                        "world_sha256": digest(canonical(world_to_dict(world)).encode()),
                        "labels": audit["labels"],
                        "optimal": audit["optimal"],
                        "distance": audit["distance"],
                        "reachable_states": audit["reachable_states"],
                        "budget": cast(int, audit["distance"]) + 4,
                    }
                )
                members.append(case_id)
        for pair in pair_source:
            for style in presentations:
                for menu_index in range(2):
                    pairs.append(
                        {
                            "kind": pair["kind"],
                            "left": pair["left"] + f"/{style}/menu-{menu_index}",
                            "right": pair["right"] + f"/{style}/menu-{menu_index}",
                        }
                    )
        declared.append(
            {
                "id": family["family_id"],
                "split": family["split"],
                "members": members,
                "pairs": pairs,
            }
        )
    directory.mkdir(parents=True)
    for filename, rows in (("cases.jsonl", cases), ("questions.jsonl", queries)):
        with (directory / filename).open("x", encoding="utf-8", newline="\n") as file:
            file.write("".join(canonical(row) + "\n" for row in rows))
    source = {p.name: digest(p.read_bytes()) for p in sorted(Path(__file__).parent.glob("*.py"))}
    manifest: dict[str, object] = {
        "benchmark": "decision-model-benchmark",
        "version": VERSION,
        "schema_version": 1,
        "semantics_version": 1,
        "scoring_version": 1,
        "rendering_version": 1,
        "config": {"seed": seed, "families_per_split": families_per_split},
        "source_sha256": source,
        "families": declared,
        "queries": [q["id"] for q in queries],
        "files_sha256": {
            name: digest((directory / name).read_bytes())
            for name in ("cases.jsonl", "questions.jsonl")
        },
        "coverage": {
            "families": len(families),
            "cases": len(cases),
            "queries": len(queries),
            "splits": dict(Counter(str(f["split"]) for f in families)),
            "motifs": dict(Counter(str(f["structure"]) for f in families)),
            "domains": dict(Counter(str(f["domain"]) for f in families)),
            "presentations": dict(Counter(str(c["presentation"]) for c in cases)),
            "action_counts": dict(
                Counter(str(len(cast(dict[str, object], c["labels"]))) for c in cases)
            ),
            "distances": dict(Counter(str(c["distance"]) for c in cases)),
            "optimal_set_sizes": dict(
                Counter(str(len(cast(list[str], c["optimal"]))) for c in cases)
            ),
            "labels": dict(
                Counter(
                    str(label)
                    for c in cases
                    for label in cast(dict[str, str], c["labels"]).values()
                )
            ),
            "audited_state_presentations": total_states,
            "unique_named_worlds": _named_world_coverage(cases),
        },
        "limits": [
            "Template-generated controlled worlds; domain names are vocabulary transfer.",
            "Held-out full motifs do not imply every internal subgraph is unseen.",
            "Published evaluation is public development evidence, not hidden confirmation.",
            "Positive deterministic effects, immutable false observations, no hidden outcomes.",
        ],
    }
    manifest["release_id"] = digest(canonical(manifest).encode())
    with (directory / "manifest.json").open("x", encoding="utf-8", newline="\n") as file:
        file.write(canonical(manifest) + "\n")
    verify(directory)
    return manifest


def verify(directory: Path, independent: bool = False) -> dict[str, object]:
    manifest = object_record(decode((directory / "manifest.json").read_text()))
    if manifest.get("version") != VERSION or any(
        type(manifest.get(k)) is not int or manifest.get(k) != 1
        for k in ("schema_version", "semantics_version", "scoring_version", "rendering_version")
    ):
        raise ValueError("unsupported release version")
    claimed = manifest.pop("release_id", None)
    if claimed != digest(canonical(manifest).encode()):
        raise ValueError("release identity mismatch")
    manifest["release_id"] = claimed
    files = object_record(manifest.get("files_sha256"))
    if set(files) != {"cases.jsonl", "questions.jsonl"}:
        raise ValueError("release requires exact fixture file set")
    if {p.name for p in directory.glob("*.jsonl")} != set(files):
        raise ValueError("unregistered fixture file")
    for name, expected in files.items():
        if digest((directory / name).read_bytes()) != expected:
            raise ValueError("fixture hash mismatch")
    if object_record(manifest.get("source_sha256")) != {
        p.name: digest(p.read_bytes()) for p in sorted(Path(__file__).parent.glob("*.py"))
    }:
        raise ValueError("benchmark source differs; declare a fork/release instead")
    cases, queries = records(directory / "cases.jsonl"), records(directory / "questions.jsonl")
    case_by_id = {str(c["id"]): c for c in cases}
    query_by_id = {str(q["id"]): q for q in queries}
    if len(case_by_id) != len(cases) or len(query_by_id) != len(queries):
        raise ValueError("duplicate fixture ID")
    if [q["id"] for q in queries] != manifest.get("queries"):
        raise ValueError("query membership mismatch")
    expected_cases: set[str] = set()
    families = cast(list[dict[str, object]], manifest["families"])
    config = object_record(manifest["config"])
    expected_families = generate_families(
        cast(int, config["seed"]), cast(int, config["families_per_split"])
    )
    if [f["id"] for f in families] != [f["family_id"] for f in expected_families]:
        raise ValueError("family population differs from generation configuration")
    for actual, expected in zip(families, expected_families, strict=True):
        styles = (
            ("compact",)
            if expected["split"] == "train"
            else ("compact", "wording", "layout", "renamed")
        )
        sources = cast(list[dict[str, object]], expected["cases"])
        expected_members = [
            str(c["case_id"]) + f"/{style}/menu-{menu}"
            for c in sources
            for style in styles
            for menu in range(2)
        ]
        if actual["members"] != expected_members:
            raise ValueError("family coverage differs from generation configuration")
        expected_pairs = [
            {
                "kind": p["kind"],
                "left": p["left"] + f"/{style}/menu-{menu}",
                "right": p["right"] + f"/{style}/menu-{menu}",
            }
            for p in cast(list[dict[str, str]], expected["pairs"])
            for style in styles
            for menu in range(2)
        ]
        if actual["pairs"] != expected_pairs:
            raise ValueError("pair coverage differs from generation configuration")
        for source in sources:
            for style in styles:
                expected_world = (
                    renamed(cast(World, source["world"]))
                    if style == "renamed"
                    else cast(World, source["world"])
                )
                ids = tuple(a.id for a in expected_world.actions)
                for menu in range(2):
                    name = str(source["case_id"]) + f"/{style}/menu-{menu}"
                    if name not in case_by_id:
                        raise ValueError("missing generated case")
                    case = case_by_id[name]
                    fields = {
                        "family_id": expected["family_id"],
                        "split": expected["split"],
                        "condition": expected["condition"],
                        "structure": expected["structure"],
                        "domain": expected["domain"],
                        "variant": source["variant"],
                        "menu": menu,
                        "presentation": style,
                        "query_ids": [name + "/judgment", name + "/action"],
                        "world": world_to_dict(expected_world),
                        "world_sha256": digest(canonical(world_to_dict(expected_world)).encode()),
                        "public_world": payload(
                            expected_world, ids if menu == 0 else ids[1:] + ids[:1], style
                        ),
                    }
                    if any(case.get(k) != value for k, value in fields.items()):
                        raise ValueError("case differs from exact generation configuration")
    if len({f["id"] for f in families}) != len(families):
        raise ValueError("duplicate family declaration")
    for family in families:
        members = cast(list[str], family["members"])
        if len(set(members)) != len(members) or expected_cases.intersection(members):
            raise ValueError("duplicate family member")
        expected_cases.update(members)
        for name in members:
            if name not in case_by_id:
                raise ValueError("missing declared family member")
            case = case_by_id[name]
            if case["family_id"] != family["id"] or case["split"] != family["split"]:
                raise ValueError("family crosses split or identity")
        for pair in cast(list[dict[str, str]], family["pairs"]):
            if pair["left"] not in members or pair["right"] not in members:
                raise ValueError("pair endpoint outside family")
            a, b = case_by_id[pair["left"]], case_by_id[pair["right"]]
            _check_intervention(
                world_from_dict(a["world"]), world_from_dict(b["world"]), pair["kind"]
            )
            if [
                x["id"]
                for x in cast(
                    list[dict[str, object]], json.loads(str(a["public_world"]))["actions"]
                )
            ] != [
                x["id"]
                for x in cast(
                    list[dict[str, object]], json.loads(str(b["public_world"]))["actions"]
                )
            ]:
                raise ValueError("pair changed menu")
    if expected_cases != set(case_by_id):
        raise ValueError("case population differs from declared families")
    expected_order = [name for family in families for name in cast(list[str], family["members"])]
    if [c["id"] for c in cases] != expected_order or [q["id"] for q in queries] != [
        name + "/" + task for name in expected_order for task in ("judgment", "action")
    ]:
        raise ValueError("fixture ordering differs from generation configuration")
    observed_queries: set[str] = set()
    for case in cases:
        world = world_from_dict(case["world"])
        public = str(case["public_world"])
        order = tuple(a["id"] for a in cast(list[dict[str, str]], json.loads(public)["actions"]))
        style = str(case["presentation"])
        if public != payload(world, order, style):
            raise ValueError("public rendering differs from world")
        for task, query_id in zip(
            ("judgment", "action"), cast(list[str], case["query_ids"]), strict=True
        ):
            observed_queries.add(query_id)
            if query_by_id.get(query_id) != {
                "id": query_id,
                "task": task,
                "text": render(public, task, style),
            }:
                raise ValueError("query rendering mismatch")
        labels = all_requirements_status(world)
        if labels != case["labels"] or list(optimal_actions(world)) != case["optimal"]:
            raise ValueError("reference answer mismatch")
        if (
            shortest_distance(world) != case["distance"]
            or case["budget"] != cast(int, case["distance"]) + 4
        ):
            raise ValueError("distance/budget mismatch")
        if independent:
            result = _audit(world, public)
            if result["distance"] != case["distance"]:
                raise ValueError("independent distance mismatch")
            if result["reachable_states"] != case["reachable_states"]:
                raise ValueError("independent state coverage mismatch")
    if observed_queries != set(query_by_id):
        raise ValueError("unexpected query population")
    coverage = {
        "families": len(families),
        "cases": len(cases),
        "queries": len(queries),
        "splits": dict(Counter(str(f["split"]) for f in families)),
        "motifs": dict(Counter(str(f["structure"]) for f in expected_families)),
        "domains": dict(Counter(str(f["domain"]) for f in expected_families)),
        "presentations": dict(Counter(str(c["presentation"]) for c in cases)),
        "action_counts": dict(
            Counter(str(len(cast(dict[str, object], c["labels"]))) for c in cases)
        ),
        "distances": dict(Counter(str(c["distance"]) for c in cases)),
        "optimal_set_sizes": dict(Counter(str(len(cast(list[str], c["optimal"]))) for c in cases)),
        "labels": dict(
            Counter(
                str(label) for c in cases for label in cast(dict[str, str], c["labels"]).values()
            )
        ),
        "audited_state_presentations": sum(cast(int, c["reachable_states"]) for c in cases),
        "unique_named_worlds": _named_world_coverage(cases),
    }
    if manifest.get("coverage") != coverage:
        raise ValueError("coverage metadata mismatch")
    return manifest

"""Public-input reference controls, not trained model quality evidence."""

import json

from .core import all_requirements_status, optimal_actions, world_from_dict
from .dataset import object_record


def control(query: dict[str, object], policy: str = "symbolic") -> object:
    public = str(query["text"]).split("\nWORLD_JSON\n", 1)[1]
    world = world_from_dict(json.loads(public))
    if policy == "symbolic":
        if query["task"] == "judgment":
            return all_requirements_status(world)
        return optimal_actions(world)[0]
    if policy == "first":
        return (
            {a.id: "met" for a in world.actions}
            if query["task"] == "judgment"
            else world.actions[0].id
        )
    if policy == "goal_overlap":
        if query["task"] == "judgment":
            return {a.id: "met" for a in world.actions}
        return next(a.id for a in world.actions if world.goal in a.effects)
    if policy == "facts_only":
        facts = dict(world.facts)
        labels = {}
        for action in world.actions:
            values = [facts.get(name) for name in action.requires]
            labels[action.id] = (
                "violated" if False in values else "unknown" if None in values else "met"
            )
        if query["task"] == "judgment":
            return labels
        eligible = [a for a in world.actions if labels[a.id] == "met"]
        return next(
            (a.id for a in eligible if world.goal in a.effects),
            eligible[0].id if eligible else world.actions[0].id,
        )
    raise ValueError("unknown control policy")


def validate_query(query: object) -> dict[str, object]:
    record = object_record(query)
    if set(record) != {"id", "task", "text"}:
        raise ValueError("engine input contains unexpected metadata")
    if record["task"] not in ("judgment", "action") or not isinstance(record["text"], str):
        raise ValueError("invalid public query")
    return record

"""Versioned public prompts; reference answers and family metadata stay outside inference."""

import hashlib
import json

from .core import Action, Rule, World, world_to_dict

PREAMBLE = (
    "Use only the supplied world. Missing primitive facts are unknown, not false. "
    "AND is violated if any input is false, otherwise unknown if any is unknown. "
    "OR is met if any input is true, otherwise unknown if any is unknown. "
    "An action is executable only when all its requirements are met. "
    "Empty requirements are met. Executable actions add their positive effects. "
    "False observations remain fixed. All attempted actions cost one step; "
    "invalid actions preserve state and no-ops still cost a step. "
    "The full action catalog remains available. Stop when the goal is true."
)


def canonical(value: object) -> str:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False
    )


def payload(world: World, order: tuple[str, ...], presentation: str = "compact") -> str:
    value = world_to_dict(world)
    if len(order) != len(world.actions) or set(order) != {a.id for a in world.actions}:
        raise ValueError("menu must contain every action exactly once")
    actions = {
        a.id: {"id": a.id, "requires": list(a.requires), "effects": list(a.effects)}
        for a in world.actions
    }
    value["actions"] = [actions[name] for name in order]
    if presentation == "layout":
        return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=True)
    return canonical(value)


def render(public_world: str, task: str, presentation: str = "compact") -> str:
    if task == "judgment":
        question = (
            "Judge the supplied requirements of EVERY action. Return only a JSON object "
            "mapping each action ID to one of: met, violated, unknown."
        )
    elif task == "action":
        question = (
            "Choose one action that starts a shortest plan to the goal. "
            "Every equally short route is accepted. Return only the action ID."
        )
    else:
        raise ValueError("unknown task")
    preamble = PREAMBLE
    if presentation == "wording":
        preamble = (
            "Treat the supplied records as the complete source of evidence. An omitted fact "
            "has an undetermined value. A conjunction fails when one member is false; it is "
            "undetermined if no member is false and some member is undetermined. A disjunction "
            "succeeds when one member is true; it is undetermined if no member is true and "
            "some member is undetermined. A requirement succeeds only when it is met. "
            "All requirements of a move must succeed; a move with no requirements qualifies. "
            "A qualifying move establishes its listed facts. False entries cannot change. "
            "Every move attempt uses one unit, including rejected and ineffectual attempts. "
            "Rejected moves leave the records unchanged. All listed moves can be reused. "
            "Execution ends as soon as the target fact holds."
        )
        question = (
            "For every listed move, classify its requirements as met, violated, or unknown. "
            "Reply with a JSON mapping from move IDs to those labels."
            if task == "judgment"
            else "Identify a first move on a minimum-length route to the target. "
            "Any tied minimum route qualifies. Reply with that move's ID only."
        )
    if presentation not in {"compact", "wording", "layout", "renamed"}:
        raise ValueError("unknown presentation")
    return preamble + "\n" + question + "\nWORLD_JSON\n" + public_world


def renamed(world: World) -> World:
    """Apply a bijective identifier renaming without changing any dependency or observation."""
    derived = {r.name for r in world.rules}
    names = {world.goal, *(n for n, _ in world.facts)}
    names.update(n for r in world.rules for n in r.inputs)
    names.update(n for a in world.actions for n in (*a.requires, *a.effects))
    mapping = {n: f"f{i}" for i, n in enumerate(sorted(names - derived))}
    mapping.update({n: f"r{i}" for i, n in enumerate(sorted(derived))})
    actions = {n: f"a{i}" for i, n in enumerate(sorted(a.id for a in world.actions))}
    return World(
        mapping[world.goal],
        tuple((mapping[n], v) for n, v in world.facts),
        tuple(
            Rule(mapping[r.name], r.operator, tuple(mapping[n] for n in r.inputs))
            for r in world.rules
        ),
        tuple(
            Action(
                actions[a.id],
                tuple(mapping[n] for n in a.requires),
                tuple(mapping[n] for n in a.effects),
            )
            for a in world.actions
        ),
    )


def rollout_order(seed: int, case_id: str, step: int, ids: tuple[str, ...]) -> tuple[str, ...]:
    """Hash ordering is independent of batching, other episodes and global RNG state."""
    return tuple(
        sorted(
            ids,
            key=lambda name: hashlib.sha256(
                f"menu-v1:{seed}:{case_id}:{step}:{name}".encode()
            ).digest(),
        )
    )

"""Deterministic evaluation and model-free replay; adapters receive public queries only."""

from __future__ import annotations

import hashlib
import json
from collections.abc import Callable
from typing import Any, cast

from .core import (
    all_requirements_status,
    optimal_actions,
    shortest_distance,
    transition,
    world_from_dict,
    world_to_dict,
)
from .render import canonical, payload, render, rollout_order

Engine = Callable[[dict[str, object]], object]
Responder = Callable[[dict[str, object]], dict[str, object]]


def _public_query(query: dict[str, object]) -> dict[str, object]:
    public = {key: query[key] for key in ("id", "task", "text")}
    if any(not isinstance(value, str) or not value for value in public.values()):
        raise ValueError("queries require nonempty string id/task/text")
    if public["task"] not in ("judgment", "action"):
        raise ValueError("unsupported task")
    return public


def _invoke(query: dict[str, object], engine: Engine) -> dict[str, object]:
    try:
        public = dict(query)
        public["id"] = hashlib.sha256(("engine-query-v1:" + str(query["id"])).encode()).hexdigest()
        answer = engine(public)
        # Detach mutable adapter data and reject objects without a portable JSON representation.
        encoded = json.dumps(answer, allow_nan=False)
        answer = json.loads(encoded)
        error = None
    except Exception as exc:
        answer = None
        error = f"{type(exc).__name__}: {exc}"
    return {"id": query["id"], "answer": answer, "error": error}


def run_static(queries: list[dict[str, object]], engine: Engine) -> list[dict[str, object]]:
    public = [_public_query(query) for query in queries]
    if len({query["id"] for query in public}) != len(public):
        raise ValueError("duplicate query IDs")
    return [_invoke(query, engine) for query in public]


def _summary(traces: list[dict[str, Any]]) -> dict[str, object]:
    attempts = [attempt for trace in traces for attempt in trace["attempts"]]
    episodes = len(traces)
    count = len(attempts)
    completed = sum(trace["completed"] for trace in traces)
    shortest = sum(
        trace["completed"] and trace["steps"] == trace["initial_distance"] for trace in traces
    )
    result: dict[str, object] = {
        "episodes": episodes,
        "completed": completed,
        "completion_rate": completed / episodes if episodes else None,
        "shortest_completed": shortest,
        "shortest_completion_rate": shortest / episodes if episodes else None,
        "attempts": count,
        "mean_steps": sum(trace["steps"] for trace in traces) / episodes if episodes else None,
        "step_denominator": "all episodes; failures consume their full budget",
        "attempt_denominator": "all attempts, including invalid outputs and no-ops",
        "suboptimal_definition": (
            "valid action outside all shortest-plan first actions; includes no-ops"
        ),
    }
    for field in ("invalid", "noop", "suboptimal", "joint_correct", "judgment_correct", "optimal"):
        total = sum(attempt[field] for attempt in attempts)
        result[field + "_count"] = total
        result[field + "_rate"] = total / count if count else None
    applicable = [
        attempt for attempt in attempts if attempt["selected_judgment_mislabel"] is not None
    ]
    result["selected_judgment_mislabel_count"] = sum(
        attempt["selected_judgment_mislabel"] for attempt in applicable
    )
    result["selected_judgment_count"] = len(applicable)
    result["selected_judgment_mislabel_rate"] = (
        sum(attempt["selected_judgment_mislabel"] for attempt in applicable) / len(applicable)
        if applicable
        else None
    )
    return result


def _run_rollouts(
    cases: list[dict[str, object]], respond: Responder, seed: int
) -> dict[str, object]:
    if type(seed) is not int:
        raise ValueError("integer rollout seed required")
    identifiers = [case.get("id") for case in cases]
    if any(not isinstance(identifier, str) or not identifier for identifier in identifiers):
        raise ValueError("nonempty case IDs required")
    if len(set(identifiers)) != len(identifiers):
        raise ValueError("duplicate rollout cases")
    traces = []
    for case in cases:
        identifier = str(case["id"])
        split = case.get("split")
        if not isinstance(split, str) or not split:
            raise ValueError("nonempty split required")
        presentation = case.get("presentation", "compact")
        if not isinstance(presentation, str) or presentation not in (
            "compact",
            "wording",
            "layout",
            "renamed",
        ):
            raise ValueError("unsupported presentation")
        world = world_from_dict(case["world"])
        initial_distance = shortest_distance(world)
        if initial_distance is None:
            raise ValueError("rollout initial goal must be reachable")
        budget = initial_distance + 4
        if "budget" in case and (type(case["budget"]) is not int or case["budget"] != budget):
            raise ValueError("rollout budget must equal initial distance plus four")
        attempts = []
        for step in range(budget):
            if dict(world.facts).get(world.goal) is True:
                break
            order = rollout_order(
                seed, identifier, step, tuple(action.id for action in world.actions)
            )
            public = payload(world, order, presentation)
            before = world_to_dict(world)
            labels = all_requirements_status(world)
            gold_optimal = list(optimal_actions(world))
            queries = []
            for task in ("judgment", "action"):
                query: dict[str, object] = {
                    "id": f"{identifier}/rollout-{step}/{task}",
                    "task": task,
                    "text": render(public, task, presentation),
                }
                prediction = respond(query)
                queries.append(
                    {
                        **query,
                        "text_sha256": hashlib.sha256(str(query["text"]).encode()).hexdigest(),
                        "answer": prediction["answer"],
                        "error": prediction["error"],
                    }
                )
            judgment, action = queries
            judgment_correct = judgment["error"] is None and judgment["answer"] == labels
            selected = action["answer"]
            selected_id = selected if isinstance(selected, str) and selected in labels else None
            valid = (
                action["error"] is None and selected_id is not None and labels[selected_id] == "met"
            )
            optimal = bool(valid and selected_id in gold_optimal)
            if valid and selected_id is not None:
                world = transition(world, selected_id)
            after = world_to_dict(world)
            noop = bool(valid and after["facts"] == before["facts"])
            selected_mislabel = None
            if selected_id is not None:
                supplied = judgment["answer"]
                selected_mislabel = (
                    judgment["error"] is not None
                    or not isinstance(supplied, dict)
                    or supplied.get(selected_id) != labels[selected_id]
                )
            attempts.append(
                {
                    "step": step,
                    "public_world": public,
                    "before": before,
                    "after": after,
                    "queries": queries,
                    "action": selected_id,
                    "gold_labels": dict(sorted(labels.items())),
                    "gold_optimal": gold_optimal,
                    "invalid": not valid,
                    "noop": noop,
                    "suboptimal": bool(valid and not optimal),
                    "optimal": optimal,
                    "judgment_correct": judgment_correct,
                    "joint_correct": bool(judgment_correct and optimal),
                    "selected_judgment_mislabel": selected_mislabel,
                }
            )
        traces.append(
            {
                "id": identifier,
                "split": split,
                "presentation": presentation,
                "initial_distance": initial_distance,
                "budget": budget,
                "completed": dict(world.facts).get(world.goal) is True,
                "steps": len(attempts),
                "attempts": attempts,
            }
        )
    return {
        "seed": seed,
        "summary": _summary(traces),
        "by_split": {
            split: _summary([trace for trace in traces if trace["split"] == split])
            for split in sorted({str(trace["split"]) for trace in traces})
        },
        "traces": traces,
    }


def run_rollouts(cases: list[dict[str, object]], engine: Engine, seed: int) -> dict[str, object]:
    """Ask separate questions at each state; every action attempt costs one.

    Answers are never forwarded into the other question. Adapters must reset
    conversational state between requests; an arbitrary callable can retain
    its own state. These observations do not establish internal faithfulness.
    Engine query IDs are opaque hashes; saved records retain fixture IDs.
    """
    return _run_rollouts(cases, lambda query: _invoke(query, engine), seed)


def replay_rollouts(
    cases: list[dict[str, object]], traces: list[dict[str, object]], seed: int
) -> dict[str, object]:
    """Rebuild exact prompts, transitions and scores using saved answers, without a model.

    Recorded answers/errors are replay evidence, not independently authenticated
    inference results. Every other trace field must agree with recomputation.
    """
    if not isinstance(traces, list) or len(traces) != len(cases):
        raise ValueError("rollout trace coverage differs")
    records: list[dict[str, object]] = []
    try:
        for trace, case in zip(traces, cases, strict=True):
            if trace["id"] != case["id"]:
                raise ValueError("rollout case order differs")
            attempts = trace["attempts"]
            if not isinstance(attempts, list) or any(
                not isinstance(item, dict) for item in attempts
            ):
                raise ValueError("malformed attempt collection")
            for attempt in cast(list[dict[str, object]], attempts):
                queries = attempt["queries"]
                if not isinstance(queries, list) or len(queries) != 2:
                    raise ValueError("each attempt requires both query records")
                if any(
                    not isinstance(record, dict) or any(not isinstance(key, str) for key in record)
                    for record in queries
                ):
                    raise ValueError("malformed prediction records")
                records.extend(cast(list[dict[str, object]], queries))
    except (KeyError, TypeError) as exc:
        raise ValueError("malformed rollout traces") from exc
    position = 0

    def respond(query: dict[str, object]) -> dict[str, object]:
        nonlocal position
        if position >= len(records):
            raise ValueError("missing rollout prediction record")
        record = records[position]
        position += 1
        digest = hashlib.sha256(str(query["text"]).encode()).hexdigest()
        if (
            any(record.get(key) != value for key, value in query.items())
            or record.get("text_sha256") != digest
        ):
            raise ValueError("replay query or input hash differs")
        if set(record) != {"id", "task", "text", "text_sha256", "answer", "error"}:
            raise ValueError("malformed prediction record")
        if record["error"] is not None and not isinstance(record["error"], str):
            raise ValueError("invalid recorded error")
        if record["error"] is not None and record["answer"] is not None:
            raise ValueError("failed adapter records cannot contain an answer")
        try:
            json.dumps(record["answer"], allow_nan=False)
        except (TypeError, ValueError) as exc:
            raise ValueError("recorded answer must be portable finite JSON") from exc
        return {"id": query["id"], "answer": record["answer"], "error": record["error"]}

    report = _run_rollouts(cases, respond, seed)
    if position != len(records):
        raise ValueError("surplus rollout prediction records")
    if canonical(report["traces"]) != canonical(traces):
        raise ValueError("recorded rollout state or score differs")
    return report

"""Transparent static-task scores with exact family membership and retained failures."""

from __future__ import annotations

from typing import cast

LABELS = ("met", "violated", "unknown")


def _object(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or any(not isinstance(k, str) for k in value):
        raise ValueError("expected string-keyed object")
    return cast(dict[str, object], value)


def _strings(value: object) -> list[str]:
    if not isinstance(value, list) or any(not isinstance(x, str) or not x for x in value):
        raise ValueError("expected nonempty string IDs")
    result = cast(list[str], value)
    if len(set(result)) != len(result):
        raise ValueError("duplicate IDs")
    return result


def _fraction(numerator: int, denominator: int) -> float | None:
    return numerator / denominator if denominator else None


def _validate(
    cases: list[dict[str, object]],
    families: list[dict[str, object]],
    predictions: list[dict[str, object]],
) -> dict[str, dict[str, object]]:
    if not cases or not families:
        raise ValueError("nonempty cases and families required")
    case_ids: set[str] = set()
    query_ids: set[str] = set()
    for case in cases:
        for field in ("id", "family_id", "split"):
            if not isinstance(case.get(field), str) or not case[field]:
                raise ValueError("case requires string identity and split")
        case_id = cast(str, case["id"])
        if case_id in case_ids:
            raise ValueError("duplicate case ID")
        case_ids.add(case_id)
        queries = _strings(case.get("query_ids"))
        if len(queries) != 2 or query_ids.intersection(queries):
            raise ValueError("cases require two unique query IDs")
        query_ids.update(queries)
        labels = _object(case.get("labels"))
        if not labels or any(not action or label not in LABELS for action, label in labels.items()):
            raise ValueError("invalid gold labels")
        optimal = _strings(case.get("optimal"))
        if not optimal or not set(optimal).issubset(labels):
            raise ValueError("invalid optimal action set")
        if any(labels[action] != "met" for action in optimal):
            raise ValueError("optimal action must be eligible")
    by_case = {cast(str, case["id"]): case for case in cases}
    declared: set[str] = set()
    family_ids: set[str] = set()
    for family in families:
        name, split = family.get("id"), family.get("split")
        if not isinstance(name, str) or not name or name in family_ids:
            raise ValueError("duplicate or invalid family ID")
        if not isinstance(split, str) or not split:
            raise ValueError("invalid family split")
        family_ids.add(name)
        members = _strings(family.get("members"))
        if not members or declared.intersection(members):
            raise ValueError("empty or duplicated family membership")
        for member in members:
            member_case = by_case.get(member)
            if (
                member_case is None
                or member_case["family_id"] != name
                or member_case["split"] != split
            ):
                raise ValueError("family member missing or crosses identity/split")
        declared.update(members)
        pairs = family.get("pairs")
        if not isinstance(pairs, list):
            raise ValueError("family requires pairs list")
        seen_pairs: set[tuple[str, str, str]] = set()
        for value in pairs:
            pair = _object(value)
            if set(pair) != {"kind", "left", "right"}:
                raise ValueError("unexpected pair envelope")
            kind, left, right = pair["kind"], pair["left"], pair["right"]
            if (
                kind not in ("rule", "fact")
                or not isinstance(left, str)
                or not isinstance(right, str)
            ):
                raise ValueError("invalid pair")
            if left == right or left not in members or right not in members:
                raise ValueError("pair endpoints must differ and belong to family")
            low, high = sorted((left, right))
            key = (kind, low, high)
            if key in seen_pairs:
                raise ValueError("duplicate pair")
            seen_pairs.add(key)
            if set(_object(by_case[left]["labels"])) != set(_object(by_case[right]["labels"])):
                raise ValueError("pair action populations differ")
    if declared != case_ids:
        raise ValueError("case population differs from exact declared families")
    by_query: dict[str, dict[str, object]] = {}
    for raw_prediction in predictions:
        prediction = _object(raw_prediction)
        if set(prediction) != {"id", "answer", "error"}:
            raise ValueError("unexpected prediction envelope")
        identifier, error = prediction["id"], prediction["error"]
        if not isinstance(identifier, str) or identifier not in query_ids:
            raise ValueError("unknown prediction ID")
        if identifier in by_query:
            raise ValueError("duplicate prediction ID")
        if error is not None:
            if not isinstance(error, str) or not error:
                raise ValueError("prediction error must be nonempty string or null")
            if prediction["answer"] is not None:
                raise ValueError("error prediction must have null answer")
        by_query[identifier] = prediction
    return by_query


def _panel(
    cases: list[dict[str, object]],
    families: list[dict[str, object]],
    by_query: dict[str, dict[str, object]],
) -> dict[str, object]:
    confusion = [[0 for _ in range(4)] for _ in LABELS]
    outcomes: dict[str, dict[str, object]] = {}
    actions_correct = eligible = invalid_actions = judgments_correct = joint_correct = 0
    missing = errors = agreement_count = agreement_met = extra_keys = 0
    for case in cases:
        labels = cast(dict[str, str], case["labels"])
        judgment_id, action_id = cast(list[str], case["query_ids"])
        judgment = by_query.get(judgment_id)
        action = by_query.get(action_id)
        for row in (judgment, action):
            missing += row is None
            errors += row is not None and row["error"] is not None
        raw = judgment["answer"] if judgment is not None and judgment["error"] is None else None
        answer: dict[str, object] = {}
        if isinstance(raw, dict) and all(isinstance(key, str) for key in raw):
            if set(raw).issubset(labels):
                answer = cast(dict[str, object], raw)
            else:
                extra_keys += 1
        per_action = {}
        for name, gold in labels.items():
            value = answer.get(name)
            column = LABELS.index(value) if isinstance(value, str) and value in LABELS else 3
            confusion[LABELS.index(gold)][column] += 1
            per_action[name] = value == gold
        judgment_correct = all(per_action.values())
        selected = action["answer"] if action is not None and action["error"] is None else None
        valid_action = isinstance(selected, str) and selected in labels
        optimal = valid_action and selected in cast(list[str], case["optimal"])
        permitted = valid_action and labels[cast(str, selected)] == "met"
        invalid_actions += not valid_action
        actions_correct += optimal
        eligible += permitted
        judgments_correct += judgment_correct
        joint = judgment_correct and optimal
        joint_correct += joint
        if valid_action and answer.get(cast(str, selected)) in LABELS:
            agreement_count += 1
            agreement_met += answer[cast(str, selected)] == "met"
        outcomes[cast(str, case["id"])] = {
            "judgment": judgment_correct,
            "action": optimal,
            "joint": joint,
            "per_action": per_action,
        }
    support = [sum(row) for row in confusion]
    recall = {label: _fraction(confusion[i][i], support[i]) for i, label in enumerate(LABELS)}
    f1 = []
    for i in range(3):
        predicted = sum(row[i] for row in confusion)
        denominator = support[i] + predicted
        if support[i]:
            f1.append(2 * confusion[i][i] / denominator)
    total = sum(support)
    correct = sum(confusion[i][i] for i in range(3))
    family_report: dict[str, object] = {"count": len(families)}
    for task in ("judgment", "action", "joint"):
        complete = sum(
            all(outcomes[name][task] for name in cast(list[str], family["members"]))
            for family in families
        )
        family_report[task + "_correct"] = complete
        family_report[task + "_accuracy"] = _fraction(complete, len(families))
    pairs: dict[str, object] = {}
    by_case = {cast(str, case["id"]): case for case in cases}
    for kind in ("rule", "fact"):
        declared_pairs = [
            cast(dict[str, str], pair)
            for family in families
            for pair in cast(list[dict[str, object]], family["pairs"])
            if pair["kind"] == kind
        ]
        result: dict[str, object] = {"count": len(declared_pairs)}
        per_count = per_correct = 0
        relations = {"equal": 0, "disjoint": 0, "overlap": 0}
        relation_correct = {"equal": 0, "disjoint": 0, "overlap": 0}
        for pair in declared_pairs:
            left, right = outcomes[pair["left"]], outcomes[pair["right"]]
            a, b = (
                cast(dict[str, bool], left["per_action"]),
                cast(dict[str, bool], right["per_action"]),
            )
            per_count += len(a)
            per_correct += sum(a[name] and b[name] for name in a)
            ga, gb = (
                set(cast(list[str], by_case[pair["left"]]["optimal"])),
                set(cast(list[str], by_case[pair["right"]]["optimal"])),
            )
            relation = "equal" if ga == gb else "disjoint" if not ga & gb else "overlap"
            relations[relation] += 1
            relation_correct[relation] += bool(left["action"] and right["action"])
        for task in ("judgment", "action", "joint"):
            count = sum(
                bool(outcomes[pair["left"]][task] and outcomes[pair["right"]][task])
                for pair in declared_pairs
            )
            result[task + "_both_correct"] = count
            result[task + "_both_accuracy"] = _fraction(count, len(declared_pairs))
        result["per_action"] = {
            "count": per_count,
            "both_correct": per_correct,
            "accuracy": _fraction(per_correct, per_count),
        }
        result["action_gold_relation"] = relations
        result["action_by_gold_relation"] = {
            relation: {
                "count": count,
                "both_correct": relation_correct[relation],
                "both_accuracy": _fraction(relation_correct[relation], count),
            }
            for relation, count in relations.items()
        }
        pairs[kind] = result
    count = len(cases)
    return {
        "cases": count,
        "judgment": {
            "count": total,
            "correct": correct,
            "accuracy": _fraction(correct, total),
            "macro_f1": sum(f1) / len(f1) if f1 else None,
            "macro_f1_classes": [label for label, n in zip(LABELS, support, strict=True) if n],
            "recall": recall,
            "confusion": {
                "rows": list(LABELS),
                "columns": [*LABELS, "invalid"],
                "counts": confusion,
            },
            "all_correct_cases": judgments_correct,
        },
        "action": {
            "count": count,
            "correct": actions_correct,
            "accuracy": _fraction(actions_correct, count),
            "eligible": eligible,
            "eligibility_accuracy": _fraction(eligible, count),
            "invalid": invalid_actions,
            "uniform_random_expected_action_accuracy": sum(
                len(cast(list[str], case["optimal"])) / len(cast(dict[str, str], case["labels"]))
                for case in cases
            )
            / count,
        },
        "joint": {
            "count": count,
            "correct": joint_correct,
            "accuracy": _fraction(joint_correct, count),
        },
        "selected_label_met_agreement": {
            "count": agreement_count,
            "met": agreement_met,
            "fraction": _fraction(agreement_met, agreement_count),
            "interpretation": (
                "Descriptive agreement on valid selected action/label outputs; "
                "not correctness or reasoning faithfulness."
            ),
        },
        "families": family_report,
        "pairs": pairs,
        "failures": {
            "missing_queries": missing,
            "error_queries": errors,
            "judgment_extra_keys": extra_keys,
        },
    }


def score(
    cases: list[dict[str, object]],
    families: list[dict[str, object]],
    predictions: list[dict[str, object]],
) -> dict[str, object]:
    """Score frozen golds; semantic/source validation belongs to release verification."""
    by_query = _validate(cases, families, predictions)
    report = _panel(cases, families, by_query)
    report["by_split"] = {
        split: _panel(
            [case for case in cases if case["split"] == split],
            [family for family in families if family["split"] == split],
            by_query,
        )
        for split in sorted({cast(str, case["split"]) for case in cases})
    }
    if all("presentation" in case for case in cases):
        slices: dict[str, object] = {}
        for presentation in sorted({str(case["presentation"]) for case in cases}):
            panel = _panel(
                [case for case in cases if str(case["presentation"]) == presentation], [], by_query
            )
            panel.pop("families")
            panel.pop("pairs")
            slices[presentation] = panel
        report["by_presentation"] = slices
    candidate_slices: dict[str, object] = {}
    for width in sorted({len(_object(case["labels"])) for case in cases}):
        panel = _panel(
            [case for case in cases if len(_object(case["labels"])) == width],
            [],
            by_query,
        )
        panel.pop("families")
        panel.pop("pairs")
        candidate_slices[str(width)] = panel
    report["by_candidate_count"] = candidate_slices
    report["uncertainty"] = (
        "Raw finite-population counts only; no confidence interval or independent-template claim."
    )
    return report

"""Optional caller-owned Laya execution; no Laya import or model load at import."""

from __future__ import annotations

import importlib
from collections.abc import Callable
from inspect import iscoroutinefunction
from typing import Protocol, cast

from ..api import (
    JSONValue,
    Prediction,
    Request,
    canonical_json,
    prediction_to_dict,
    strict_json_loads,
)
from .native import ScoreMode, decode_native, native_request

Admission = Callable[[Request], None]


class _Predict(Protocol):
    def __call__(
        self, *, state: JSONValue, questions: dict[str, dict[str, JSONValue]]
    ) -> object: ...


class _Encode(Protocol):
    def __call__(
        self, tok: object, text: str, *, add_special_tokens: bool
    ) -> dict[str, object]: ...


class _BuildSequence(Protocol):
    def __call__(
        self,
        tok: object,
        state: JSONValue,
        question: dict[str, object],
        max_len: int,
        head_max_len: int,
    ) -> tuple[list[int], list[int]]: ...


class _Agent(Protocol):
    tok: object
    cfg: dict[str, object]

    def _check_question(self, identifier: str, question: dict[str, JSONValue]) -> None: ...
    def _to_internal(self, question: dict[str, JSONValue]) -> dict[str, object]: ...
    def _encode_state(
        self, state: JSONValue, ids: list[str], internal: dict[str, dict[str, object]]
    ) -> list[dict[str, object]]: ...


def source_admission(agent: object) -> Admission:
    """Check hook-free Agent inputs using its installed source formatter/tokenizer.

    The inspected formatter caps individual criterion text at 48 tokens, then
    may cut instructions, criteria and state again. Compare its actual encoding
    with a generous-budget encoding, checking that the fixed criterion cap was
    not activated. Unknown APIs and configured hooks require a different explicit
    admission recipe; character counts are never used as token evidence.
    """
    common = importlib.import_module("laya.common")
    encode = cast(_Encode, common.encode_text)
    render = cast(Callable[[dict[str, object]], list[str]], common.render_options)
    serialize = cast(Callable[[JSONValue], str], common.serialize_state)
    build = cast(_BuildSequence, common.build_sequence)
    for name in ("_check_question", "_to_internal", "_encode_state"):
        if not callable(getattr(agent, name, None)):
            raise ValueError("Source admission requires the inspected Laya Agent formatter API")
    checked = cast(_Agent, agent)
    if not hasattr(agent, "tok") or not isinstance(getattr(agent, "cfg", None), dict):
        raise ValueError("Source admission requires the loaded Agent tokenizer and config")

    def admit(request: Request) -> None:
        if getattr(agent, "hooks", ()):
            raise ValueError("Source admission requires a hook-free Laya Agent")
        state, question, _ = native_request(request)
        checked._check_question("decision", question)
        internal = checked._to_internal(question)
        mask = getattr(checked.tok, "mask_token", None)
        if type(mask) is not str or not mask:
            raise ValueError("Tokenizer does not expose its reserved mask token")
        texts = render(internal)
        instructions = cast(str, internal["ins"])
        state_text = serialize(state)
        if any(mask in text for text in [instructions, state_text, *texts]):
            raise ValueError("Input contains a reserved mask token that Laya removes")
        lengths = [
            len(
                cast(
                    list[int],
                    encode(checked.tok, " " + text, add_special_tokens=False)["input_ids"],
                )
            )
            for text in texts
        ]
        if any(length > 48 for length in lengths):
            raise ValueError("Laya's fixed 48-token criterion cap would drop semantic input")
        instruction_length = len(
            cast(
                list[int],
                encode(
                    checked.tok,
                    str(internal["t"]) + " question: " + instructions,
                    add_special_tokens=False,
                )["input_ids"],
            )
        )
        state_length = len(
            cast(
                list[int],
                encode(
                    checked.tok,
                    state_text,
                    add_special_tokens=False,
                )["input_ids"],
            )
        )
        head_budget = instruction_length + sum(lengths) + len(lengths) + 16
        full, markers = build(
            checked.tok, state, internal, head_budget + state_length + 16, head_budget
        )
        if len(markers) != len(texts):
            raise ValueError("Laya's formatter cannot preserve every native candidate marker")
        actual = checked._encode_state(state, ["decision"], {"decision": internal})
        if len(actual) != 1 or actual[0].get("ids") != full or actual[0].get("markers") != markers:
            raise ValueError("Laya's configured token budgets would truncate the supplied input")

    return admit


class Laya:
    """Wrap one already-loaded synchronous Agent with an explicit admission check."""

    def __init__(
        self,
        agent: object,
        *,
        admission: Admission,
        admission_id: str,
        score_mode: ScoreMode = "native",
    ) -> None:
        predict = getattr(agent, "predict", None)
        if not callable(predict) or iscoroutinefunction(predict):
            raise ValueError("Laya requires an already-loaded synchronous predict method")
        if not callable(admission):
            raise ValueError("Laya requires an explicit full-input admission callable")
        if type(admission_id) is not str or not admission_id.strip():
            raise ValueError("Laya requires a nonempty admission recipe identifier")
        if score_mode not in ("native", "jevbench_argmax"):
            raise ValueError("Unknown Laya score mode")
        self._predict = cast(_Predict, predict)
        self._admission = admission
        self.admission_id = admission_id
        self.score_mode = score_mode
        self._records: list[dict[str, JSONValue]] = []

    @property
    def records(self) -> tuple[dict[str, JSONValue], ...]:
        return tuple(
            cast(dict[str, JSONValue], strict_json_loads(canonical_json(record)))
            for record in self._records
        )

    def __call__(self, request: Request) -> Prediction:
        record: dict[str, JSONValue] = {
            "execution_id": request.id,
            "recipe": "laya-native-jev-v1",
            "admission_id": self.admission_id,
            "score_mode": self.score_mode,
            "response": None,
        }
        self._records.append(record)
        try:
            state, question, _ = native_request(request)
            self._admission(request)
            raw = strict_json_loads(
                canonical_json(
                    self._predict(
                        state=state,
                        questions={"decision": question},
                    )
                )
            )
            record["response"] = raw
            prediction, metadata = decode_native(
                request, raw, score_mode=self.score_mode, probability_rounding=0.00005
            )
            if isinstance(raw, dict):
                usage = raw.get("usage")
                collapsed = False
                if isinstance(usage, dict) and isinstance(usage.get("options"), dict):
                    for diagnostic in cast(dict[str, JSONValue], usage["options"]).values():
                        if not isinstance(diagnostic, dict):
                            raise ValueError("Unknown Laya option-admission diagnostic")
                        total, distinct = diagnostic.get("total"), diagnostic.get("distinct")
                        if type(total) is not int or type(distinct) is not int:
                            raise ValueError("Unknown Laya candidate-admission counts")
                        if total < 1 or not 0 <= distinct <= total:
                            raise ValueError("Invalid Laya candidate-admission counts")
                        collapsed |= distinct < total
                if isinstance(usage, dict) and (usage.get("truncated") is True or collapsed):
                    prediction = Prediction(
                        None,
                        "Laya reports truncated state or collapsed options",
                        usage=prediction.usage,
                    )
            record["decode"] = metadata
            record["prediction"] = prediction_to_dict(prediction)
            return prediction
        except Exception as error:
            record["error"] = f"{type(error).__name__}: {error}"
            raise

"""Pure conversion of explicit JevBench public schemas and native typed answers."""

from __future__ import annotations

import math
from typing import Literal, cast

from ..api import (
    JSONValue,
    Prediction,
    Request,
    Usage,
    canonical_json,
    strict_json_loads,
    validate_request,
)

ScoreMode = Literal["native", "jevbench_argmax"]


def _object(value: JSONValue) -> dict[str, JSONValue]:
    if type(value) is not dict:
        raise ValueError("Native schema requires an object")
    return value


def native_request(request: Request) -> tuple[JSONValue, dict[str, JSONValue], tuple[str, ...]]:
    """Parse only the declared native task; preserve state and question roles."""
    validate_request(request)
    if request.task not in {"jevbench/choice", "jevbench/noul", "jevbench/score"}:
        raise ValueError("Native adapter supports explicit jevbench choice/noul/score tasks only")
    body = _object(strict_json_loads(request.text))
    if set(body) != {"state", "question", "labels"}:
        raise ValueError("Native public body requires exactly state, question and labels")
    question = _object(body["question"])
    if set(question) != {"type", "instructions", "criteria"}:
        raise ValueError("Native question has missing or unknown fields")
    kind = question["type"]
    if request.task != "jevbench/" + str(kind):
        raise ValueError("Native task and question type disagree")
    if type(question["instructions"]) is not str or not question["instructions"].strip():
        raise ValueError("Native instructions must be nonempty text")
    raw_labels = body["labels"]
    if (
        type(raw_labels) is not list
        or not raw_labels
        or any(type(label) is not str or not label for label in raw_labels)
    ):
        raise ValueError("Native labels require nonempty strings")
    labels = tuple(cast(list[str], raw_labels))
    if len(set(labels)) != len(labels):
        raise ValueError("Native labels must be unique")
    criteria = question["criteria"]
    if kind == "score":
        if labels != tuple(str(i) for i in range(len(labels))) or request.choices:
            raise ValueError("Native score requires sequential levels and no choice menu")
        if type(criteria) is not list or len(criteria) != len(labels):
            raise ValueError("Native score rubric does not match its levels")
    else:
        if tuple(choice.id for choice in request.choices) != labels:
            raise ValueError("Native labels and supplied menu order disagree")
        mapping = _object(criteria)
        if kind == "noul":
            if labels != ("no", "yes") or set(mapping) != {"false", "true"}:
                raise ValueError("Native noul requires no/yes and false/true criteria")
            expected_text = {"no": mapping["false"], "yes": mapping["true"]}
        else:
            if set(mapping) != set(labels):
                raise ValueError("Native choice criteria differ from menu")
            expected_text = mapping
        if any(choice.text != expected_text[choice.id] for choice in request.choices):
            raise ValueError("Native criteria and supplied choice text disagree")
        if kind == "choice":
            # Canonical JSON sorts object keys; the explicit menu retains source order.
            question["criteria"] = {label: mapping[label] for label in labels}
    if type(body["state"]) not in (str, dict, list):
        raise ValueError("Native state must be text, an object or a conversation list")
    return body["state"], question, labels


def _number(value: JSONValue, name: str) -> int | float:
    if type(value) not in (int, float) or not math.isfinite(cast(float, value)):
        raise ValueError(f"Native {name} must be a finite number")
    return cast(int | float, value)


def _distribution(value: JSONValue, labels: tuple[str, ...], rounding: float) -> dict[str, float]:
    values = _object(value)
    if set(values) != set(labels):
        raise ValueError("Native probability labels differ from requested labels")
    result = {label: float(_number(values[label], "probability")) for label in labels}
    if any(not 0 <= value <= 1 for value in result.values()):
        raise ValueError("Native probabilities must be in [0, 1]")
    if abs(math.fsum(result.values()) - 1) > len(labels) * rounding + 1e-6:
        raise ValueError("Native probability mass is invalid")
    return result


def decode_native(
    request: Request,
    response: object,
    *,
    score_mode: ScoreMode = "native",
    probability_rounding: float = 0.0,
) -> tuple[Prediction, dict[str, JSONValue]]:
    """Keep native numeric values; an explicit Jev mode chooses ordinal argmax.

    Native rounded distributions never get renormalized. A vector outside the
    core's strict mass tolerance stays only in the caller's raw-response ledger.
    """
    if score_mode not in ("native", "jevbench_argmax"):
        raise ValueError("Unknown native score mode")
    if (
        type(probability_rounding) not in (int, float)
        or not math.isfinite(probability_rounding)
        or probability_rounding < 0
    ):
        raise ValueError("Probability rounding must be finite and nonnegative")
    _, question, labels = native_request(request)
    body = _object(strict_json_loads(canonical_json(response)))
    answers = _object(body.get("answers"))
    if set(answers) != {"decision"}:
        raise ValueError("Native answer IDs differ from requested question")
    answer = _object(answers["decision"])
    if answer.get("type") != question["type"]:
        raise ValueError("Native answer type differs from requested question")
    usage_values = _object(body["usage"]) if body.get("usage") is not None else {}
    usage = (
        Usage(
            cast(int | None, usage_values.get("input_tokens")),
            cast(int | None, usage_values.get("output_tokens")),
            cast(int | None, usage_values.get("forward_passes")),
        )
        if usage_values
        else None
    )
    metadata: dict[str, JSONValue] = {"score_mode": score_mode, "probability_reason": None}
    if answer.get("low_confidence") is True or answer.get("abstention") == "abstained":
        return Prediction(None, "Native backend abstained", usage=usage), metadata
    kind = question["type"]
    probabilities: dict[str, float] | None = None
    if kind == "noul":
        p = _number(answer.get("noul"), "noul")
        if not 0 <= p <= 1:
            raise ValueError("Native noul must be P(true) in [0, 1]")
        result: JSONValue = "yes" if p > 0.5 else "no"
        probabilities = {"no": 1 - float(p), "yes": float(p)}
    elif kind == "choice":
        result = answer.get("choice")
        if type(result) is not str or result not in labels:
            raise ValueError("Native choice is absent from menu")
        if answer.get("probabilities") is not None:
            probabilities = _distribution(answer["probabilities"], labels, probability_rounding)
    else:
        result = _number(answer.get("score"), "score")
        if not 0 <= result <= len(labels) - 1:
            raise ValueError("Native score exceeds its rubric")
        distribution = (
            _distribution(answer["probabilities"], labels, probability_rounding)
            if answer.get("probabilities") is not None
            else None
        )
        if score_mode == "jevbench_argmax":
            if distribution is None:
                raise ValueError("JevBench ordinal argmax requires native probabilities")
            # Match JevBench scoring.py: ties use the lexicographically smallest key.
            result = int(min(distribution, key=lambda label: (-distribution[label], label)))
        metadata["probability_reason"] = "native ordinal distribution retained in raw response"
    if probabilities is not None and not math.isclose(
        math.fsum(probabilities.values()), 1.0, rel_tol=0, abs_tol=1e-6
    ):
        probabilities = None
        metadata["probability_reason"] = (
            "rounded native vector does not meet strict core mass tolerance"
        )
    prediction = Prediction(result, probabilities=probabilities, usage=usage)
    return prediction, metadata

"""Optional official TypeSafe SDK transport for native Jev requests."""

from __future__ import annotations

from typing import Literal, Protocol, cast

from dmbench.adapters.native import decode_native, native_request
from dmbench.api import JSONValue, Prediction, Request, canonical_json, strict_json_loads


class SystemOneClient(Protocol):
    """The public synchronous SDK operation used by this adapter."""

    def system_one(
        self,
        state: JSONValue,
        questions: dict[str, dict[str, JSONValue]],
        *,
        model: str | None = None,
    ) -> object: ...
    def close(self) -> None: ...


class TypeSafeModel:
    """Use an already constructed SDK client; retain detached native evidence.

    Caller-owned clients remain caller-owned unless ``owns_client`` is true.
    Records contain public request IDs and responses, never expected answers.
    """

    def __init__(
        self,
        client: SystemOneClient,
        *,
        model: str | None = None,
        score_mode: Literal["native", "jevbench_argmax"] = "native",
        owns_client: bool = False,
    ) -> None:
        if score_mode not in ("native", "jevbench_argmax"):
            raise ValueError("Unsupported score_mode")
        if model is not None and (type(model) is not str or not model.strip()):
            raise ValueError("Model requires a nonempty string")
        self.client = client
        self.model = model
        self.score_mode = score_mode
        self.owns_client = owns_client
        self._records: list[dict[str, JSONValue]] = []
        self._closed = False

    @property
    def records(self) -> tuple[dict[str, JSONValue], ...]:
        """Detached portable native response ledger, suitable for saving as JSON."""
        return tuple(
            cast(dict[str, JSONValue], strict_json_loads(canonical_json(record)))
            for record in self._records
        )

    def __call__(self, request: Request) -> Prediction:
        record: dict[str, JSONValue] = {
            "request_id": request.id,
            "requested_model": self.model,
            "score_mode": self.score_mode,
            "response": None,
        }
        try:
            if self._closed:
                raise RuntimeError("Adapter is closed")
            state, question, _ = native_request(request)
            response = self.client.system_one(
                state, {"decision": question}, **({"model": self.model} if self.model else {})
            )
            dump = getattr(response, "model_dump", None)
            if not callable(dump):
                raise ValueError("SDK response requires model_dump")
            raw = strict_json_loads(canonical_json(dump(mode="json")))
            if type(raw) is not dict:
                raise ValueError("SDK response must be a JSON object")
            record["response"] = raw
            prediction, metadata = decode_native(request, raw, score_mode=self.score_mode)
            record["decoding"] = metadata
        except Exception as error:
            # Exception messages can contain credentials or server response bodies.
            kind = type(error).__name__
            record["error_type"] = kind
            prediction = Prediction(None, error=f"TypeSafe adapter failure: {kind}")
        self._records.append(record)
        return prediction

    def close(self) -> None:
        """Close a factory-owned client once; caller-owned clients stay open."""
        if not self._closed:
            self._closed = True
            if self.owns_client:
                self.client.close()


def create_model() -> TypeSafeModel:
    """Load the optional SDK once, using its documented environment settings."""
    import importlib

    try:
        sdk = importlib.import_module("typesafe_sdk")
    except ImportError as error:
        raise ImportError("Install typesafe-sdk==0.7.2 to use TypeSafe") from error
    client = sdk.TypeSafeClient(retry=sdk.RetryPolicy(max_retries=0))
    return TypeSafeModel(cast(SystemOneClient, client), owns_client=True)


def create_jevbench_model() -> TypeSafeModel:
    """Explicit discrete Jev decoding; retain the native score and distribution."""
    result = create_model()
    result.score_mode = "jevbench_argmax"
    return result

"""Small portable model boundary; supervision never belongs in a Request."""

from __future__ import annotations

import json
import math
from collections.abc import Callable, Sequence
from dataclasses import dataclass
from typing import TypeAlias, cast

JSONValue: TypeAlias = None | bool | int | float | str | list["JSONValue"] | dict[str, "JSONValue"]


def _json(value: object, ancestors: frozenset[int] = frozenset()) -> JSONValue:
    """Validate and detach portable JSON; reject cycles and non-JSON Python types."""
    if value is None or type(value) in (bool, int, str):
        return cast(JSONValue, value)
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("JSON numbers must be finite")
        return value
    if type(value) not in (list, dict):
        raise ValueError("Answer must contain only portable JSON values")
    if id(value) in ancestors:
        raise ValueError("JSON containers cannot contain cycles")
    nested = ancestors | {id(value)}
    if type(value) is list:
        return [_json(item, nested) for item in cast(list[object], value)]
    result: dict[str, JSONValue] = {}
    for key, item in cast(dict[object, object], value).items():
        if type(key) is not str:
            raise ValueError("JSON object keys must be strings")
        result[key] = _json(item, nested)
    return result


def canonical_json(value: object) -> str:
    """Deterministic typed JSON identity, with object order ignored."""
    return json.dumps(_json(value), sort_keys=True, separators=(",", ":"), allow_nan=False)


def strict_json_loads(text: str) -> JSONValue:
    def pairs(items: list[tuple[str, object]]) -> dict[str, object]:
        result: dict[str, object] = {}
        for key, item in items:
            if key in result:
                raise ValueError(f"Duplicate JSON key: {key}")
            result[key] = item
        return result

    def constant(value: str) -> object:
        raise ValueError(f"Nonfinite JSON number: {value}")

    return _json(json.loads(text, object_pairs_hook=pairs, parse_constant=constant))


def _text(value: object, name: str) -> None:
    if type(value) is not str or not value.strip():
        raise ValueError(f"{name} requires a nonempty string")


def _fields(value: object, required: set[str], optional: set[str]) -> dict[str, object]:
    if type(value) is not dict:
        raise ValueError("Schema requires an object")
    record = cast(dict[str, object], value)
    if any(type(key) is not str for key in record):
        raise ValueError("Schema keys must be strings")
    if not required <= record.keys() or record.keys() - required - optional:
        raise ValueError("Schema has missing or unknown fields")
    return record


@dataclass(frozen=True)
class Choice:
    id: str
    text: str

    def __post_init__(self) -> None:
        _text(self.id, "Choice id")
        _text(self.text, "Choice text")


@dataclass(frozen=True)
class Request:
    id: str
    task: str
    text: str
    choices: tuple[Choice, ...] = ()

    def __post_init__(self) -> None:
        validate_request(self)


@dataclass(frozen=True)
class Usage:
    input_tokens: int | None = None
    output_tokens: int | None = None
    forward_passes: int | None = None

    def __post_init__(self) -> None:
        for name in ("input_tokens", "output_tokens", "forward_passes"):
            value = getattr(self, name)
            if value is not None and (
                type(value) is not int or value < (1 if name == "forward_passes" else 0)
            ):
                raise ValueError(f"Invalid usage {name}")


@dataclass(frozen=True)
class Prediction:
    answer: JSONValue
    error: str | None = None
    probabilities: dict[str, float] | None = None
    usage: Usage | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "answer", _json(self.answer))
        if self.probabilities is not None:
            if type(self.probabilities) is not dict:
                raise ValueError("Probabilities require an object")
            object.__setattr__(self, "probabilities", dict(self.probabilities))
        validate_prediction(self)


@dataclass(frozen=True)
class Case:
    request: Request
    expected: tuple[JSONValue, ...]
    group: str
    source: str
    split: str

    def __post_init__(self) -> None:
        if type(self.expected) is not tuple:
            raise ValueError("Expected answers require a tuple")
        object.__setattr__(self, "expected", tuple(_json(item) for item in self.expected))
        validate_case(self)


Model: TypeAlias = Callable[[Request], Prediction | JSONValue]
BatchModel: TypeAlias = Callable[[tuple[Request, ...]], Sequence[Prediction | JSONValue]]


def validate_request(request: Request) -> None:
    if not isinstance(request, Request):
        raise ValueError("Request required")
    for name in ("id", "task", "text"):
        _text(getattr(request, name), f"Request {name}")
    if type(request.choices) is not tuple or any(
        not isinstance(choice, Choice) for choice in request.choices
    ):
        raise ValueError("Choices require a tuple of Choice values")
    ids: set[str] = set()
    for choice in request.choices:
        _text(choice.id, "Choice id")
        _text(choice.text, "Choice text")
        if choice.id in ids:
            raise ValueError("Duplicate choice id")
        ids.add(choice.id)


def validate_prediction(prediction: Prediction, request: Request | None = None) -> None:
    if not isinstance(prediction, Prediction):
        raise ValueError("Prediction required")
    if request is not None:
        validate_request(request)
    _json(prediction.answer)
    if prediction.error is not None:
        _text(prediction.error, "Prediction error")
        if prediction.answer is not None or prediction.probabilities is not None:
            raise ValueError("Errors require null answer and no probabilities")
    if prediction.usage is not None:
        if not isinstance(prediction.usage, Usage):
            raise ValueError("Usage required")
        prediction.usage.__post_init__()
    probabilities = prediction.probabilities
    if probabilities is not None:
        if type(probabilities) is not dict or not probabilities:
            raise ValueError("Probabilities require a nonempty object")
        for key, value in probabilities.items():
            _text(key, "Probability choice id")
            if type(value) not in (int, float) or not math.isfinite(value) or not 0 <= value <= 1:
                raise ValueError("Probabilities must be finite numbers in [0, 1]")
        if not math.isclose(math.fsum(probabilities.values()), 1.0, rel_tol=0, abs_tol=1e-6):
            raise ValueError("Probabilities must sum to one")
        if request is not None:
            if not request.choices or set(probabilities) != {c.id for c in request.choices}:
                raise ValueError("Probabilities must cover exactly the supplied choices")


def validate_case(case: Case) -> None:
    if not isinstance(case, Case):
        raise ValueError("Case required")
    validate_request(case.request)
    for name in ("group", "source", "split"):
        _text(getattr(case, name), f"Case {name}")
    if type(case.expected) is not tuple or not case.expected:
        raise ValueError("Case requires at least one expected answer")
    choices = {choice.id for choice in case.request.choices}
    for answer in case.expected:
        _json(answer)
        if choices and (type(answer) is not str or answer not in choices):
            raise ValueError("Expected choice answer is absent from menu")


def request_to_dict(request: Request) -> dict[str, JSONValue]:
    validate_request(request)
    return {
        "id": request.id,
        "task": request.task,
        "text": request.text,
        "choices": [{"id": c.id, "text": c.text} for c in request.choices],
    }


def request_from_dict(value: object) -> Request:
    record = _fields(value, {"id", "task", "text"}, {"choices"})
    raw = record.get("choices", [])
    if type(raw) is not list:
        raise ValueError("Choices schema requires a list")
    choices = []
    for item in cast(list[object], raw):
        choice = _fields(item, {"id", "text"}, set())
        choices.append(Choice(cast(str, choice["id"]), cast(str, choice["text"])))
    return Request(
        cast(str, record["id"]),
        cast(str, record["task"]),
        cast(str, record["text"]),
        tuple(choices),
    )


def prediction_to_dict(prediction: Prediction) -> dict[str, JSONValue]:
    validate_prediction(prediction)
    usage = prediction.usage
    return {
        "answer": _json(prediction.answer),
        "error": prediction.error,
        "probabilities": _json(prediction.probabilities),
        "usage": None
        if usage is None
        else {
            "input_tokens": usage.input_tokens,
            "output_tokens": usage.output_tokens,
            "forward_passes": usage.forward_passes,
        },
    }


def prediction_from_dict(value: object, request: Request | None = None) -> Prediction:
    record = _fields(value, {"answer"}, {"error", "probabilities", "usage"})
    raw_usage = record.get("usage")
    usage = None
    if raw_usage is not None:
        fields = _fields(raw_usage, set(), {"input_tokens", "output_tokens", "forward_passes"})
        usage = Usage(
            cast(int | None, fields.get("input_tokens")),
            cast(int | None, fields.get("output_tokens")),
            cast(int | None, fields.get("forward_passes")),
        )
    raw_probabilities = record.get("probabilities")
    if raw_probabilities is not None and type(raw_probabilities) is not dict:
        raise ValueError("Probabilities schema requires an object")
    prediction = Prediction(
        _json(record["answer"]),
        cast(str | None, record.get("error")),
        cast(dict[str, float] | None, raw_probabilities),
        usage,
    )
    validate_prediction(prediction, request)
    return prediction


def case_to_dict(case: Case) -> dict[str, JSONValue]:
    validate_case(case)
    return {
        "request": request_to_dict(case.request),
        "expected": [_json(item) for item in case.expected],
        "group": case.group,
        "source": case.source,
        "split": case.split,
    }


def case_from_dict(value: object) -> Case:
    record = _fields(value, {"request", "expected", "group", "source", "split"}, set())
    expected = record["expected"]
    if type(expected) is not list:
        raise ValueError("Expected schema requires a list")
    return Case(
        request_from_dict(record["request"]),
        tuple(_json(item) for item in cast(list[object], expected)),
        cast(str, record["group"]),
        cast(str, record["source"]),
        cast(str, record["split"]),
    )


def normalize_prediction(value: Prediction | JSONValue, request: Request) -> Prediction:
    """Detach an explicit envelope or wrap a native answer without repairing it."""
    prediction = (
        Prediction(value.answer, value.error, value.probabilities, value.usage)
        if isinstance(value, Prediction)
        else Prediction(value)
    )
    validate_prediction(prediction, request)
    return prediction

"""Sequential evaluation with complete preflight and an isolated public boundary."""

from __future__ import annotations

import hashlib
import math
import time
from collections import defaultdict
from collections.abc import Iterable, Sequence
from typing import cast

from .api import (
    BatchModel,
    Case,
    JSONValue,
    Model,
    Prediction,
    Request,
    canonical_json,
    normalize_prediction,
    prediction_from_dict,
    prediction_to_dict,
)

Group = tuple[str, str, str]


def _group(case: Case) -> Group:
    return case.source, case.split, case.group


def _fraction(correct: int, count: int) -> float | None:
    return correct / count if count else None


def _summary(
    indices: list[int],
    correct: list[bool],
    groups: dict[Group, set[int]],
) -> dict[str, object]:
    members = set(indices)
    complete = [positions for positions in groups.values() if positions <= members]
    groups_correct = sum(all(correct[index] for index in positions) for positions in complete)
    total = sum(correct[index] for index in indices)
    return {
        "count": len(indices),
        "correct": total,
        "accuracy": _fraction(total, len(indices)),
        "complete_groups": {
            "count": len(complete),
            "correct": groups_correct,
            "accuracy": _fraction(groups_correct, len(complete)),
        },
    }


def _classification(
    cases: tuple[Case, ...], predictions: list[Prediction]
) -> list[dict[str, object]]:
    """No averaging across unrelated option identities or ambiguous gold sets."""
    panels: dict[tuple[str, str, str], list[int]] = defaultdict(list)
    for index, case in enumerate(cases):
        panels[case.source, case.request.task, case.split].append(index)
    reports: list[dict[str, object]] = []
    for (source, task, split), indices in sorted(panels.items()):
        ids = {choice.id for choice in cases[indices[0]].request.choices}
        texts = {choice.id: choice.text for choice in cases[indices[0]].request.choices}
        if not ids or any(
            {choice.id for choice in cases[index].request.choices} != ids
            or {choice.id: choice.text for choice in cases[index].request.choices} != texts
            or len(cases[index].expected) != 1
            for index in indices
        ):
            continue
        labels = sorted(ids)
        positions = {label: i for i, label in enumerate(labels)}
        matrix = [[0] * (len(labels) + 1) for _ in labels]
        brier: list[float] = []
        log_loss: list[float] = []
        zero_gold_probability = 0
        for index in indices:
            expected = cast(str, cases[index].expected[0])
            prediction = predictions[index]
            selected = prediction.answer
            column = (
                positions[selected]
                if prediction.error is None and type(selected) is str and selected in ids
                else len(labels)
            )
            matrix[positions[expected]][column] += 1
            if prediction.probabilities is not None:
                probabilities = prediction.probabilities
                brier.append(
                    sum((probabilities[label] - int(label == expected)) ** 2 for label in labels)
                )
                if probabilities[expected] == 0:
                    zero_gold_probability += 1
                else:
                    log_loss.append(-math.log(probabilities[expected]))
        support = [sum(row) for row in matrix]
        recall = {label: _fraction(matrix[i][i], support[i]) for i, label in enumerate(labels)}
        f1 = []
        for i, count in enumerate(support):
            if count:
                predicted = sum(row[i] for row in matrix)
                f1.append(2 * matrix[i][i] / (count + predicted))
        valid_recall = [value for value in recall.values() if value is not None]
        reports.append(
            {
                "source": source,
                "task": task,
                "split": split,
                "count": len(indices),
                "labels": labels,
                "recall": recall,
                "balanced_accuracy": sum(valid_recall) / len(valid_recall),
                "macro_f1": sum(f1) / len(f1),
                "macro_classes": [label for label, n in zip(labels, support, strict=True) if n],
                "confusion": {"rows": labels, "columns": [*labels, "<invalid>"], "counts": matrix},
                "calibration": {
                    "probability_count": len(brier),
                    "coverage": _fraction(len(brier), len(indices)),
                    "multiclass_brier": sum(brier) / len(brier) if brier else None,
                    "log_loss": sum(log_loss) / len(log_loss)
                    if log_loss and not zero_gold_probability
                    else None,
                    "log_loss_infinite": bool(zero_gold_probability),
                    "zero_gold_probability_count": zero_gold_probability,
                },
            }
        )
    return reports


def _preflight(cases: Iterable[Case]) -> tuple[tuple[Case, ...], dict[Group, set[int]]]:
    snapshots: list[Case] = []
    for case in cases:
        if not isinstance(case, Case):
            raise ValueError("Case required")
        # Request/Choice fields are immutable. Case construction validates them
        # and detaches mutable expected JSON without a schema roundtrip.
        snapshots.append(Case(case.request, case.expected, case.group, case.source, case.split))
    frozen = tuple(snapshots)
    ids: set[str] = set()
    source_groups: dict[tuple[str, str], str] = {}
    groups: dict[Group, set[int]] = defaultdict(set)
    for index, case in enumerate(frozen):
        if case.request.id in ids:
            raise ValueError("Duplicate request id")
        ids.add(case.request.id)
        key = case.source, case.group
        if source_groups.setdefault(key, case.split) != case.split:
            raise ValueError("Source group crosses splits")
        groups[_group(case)].add(index)
    return frozen, groups


def _report(
    frozen: tuple[Case, ...],
    groups: dict[Group, set[int]],
    predictions: list[Prediction],
    records: list[dict[str, JSONValue]],
) -> dict[str, object]:
    correct = [
        prediction.error is None
        and canonical_json(prediction.answer) in {canonical_json(a) for a in case.expected}
        for case, prediction in zip(frozen, predictions, strict=True)
    ]
    report = _summary(list(range(len(frozen))), correct, groups)
    report["version"] = 1
    for name in ("source", "task", "split"):
        slices: dict[str, list[int]] = defaultdict(list)
        for index, case in enumerate(frozen):
            value = case.request.task if name == "task" else getattr(case, name)
            slices[value].append(index)
        report["by_" + name] = {
            key: _summary(indices, correct, groups) for key, indices in sorted(slices.items())
        }
    report["classification"] = _classification(frozen, predictions)
    report["predictions"] = records
    return report


def _public_request(request: Request) -> Request:
    return Request(
        hashlib.sha256(request.id.encode("utf-8", errors="surrogatepass")).hexdigest(),
        request.task,
        request.text,
        request.choices,
    )


def evaluate(
    cases: Iterable[Case], model: Model, *, batch: BatchModel | None = None, batch_size: int = 1
) -> dict[str, object]:
    """Validate the complete cohort before the first model call; never retry."""
    started = time.perf_counter()
    if not callable(model):
        raise ValueError("Model must be callable")
    if type(batch_size) is not int or batch_size < 1:
        raise ValueError("Batch size must be a positive integer")
    if batch is not None and not callable(batch):
        raise ValueError("Batch model must be callable")
    if batch is None and batch_size != 1:
        raise ValueError("Batch size requires an explicit batch callable")
    # Snapshot all gold and inputs before user code executes or mutates caller data.
    frozen, groups = _preflight(cases)

    predictions: list[Prediction] = []
    records: list[dict[str, JSONValue]] = []
    inference_seconds = 0.0
    batch_count = 0
    if batch is None:
        for case in frozen:
            request = case.request
            public = _public_request(request)
            call_started = time.perf_counter()
            try:
                prediction = normalize_prediction(model(public), public)
            except Exception as error:
                prediction = Prediction(None, f"{type(error).__name__}: {error}")
            elapsed = time.perf_counter() - call_started
            inference_seconds += elapsed
            predictions.append(prediction)
            records.append(
                {"id": request.id, **prediction_to_dict(prediction), "elapsed_seconds": elapsed}
            )
    else:
        for start in range(0, len(frozen), batch_size):
            cohort = frozen[start : start + batch_size]
            public_batch = tuple(_public_request(case.request) for case in cohort)
            call_started = time.perf_counter()
            try:
                raw = batch(public_batch)
                if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes, bytearray)):
                    raise ValueError("Batch must return an ordered sequence of predictions")
                if len(raw) != len(cohort):
                    raise ValueError("Batch prediction count must match request count")
                results: list[Prediction] = []
                for value, request in zip(raw, public_batch, strict=True):
                    try:
                        results.append(normalize_prediction(value, request))
                    except Exception as error:
                        results.append(Prediction(None, f"{type(error).__name__}: {error}"))
            except Exception as error:
                results = [Prediction(None, f"{type(error).__name__}: {error}") for _ in cohort]
            elapsed = time.perf_counter() - call_started
            inference_seconds += elapsed
            for case, prediction in zip(cohort, results, strict=True):
                predictions.append(prediction)
                records.append(
                    {
                        "id": case.request.id,
                        **prediction_to_dict(prediction),
                        "elapsed_seconds": None,
                        "batch_index": batch_count,
                        "batch_elapsed_seconds": elapsed,
                    }
                )
            batch_count += 1
    report = _report(frozen, groups, predictions, records)
    report["timing"] = {
        "elapsed_seconds": time.perf_counter() - started,
        "inference_seconds": inference_seconds,
        "mode": "sequential" if batch is None else "explicit_batch",
        "batch_size": batch_size,
        "batch_count": batch_count,
        "measurement": "model call and output normalization; batch time is not per-item latency",
    }
    return report


def score_predictions(cases: Iterable[Case], records: Iterable[object]) -> dict[str, object]:
    """Re-score strict saved outputs; missing records fail and extra IDs reject."""
    frozen, groups = _preflight(cases)
    by_id = {case.request.id: case for case in frozen}
    saved: dict[str, tuple[Prediction, dict[str, JSONValue]]] = {}
    for value in records:
        if type(value) is not dict:
            raise ValueError("Prediction record requires an object")
        record = cast(dict[str, object], value)
        if not {"id", "answer"} <= record.keys() or record.keys() - {
            "id",
            "answer",
            "error",
            "probabilities",
            "usage",
            "elapsed_seconds",
            "batch_index",
            "batch_elapsed_seconds",
        }:
            raise ValueError("Prediction record has missing or unknown fields")
        identity = record["id"]
        if type(identity) is not str or identity not in by_id:
            raise ValueError("Unknown prediction id")
        if identity in saved:
            raise ValueError("Duplicate prediction id")
        prediction = prediction_from_dict(
            {
                key: item
                for key, item in record.items()
                if key not in ("id", "elapsed_seconds", "batch_index", "batch_elapsed_seconds")
            },
            by_id[identity].request,
        )
        output: dict[str, JSONValue] = {"id": identity, **prediction_to_dict(prediction)}
        if "elapsed_seconds" in record:
            elapsed = record["elapsed_seconds"]
            if elapsed is None:
                if not {"batch_index", "batch_elapsed_seconds"} <= record.keys():
                    raise ValueError("Null per-item latency requires batch timing")
            elif (
                type(elapsed) not in (float, int)
                or not math.isfinite(cast(float, elapsed))
                or cast(float, elapsed) < 0
            ):
                raise ValueError("Elapsed seconds must be finite and nonnegative")
            output["elapsed_seconds"] = cast(float | None, elapsed)
        if {"batch_index", "batch_elapsed_seconds"} & record.keys():
            if not {"batch_index", "batch_elapsed_seconds", "elapsed_seconds"} <= record.keys():
                raise ValueError("Batch timing fields must be supplied together")
            index, elapsed = record["batch_index"], record["batch_elapsed_seconds"]
            if type(index) is not int or index < 0 or record["elapsed_seconds"] is not None:
                raise ValueError("Invalid batch index or per-item latency")
            if (
                type(elapsed) not in (float, int)
                or not math.isfinite(cast(float, elapsed))
                or cast(float, elapsed) < 0
            ):
                raise ValueError("Batch elapsed seconds must be finite and nonnegative")
            output["batch_index"] = index
            output["batch_elapsed_seconds"] = cast(float, elapsed)
        saved[identity] = prediction, output
    predictions: list[Prediction] = []
    outputs: list[dict[str, JSONValue]] = []
    for case in frozen:
        identity = case.request.id
        prediction, output = saved.get(
            identity,
            (
                Prediction(None, "Missing prediction"),
                {
                    "id": identity,
                    "answer": None,
                    "error": "Missing prediction",
                    "probabilities": None,
                    "usage": None,
                },
            ),
        )
        predictions.append(prediction)
        outputs.append(output)
    return _report(frozen, groups, predictions, outputs)

"""Explicit local native imports. No network, invented labels or executable actions."""

from __future__ import annotations

import hashlib
import re
from dataclasses import dataclass
from pathlib import Path
from typing import cast

from .api import Case, Choice, JSONValue, Request, canonical_json, strict_json_loads
from .io import validate_cases


@dataclass(frozen=True)
class ImportResult:
    cases: tuple[Case, ...]
    provenance: dict[str, object]
    rejected: tuple[dict[str, object], ...]


def _object(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or not all(isinstance(key, str) for key in value):
        raise ValueError("expected string-keyed object")
    return cast(dict[str, object], value)


def _string(value: object) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError("expected nonempty string")
    return value


def _list(value: object) -> list[object]:
    if not isinstance(value, list) or not value:
        raise ValueError("expected nonempty list")
    return value


def _fields(value: dict[str, object], required: set[str], optional: set[str] | None = None) -> None:
    if not required <= set(value) or set(value) - required - (optional or set()):
        raise ValueError("unsupported source schema fields")


def _receipt(
    path: Path, revision: str, source: str, accepted: int, rejected: int
) -> dict[str, object]:
    if not re.fullmatch(r"[0-9a-f]{40}", revision):
        raise ValueError("pin a full 40-character upstream commit revision")
    return {
        "source": source,
        "revision": revision,
        "input_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "input_filename": path.name,
        "license": "MIT",
        "accepted": accepted,
        "rejected": rejected,
        "importer": "native-v1",
        "scope": "local supplied file only; source authenticity is caller-provided",
    }


def import_jevbench(path: str | Path, revision: str) -> ImportResult:
    """Admit original-authored MIT public records, retaining native noul/choice/score."""
    target = Path(path)
    cases: list[Case] = []
    rejected: list[dict[str, object]] = []
    for line_number, line in enumerate(target.read_text(encoding="utf-8").splitlines(), 1):
        value = _object(strict_json_loads(line))
        _fields(
            value,
            {"id", "family", "state", "question", "labels", "expected", "split"},
            {"group", "provenance"},
        )
        identifier = _string(value["id"])
        provenance = _object(value.get("provenance", {}))
        # Admit authored originals; imported router tasks retain upstream terms.
        if (
            provenance.get("source") != "JevBench original authored scenario"
            or provenance.get("license") != "MIT"
            or value["split"] != "public"
        ):
            rejected.append(
                {
                    "id": identifier,
                    "line": line_number,
                    "reason": "outside original MIT public scope",
                }
            )
            continue
        if value["expected"] is None or provenance.get("exclude_reason") is not None:
            rejected.append(
                {"id": identifier, "line": line_number, "reason": "unscored or upstream excluded"}
            )
            continue
        question = _object(value["question"])
        _fields(question, {"type", "instructions", "criteria"})
        kind = _string(question["type"])
        if kind not in {"noul", "choice", "score"}:
            raise ValueError("unsupported JevBench question type")
        labels = tuple(_string(label) for label in _list(value["labels"]))
        if len(set(labels)) != len(labels):
            raise ValueError("duplicate source labels")
        expected = cast(JSONValue, value["expected"])
        criteria = question["criteria"]
        if kind == "score":
            if type(expected) is not int or str(expected) not in labels:
                raise ValueError("score expected must be a native integer level")
            if not isinstance(criteria, list) or len(criteria) != len(labels):
                raise ValueError("score criteria must align with levels")
            choices: tuple[Choice, ...] = ()
        elif kind == "noul":
            if labels != ("no", "yes") or expected not in labels:
                raise ValueError("noul requires native no/yes labels")
            mapping = _object(criteria)
            if set(mapping) != {"false", "true"}:
                raise ValueError("noul criteria require false/true")
            choices = tuple(
                Choice(label, _string(mapping[key]))
                for label, key in (("no", "false"), ("yes", "true"))
            )
        else:
            mapping = _object(criteria)
            if set(mapping) != set(labels) or expected not in labels:
                raise ValueError("choice criteria/expected must match source labels")
            choices = tuple(Choice(label, _string(mapping[label])) for label in labels)
        _string(question["instructions"])
        state = value["state"]
        if isinstance(state, dict) and set(state) & {
            "expected",
            "label",
            "ground_truth",
            "answer_key",
        }:
            raise ValueError("source state includes answer-key field")
        text = canonical_json({"state": state, "question": question, "labels": list(labels)})
        family = _string(value["family"])
        group = value.get("group")
        cases.append(
            Case(
                Request(identifier, "jevbench/" + kind, text, choices),
                (expected,),
                identifier if group is None else _string(group),
                "JevBench/" + family,
                "public",
            )
        )
    values = validate_cases(cases)
    return ImportResult(
        values,
        _receipt(target, revision, "JevBench/original", len(values), len(rejected)),
        tuple(rejected),
    )


def import_logicbench(
    path: str | Path, revision: str, variant: str = "Eval", task: str = "BQA"
) -> ImportResult:
    """Import verified native Eval BQA/MCQA schemas with their original answers."""
    if variant != "Eval" or task not in {"BQA", "MCQA"}:
        raise ValueError("only LogicBench Eval BQA/MCQA schemas are currently supported")
    target = Path(path)
    root = _object(strict_json_loads(target.read_text(encoding="utf-8")))
    _fields(root, {"type", "axiom", "samples"})
    kind = _string(root["type"])
    axiom = _string(root["axiom"])
    cases: list[Case] = []
    seen: set[int] = set()
    for sample_raw in _list(root["samples"]):
        sample = _object(sample_raw)
        _fields(
            sample,
            {"id", "context", "qa_pairs"}
            if task == "BQA"
            else {"id", "context", "question", "choices", "answer"},
        )
        number = sample["id"]
        if type(number) is not int or number in seen:
            raise ValueError("sample IDs must be unique native integers")
        seen.add(number)
        context = _string(sample["context"])
        group = f"{kind}:{axiom}:{number}"
        if task == "MCQA":
            mapping = _object(sample["choices"])
            if len(mapping) < 2:
                raise ValueError("MCQA requires at least two choices")
            answer = _string(sample["answer"])
            if answer not in mapping:
                raise ValueError("MCQA answer must belong to supplied choices")
            choices = tuple(
                Choice(label, _string(description)) for label, description in mapping.items()
            )
            text = canonical_json({"context": context, "question": _string(sample["question"])})
            cases.append(
                Case(
                    Request(f"logicbench:MCQA:{group}", "logicbench/MCQA", text, choices),
                    (answer,),
                    group,
                    "LogicBench/Eval/" + kind + "/" + axiom,
                    "evaluation",
                )
            )
            continue
        for index, pair_raw in enumerate(_list(sample["qa_pairs"])):
            pair = _object(pair_raw)
            _fields(pair, {"question", "answer"})
            answer = _string(pair["answer"])
            if answer not in {"yes", "no"}:
                raise ValueError("unsupported native BQA label")
            text = canonical_json({"context": context, "question": _string(pair["question"])})
            cases.append(
                Case(
                    Request(
                        f"logicbench:BQA:{group}:{index}",
                        "logicbench/BQA",
                        text,
                        (Choice("yes", "yes"), Choice("no", "no")),
                    ),
                    (answer,),
                    group,
                    "LogicBench/Eval/" + kind + "/" + axiom,
                    "evaluation",
                )
            )
    values = validate_cases(cases)
    return ImportResult(
        values, _receipt(target, revision, "LogicBench/Eval/" + task, len(values), 0), ()
    )

"""Explicit local factory loading and bounded standard-library HTTP transport."""

from __future__ import annotations

import http.client
import importlib
import math
import urllib.error
import urllib.parse
import urllib.request
from typing import cast

from .api import (
    Model,
    Prediction,
    Request,
    canonical_json,
    prediction_from_dict,
    request_to_dict,
    strict_json_loads,
    validate_request,
)

MAX_BODY_BYTES = 1_048_576


def load_model(specification: str) -> Model:
    """Import an explicitly named local no-argument factory, once per load.

    Importing the module executes its code. No remote code or weights are fetched
    by this loader; the user-selected factory owns its dependencies and loading.
    """
    if not isinstance(specification, str) or specification.count(":") != 1:
        raise ValueError("model must be module:factory")
    module_name, factory_name = specification.split(":")
    if not module_name or not all(part.isidentifier() for part in module_name.split(".")):
        raise ValueError("invalid model module name")
    if not factory_name.isidentifier():
        raise ValueError("factory must be a single attribute name")
    factory = getattr(importlib.import_module(module_name), factory_name)
    if not callable(factory):
        raise TypeError("model factory must be callable")
    model = factory()
    if not callable(model):
        raise TypeError("model factory must return a callable")
    return cast(Model, model)


def first_model() -> Model:
    """A deliberately weak control: select the first public choice, or error."""

    def choose(request: Request) -> Prediction:
        validate_request(request)
        if not request.choices:
            return Prediction(answer=None, error="first control requires choices")
        return Prediction(answer=request.choices[0].id)

    return choose


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(
        self,
        req: urllib.request.Request,
        fp: object,
        code: int,
        msg: str,
        headers: object,
        newurl: str,
    ) -> None:
        return None


class HTTPModel:
    """Call one /decide endpoint; transport/schema failures remain failures."""

    def __init__(self, url: str, timeout: float = 30.0) -> None:
        if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
            raise ValueError("timeout must be a finite positive number")
        if not math.isfinite(timeout) or timeout <= 0:
            raise ValueError("timeout must be a finite positive number")
        parts = urllib.parse.urlsplit(url)
        if (
            parts.scheme not in {"http", "https"}
            or not parts.hostname
            or parts.username is not None
            or parts.password is not None
            or parts.query
            or parts.fragment
            or parts.path not in {"", "/", "/decide"}
        ):
            raise ValueError("HTTP model URL must be an http(s) origin or /decide endpoint")
        self.url = urllib.parse.urlunsplit((parts.scheme, parts.netloc, "/decide", "", ""))
        self.timeout = float(timeout)
        self._opener = urllib.request.build_opener(_NoRedirect())

    def __call__(self, request: Request) -> Prediction:
        validate_request(request)
        body = canonical_json(request_to_dict(request)).encode("utf-8")
        if len(body) > MAX_BODY_BYTES:
            return Prediction(answer=None, error="HTTP request exceeds byte limit")
        outgoing = urllib.request.Request(
            self.url,
            data=body,
            headers={"Content-Type": "application/json", "Accept": "application/json"},
            method="POST",
        )
        try:
            with self._opener.open(outgoing, timeout=self.timeout) as response:
                if response.status != 200:
                    raise ValueError(f"HTTP status {response.status}")
                if response.headers.get_content_type() != "application/json":
                    raise ValueError("HTTP response must be application/json")
                raw = response.read(MAX_BODY_BYTES + 1)
                if len(raw) > MAX_BODY_BYTES:
                    raise ValueError("HTTP response exceeds byte limit")
            return prediction_from_dict(strict_json_loads(raw.decode("utf-8")), request)
        except (
            OSError,
            ValueError,
            TypeError,
            RecursionError,
            urllib.error.URLError,
            http.client.HTTPException,
        ) as exc:
            return Prediction(answer=None, error=f"HTTP transport: {type(exc).__name__}: {exc}")

"""Correctness of coupled judgments/actions and strict interventions, not flips alone."""

from __future__ import annotations

from collections import defaultdict
from collections.abc import Sequence
from typing import cast

from .api import Case, JSONValue, canonical_json
from .evaluation import score_predictions
from .imports import _object, _string


def score_relationship(
    cases: Sequence[Case], records: Sequence[dict[str, object]], metadata: dict[str, object]
) -> dict[str, object]:
    """Score complete declared pairs; missing results are failures, partial pairs invalid."""
    report = score_predictions(cases, records)
    saved = cast(list[dict[str, JSONValue]], report["predictions"])
    indexed = {row["id"]: row for row in saved}
    values: dict[tuple[str, str, str, str], bool] = {}
    families: dict[str, dict[str, object]] = {}
    judgment_cases: list[Case] = []
    judgment_records: list[dict[str, object]] = []
    for case in cases:
        row = _object(metadata.get(case.request.id))
        family = _string(row["family"])
        intervention = _string(row["intervention"])
        presentation = _string(row["presentation"])
        task = _string(row["task"])
        if family != case.group or row.get("split") != case.split:
            raise ValueError("Relationship metadata disagrees with case family/split")
        width = row.get("width")
        if type(width) is not int or width < 1 or task not in {"judgment", "action"}:
            raise ValueError("Invalid relationship width/task")
        if len(case.request.choices) != (3 if task == "judgment" else width + 2):
            raise ValueError("Relationship menu does not match declared task/width")
        key = family, intervention, presentation, task
        if key in values:
            raise ValueError("Duplicate declared relationship member")
        prediction = indexed[case.request.id]
        values[key] = prediction["error"] is None and canonical_json(prediction["answer"]) in {
            canonical_json(answer) for answer in case.expected
        }
        if family in families and any(
            families[family].get(field) != row.get(field) for field in ("split", "width")
        ):
            raise ValueError("Inconsistent family metadata")
        families[family] = row
        if task == "judgment":
            judgment_cases.append(case)
            judgment_records.append(cast(dict[str, object], prediction))
    selected_ids = {case.request.id for case in cases}
    declared_ids = {
        identifier
        for identifier, value in metadata.items()
        if _object(value).get("family") in families
    }
    if selected_ids != declared_ids:
        raise ValueError("Incomplete declared relationship family: missing metadata members")
    panels: dict[str, list[bool]] = defaultdict(list)
    for family, row in families.items():
        keys = [key for key in values if key[0] == family]
        views = {key[2] for key in keys}
        required = {
            (family, intervention, view, task)
            for intervention in ("original", "fact", "operator")
            for view in views
            for task in ("judgment", "action")
        }
        if set(keys) != required or views not in (
            {"familiar", "rename", "order", "wording"},
            {"familiar", "rename", "order", "layout"},
        ):
            raise ValueError("Incomplete declared intervention/task family")
        panel = f"{row['split']}/width-{row['width']}"
        panels[panel + "/complete_family"].append(all(values[key] for key in keys))
        for view in views:
            for intervention in ("original", "fact", "operator"):
                panels[panel + "/joint_judgment_action"].append(
                    all(values[family, intervention, view, task] for task in ("judgment", "action"))
                )
            for intervention in ("fact", "operator"):
                for task in ("judgment", "action"):
                    panels[panel + f"/{intervention}_strict_{task}"].append(
                        values[family, "original", view, task]
                        and values[family, intervention, view, task]
                    )
        for view in views - {"familiar"}:
            for intervention in ("original", "fact", "operator"):
                for task in ("judgment", "action"):
                    panels[panel + f"/{view}_strict_{task}"].append(
                        values[family, intervention, "familiar", task]
                        and values[family, intervention, view, task]
                    )
    judgment = score_predictions(judgment_cases, judgment_records)
    return {
        "schema_version": 1,
        "panels": {
            name: {
                "count": len(outcomes),
                "correct": sum(outcomes),
                "accuracy": sum(outcomes) / len(outcomes),
            }
            for name, outcomes in sorted(panels.items())
        },
        "judgment_classification": judgment["classification"],
        "policy": (
            "All declared members must be correct. Answer changes alone earn no credit. "
            "Each width/split remains separate."
        ),
    }

"""Conservative split quarantine and auditable release composition."""

from __future__ import annotations

import hashlib
import unicodedata
from collections import Counter, defaultdict
from collections.abc import Iterable
from dataclasses import dataclass

from .api import Case, canonical_json, strict_json_loads, validate_case
from .io import validate_cases


@dataclass(frozen=True)
class Composition:
    cases: tuple[Case, ...]
    quarantined: tuple[Case, ...]
    audit: dict[str, object]


def content_key(case: Case) -> str:
    """Native public state only: repeated contexts stay together across formats."""
    text = case.request.text
    try:
        value = strict_json_loads(text)
    except ValueError:
        value = None
    if isinstance(value, dict) and "state" in value:
        state = value["state"]
        text = state if isinstance(state, str) else canonical_json(state)
    normalized = " ".join(unicodedata.normalize("NFKC", text).casefold().split())
    return hashlib.sha256(normalized.encode()).hexdigest()


def compose(
    cases: Iterable[Case], scored_splits: tuple[str, ...] = ("dev", "test", "public")
) -> Composition:
    """Quarantine entire connected components spanning original source splits.

    Connections are explicit family identity or normalized public context. No
    split is relabeled, and training rows never become scored observations.
    """
    values = tuple(cases)
    parents = list(range(len(values)))

    def find(index: int) -> int:
        while parents[index] != index:
            parents[index] = parents[parents[index]]
            index = parents[index]
        return index

    def union(left: int, right: int) -> None:
        parents[find(left)] = find(right)

    seen: dict[tuple[str, str], int] = {}
    ids: set[str] = set()
    for index, case in enumerate(values):
        validate_case(case)
        if case.request.id in ids:
            raise ValueError("duplicate request ID across release")
        ids.add(case.request.id)
        # Shared context is a conservative exposure risk across source policies;
        # this does not assert that their labels have interchangeable meanings.
        for key in ((case.source, case.group), ("__public_context__", content_key(case))):
            if key in seen:
                union(index, seen[key])
            else:
                seen[key] = index
    components: dict[int, list[Case]] = defaultdict(list)
    for index, case in enumerate(values):
        components[find(index)].append(case)
    rejected: list[Case] = []
    kept: list[Case] = []
    conflicts: list[dict[str, object]] = []
    for component in components.values():
        splits = sorted({case.split for case in component})
        answers: dict[str, set[str]] = {}
        contradictory = False
        for case in component:
            try:
                public = strict_json_loads(case.request.text)
            except ValueError:
                public = case.request.text
            if isinstance(public, dict) and "state" in public:
                public = {**public, "state": content_key(case)}
            public_key = canonical_json(
                {
                    "task": case.request.task,
                    "public": public,
                    "choices": [{"id": c.id, "text": c.text} for c in case.request.choices],
                }
            )
            allowed = {canonical_json(answer) for answer in case.expected}
            if public_key in answers:
                allowed &= answers[public_key]
                contradictory |= not allowed
            answers[public_key] = allowed
        if len(splits) > 1 or contradictory:
            rejected.extend(component)
            conflicts.append(
                {
                    "ids": [c.request.id for c in component],
                    "splits": splits,
                    "reason": (
                        "contradictory references for normalized context "
                        "and identical question/menu"
                    )
                    if contradictory
                    else "connected context/family crosses official splits",
                }
            )
        else:
            kept.extend(c for c in component if c.split in scored_splits)
    order = {case.request.id: index for index, case in enumerate(values)}
    kept.sort(key=lambda case: order[case.request.id])
    rejected.sort(key=lambda case: order[case.request.id])
    return Composition(
        validate_cases(kept),
        tuple(rejected),
        {
            "input_count": len(values),
            "scored_count": len(kept),
            "quarantined_count": len(rejected),
            "reference_only_count": len(values) - len(kept) - len(rejected),
            "scored_splits": list(scored_splits),
            "input_source_splits": dict(Counter(f"{c.source}/{c.split}" for c in values)),
            "conflicts": conflicts,
            "limitations": [
                "context normalization detects exact normalized overlap, not paraphrases",
                "paraphrase contamination and pretrained-model exposure remain unknown",
            ],
        },
    )

"""Frozen matched perturbations of native choice tasks, with clustered evidence."""

from __future__ import annotations

import hashlib
import math
import random
from collections import defaultdict
from collections.abc import Sequence
from dataclasses import replace
from itertools import permutations, product
from typing import cast

from .adapters.native import native_request
from .api import (
    Case,
    Choice,
    Model,
    Request,
    canonical_json,
    case_from_dict,
    case_to_dict,
    strict_json_loads,
)
from .evaluation import evaluate, score_predictions
from .io import validate_cases
from .statistics import grouped_interval, wilson_interval
from .tracks.requirements import SEMANTICS

VERSION = "matched-robustness-v1"
AXES = ("instructions", "descriptions", "state")
Panel = tuple[str, str, str, int, int]


def public_hash(request: Request) -> str:
    """Bind review to task, complete text and menu, excluding evaluator identity."""
    return hashlib.sha256(
        canonical_json(
            {
                "task": request.task,
                "text": request.text,
                "choices": [{"id": c.id, "text": c.text} for c in request.choices],
            }
        ).encode()
    ).hexdigest()


def _object(value: object) -> dict[str, object]:
    if not isinstance(value, dict) or any(not isinstance(key, str) for key in value):
        raise ValueError("Robustness objects require string keys")
    return cast(dict[str, object], value)


def authored_wordings(request: Request) -> list[dict[str, object]]:
    """Controlled authored equivalents; never guess paraphrases for source data."""
    state, question, _ = native_request(request)
    if not isinstance(state, dict) or not {"facts", "goal", "actions"} <= state.keys():
        return []
    judgment = "queried_action" in state
    original = (
        "Judge whether the queried action's requirements are met, violated, or unknown."
        if judgment
        else "Choose any first action of a shortest valid plan to make the goal true. "
        "Choose stop if already true; abstain only if no valid plan can achieve it."
    )
    if question["instructions"] != SEMANTICS + " " + original:
        return []
    descriptions: tuple[dict[str, str], ...]
    if judgment:
        if {c.id for c in request.choices} != {"met", "violated", "unknown"}:
            return []
        instructions = (
            "Using only the supplied facts and the stated three-valued rules, classify the "
            "queried action's prerequisite expression: met for true, violated for false, "
            "and unknown when neither truth nor falsity is established.",
            "Evaluate the requirements of the named action under the supplied observations. "
            "Return met if they evaluate to true, violated if they evaluate to false, "
            "or unknown if their value remains undetermined.",
        )
        descriptions = (
            {
                "met": "The prerequisite expression evaluates to true",
                "violated": "The prerequisite expression evaluates to false",
                "unknown": "The prerequisite expression has an undetermined truth value",
            },
            {
                "met": "The requirements are established as satisfied",
                "violated": "The requirements are established as not satisfied",
                "unknown": "The observations establish neither satisfaction nor violation",
            },
        )
    else:
        actions = state["actions"]
        if not isinstance(actions, list):
            return []
        action_ids = {cast(str, _object(action).get("id")) for action in actions}
        if {c.id for c in request.choices} != action_ids | {"__stop__", "__abstain__"}:
            return []
        instructions = (
            "Among valid plans that establish the goal, select an initial action of any "
            "plan with the fewest steps. All equally short alternatives are acceptable. "
            "Select stop if the goal is already true, and abstain only if it is unreachable.",
            "Find a shortest sequence of permitted transitions that makes the target fact "
            "true, and choose its first action. Ties may be resolved by any optimal choice. "
            "If the target is already true, stop; if no valid sequence reaches it, abstain.",
        )
        descriptions = tuple(
            {
                c.id: (
                    (
                        "Finish: the target fact is already true"
                        if index == 0
                        else "Stop execution because the goal already holds"
                    )
                    if c.id == "__stop__"
                    else (
                        "Decline: the goal cannot be reached by any valid plan"
                        if index == 0
                        else "Abstain because no permitted sequence achieves the goal"
                    )
                    if c.id == "__abstain__"
                    else ("Perform action " if index == 0 else "Apply candidate ") + c.id
                )
                for c in request.choices
            }
            for index in range(2)
        )
    return [
        {
            "axis": axis,
            "name": f"authored-{index + 1}",
            "value": SEMANTICS + " " + value if isinstance(value, str) else value,
            "base_sha256": public_hash(request),
            "reviewer": VERSION,
            "rationale": "Controlled authored equivalent; facts, logic, objective, "
            "ties, terminal conditions and label meanings retained",
        }
        for axis, values in (("instructions", instructions), ("descriptions", descriptions))
        for index, value in enumerate(values)
    ]


def _wordings(request: Request, rows: object) -> dict[str, list[tuple[str, object]]]:
    state, question, _ = native_request(request)
    originals: dict[str, object] = {
        "instructions": question["instructions"],
        "descriptions": {c.id: c.text for c in request.choices},
        "state": state,
    }
    axes = {axis: [("original", originals[axis])] for axis in AXES}
    if not isinstance(rows, list):
        raise ValueError("Wording bank entries must be arrays")
    for raw in rows:
        row = _object(raw)
        if set(row) != {"axis", "name", "value", "base_sha256", "reviewer", "rationale"}:
            raise ValueError("Wording entry has missing or unknown fields")
        axis, name = row["axis"], row["name"]
        if axis not in AXES or not isinstance(name, str) or not name.strip():
            raise ValueError("Wording axis/name is invalid")
        if any(
            not isinstance(row[field], str) or not str(row[field]).strip()
            for field in ("reviewer", "rationale")
        ):
            raise ValueError("Wording changes require reviewer and semantic rationale")
        if row["base_sha256"] != public_hash(request):
            raise ValueError("Wording review is not bound to this public request")
        value = row["value"]
        if axis == "descriptions":
            texts = _object(value)
            if set(texts) != {c.id for c in request.choices} or any(
                not isinstance(text, str) or not text.strip() for text in texts.values()
            ):
                raise ValueError("Description wording must cover exactly the original labels")
        elif not isinstance(value, str) or not value.strip():
            raise ValueError("Instruction/state paraphrases must be nonempty text")
        elif axis == "state" and not isinstance(state, str):
            raise ValueError("Context paraphrases require an original text state")
        if any(
            old_name == name or canonical_json(old) == canonical_json(value)
            for old_name, old in axes[axis]
        ):
            raise ValueError("Duplicate or unchanged wording variant")
        axes[axis].append((name, value))
    return axes


def _orders(
    request: Request, seed: int, count: int, exhaustive_max_width: int = 4
) -> tuple[tuple[Choice, ...], ...]:
    original = request.choices
    width = len(original)
    if width <= exhaustive_max_width:
        return tuple(permutations(original))  # original is first, all orders exhausted
    target = min(count, math.factorial(width))
    orders = [original, tuple(reversed(original))]
    # Spread rotations over the menu before seeded random permutations.
    for step in range(1, min(width, max(2, target // 2))):
        offset = step * width // min(width, max(2, target // 2))
        order = original[offset:] + original[:offset]
        if order not in orders and len(orders) < target:
            orders.append(order)
    rng = random.Random(f"{VERSION}/orders/{seed}/{request.id}")
    while len(orders) < target:
        shuffled = list(original)
        rng.shuffle(shuffled)
        order = tuple(shuffled)
        if order not in orders:
            orders.append(order)
    return tuple(orders)


def build_robustness(
    cases: Sequence[Case],
    *,
    seed: int = 17,
    order_count: int = 12,
    repeats: int = 3,
    wording_bank: dict[str, object] | None = None,
    max_cases: int = 100000,
    exhaustive_max_width: int = 4,
) -> tuple[tuple[Case, ...], dict[str, object]]:
    """Full matched factorial; no gold-dependent sampling or source overwrites."""
    bases = validate_cases(cases)
    if not bases or any(
        type(v) is not int for v in (seed, order_count, repeats, max_cases, exhaustive_max_width)
    ):
        raise ValueError("Nonempty cohort and integer design settings required")
    if order_count < 2 or repeats < 2 or max_cases < 1:
        raise ValueError("At least two orders/repeats and a positive case cap required")
    if not 2 <= exhaustive_max_width <= 4:
        raise ValueError("Exhaustive menu threshold must be 2..4")
    supplied = _object(strict_json_loads(canonical_json(wording_bank or {})))
    if set(supplied) - {c.request.id for c in bases}:
        raise ValueError("Wording bank names unknown base cases")
    bank: dict[str, object] = {}
    plans = []
    count = 0
    for case in bases:
        if case.request.task != "jevbench/choice" or len(case.request.choices) < 2:
            raise ValueError("Robustness requires native jevbench/choice menus of width >= 2")
        native_request(case.request)
        rows = supplied.get(case.request.id, authored_wordings(case.request))
        bank[case.request.id] = rows
        wordings = _wordings(case.request, rows)
        width = len(case.request.choices)
        permutation_count = (
            math.factorial(width)
            if width <= exhaustive_max_width
            else min(order_count, math.factorial(width))
        )
        count += permutation_count * math.prod(len(v) for v in wordings.values()) * repeats
        if count > max_cases:
            raise ValueError(
                f"Robustness expansion exceeds max_cases={max_cases}; "
                "select a smaller cohort or explicitly increase the cap"
            )
        orders = _orders(case.request, seed, order_count, exhaustive_max_width)
        plans.append((case, wordings, orders))
    expanded = []
    metadata: dict[str, object] = {}
    coverage: dict[str, object] = {}
    for base, wordings, orders in plans:
        coverage[base.request.id] = {
            "width": len(base.request.choices),
            "orders": len(orders),
            "exhaustive": len(orders) == math.factorial(len(base.request.choices)),
            "wordings": {axis: len(values) - 1 for axis, values in wordings.items()},
            "label_positions": {
                c.id: sorted({order.index(c) for order in orders}) for c in base.request.choices
            },
        }
        for order_index, order in enumerate(orders):
            for instruction, description, state in product(*(wordings[axis] for axis in AXES)):
                for repeat in range(repeats):
                    condition = {
                        "base_id": base.request.id,
                        "order": order_index,
                        "instructions": instruction[0],
                        "descriptions": description[0],
                        "state": state[0],
                        "repeat": repeat,
                    }
                    identifier = hashlib.sha256(
                        (VERSION + canonical_json(condition)).encode()
                    ).hexdigest()
                    body = _object(strict_json_loads(base.request.text))
                    question = _object(body["question"])
                    texts = _object(description[1])
                    changed = order_index != 0 or any(
                        item[0] != "original" for item in (instruction, description, state)
                    )
                    if changed:
                        body["state"] = state[1]
                        body["question"] = {
                            **question,
                            "instructions": instruction[1],
                            "criteria": texts,
                        }
                        body["labels"] = [c.id for c in order]
                    request = Request(
                        identifier,
                        base.request.task,
                        canonical_json(body),
                        tuple(Choice(c.id, cast(str, texts[c.id])) for c in order),
                    )
                    native_request(request)
                    expanded.append(replace(base, request=request))
                    metadata[identifier] = condition
    random.Random(f"{VERSION}/schedule/{seed}").shuffle(expanded)
    protocol: dict[str, object] = {
        "version": VERSION,
        "seed": seed,
        "order_count": order_count,
        "repeats": repeats,
        "max_cases": max_cases,
        "bases": [case_to_dict(base) for base in bases],
        "wording_bank": bank,
        "case_metadata": metadata,
        "coverage": coverage,
        "policy": "Frozen full factorial, seeded interleaving, matched repeats; "
        "canonical JSON for all conditions; public IDs fixed within base; "
        "original gold/family/split retained",
    }
    if exhaustive_max_width != 4:
        protocol["exhaustive_max_width"] = exhaustive_max_width
    return validate_cases(expanded), protocol


def validate_robustness(cases: Sequence[Case], protocol: dict[str, object]) -> None:
    """Reconstruct the entire declared experiment before any inference."""
    if protocol.get("version") != VERSION or not isinstance(protocol.get("bases"), list):
        raise ValueError("Unsupported robustness protocol")
    bases = tuple(case_from_dict(row) for row in cast(list[object], protocol["bases"]))
    expected, rebuilt = build_robustness(
        bases,
        seed=cast(int, protocol.get("seed")),
        order_count=cast(int, protocol.get("order_count")),
        repeats=cast(int, protocol.get("repeats")),
        max_cases=cast(int, protocol.get("max_cases")),
        wording_bank=_object(protocol.get("wording_bank")),
        exhaustive_max_width=cast(int, protocol.get("exhaustive_max_width", 4)),
    )
    if canonical_json(protocol) != canonical_json(rebuilt) or (
        [case_to_dict(c) for c in cases] != [case_to_dict(c) for c in expected]
    ):
        raise ValueError("Robustness cohort differs from its complete declared design")


def evaluate_robustness(
    cases: Sequence[Case], model: Model, protocol: dict[str, object]
) -> dict[str, object]:
    validate_robustness(cases, protocol)
    metadata = _object(protocol["case_metadata"])
    identities = {
        hashlib.sha256(identifier.encode()).hexdigest(): hashlib.sha256(
            str(_object(row)["base_id"]).encode()
        ).hexdigest()
        for identifier, row in metadata.items()
    }

    def matched_model(request: Request) -> object:
        return model(replace(request, id=identities[request.id]))

    report = evaluate(cases, cast(Model, matched_model))
    report["robustness"] = _score_robustness(
        cases, cast(list[dict[str, object]], report["predictions"]), protocol
    )
    return report


def _interval(values: dict[str, list[float]], seed: int, *, signed: bool = False) -> object:
    if not values:
        return None
    means = [sum(group) / len(group) for _, group in sorted(values.items())]
    result = grouped_interval([(v + 1) / 2 for v in means] if signed else means, seed=seed)
    if signed:
        for key in ("estimate", "lower", "upper"):
            result[key] = 2 * cast(float, result[key]) - 1
    return result


def _correct(case: Case, record: dict[str, object]) -> bool:
    return record["error"] is None and canonical_json(record["answer"]) in {
        canonical_json(answer) for answer in case.expected
    }


def _valid(case: Case, record: dict[str, object]) -> bool:
    return (
        record["error"] is None
        and isinstance(record["answer"], str)
        and (record["answer"] in {c.id for c in case.request.choices})
    )


def score_robustness(
    cases: Sequence[Case],
    records: Sequence[dict[str, object]],
    protocol: dict[str, object],
) -> dict[str, object]:
    """Errors/missing predictions fail correctness; flips alone never earn credit."""
    validate_robustness(cases, protocol)
    return _score_robustness(cases, records, protocol)


def _score_robustness(
    cases: Sequence[Case], records: Sequence[dict[str, object]], protocol: dict[str, object]
) -> dict[str, object]:
    report = score_predictions(cases, records)
    saved = cast(list[dict[str, object]], report["predictions"])
    metadata = _object(protocol["case_metadata"])
    by_base: dict[str, list[tuple[Case, dict[str, object], dict[str, object]]]] = defaultdict(list)
    for case, record in zip(cases, saved, strict=True):
        meta = _object(metadata[case.request.id])
        by_base[str(meta["base_id"])].append((case, record, meta))
    # Panels keep native task, source, split and menu width separate.
    groups: dict[Panel, dict[str, dict[str, list[float]]]] = {}
    pair_counts: dict[Panel, dict[str, int]] = defaultdict(lambda: defaultdict(int))
    observations: dict[Panel, dict[str, int]] = defaultdict(lambda: defaultdict(int))
    positions: dict[Panel, dict[int, list[bool]]] = defaultdict(lambda: defaultdict(list))
    base_counts: dict[Panel, int] = defaultdict(int)
    wording_counts: dict[Panel, int] = defaultdict(int)
    for rows in by_base.values():
        case = rows[0][0]
        state, _, _ = native_request(case.request)
        context_width = (
            len(cast(list[object], state["actions"]))
            if (isinstance(state, dict) and isinstance(state.get("actions"), list))
            else 0
        )
        panel = (
            case.source,
            case.split,
            case.request.task,
            len(case.request.choices),
            context_width,
        )
        metrics = groups.setdefault(panel, {})
        base_counts[panel] += 1

        base_values: dict[str, list[float]] = defaultdict(list)

        def add(name: str, value: float, target: dict[str, list[float]] = base_values) -> None:
            target[name].append(value)

        baseline = {
            cast(int, m["repeat"]): (c, r)
            for c, r, m in rows
            if m["order"] == 0 and all(m[axis] == "original" for axis in AXES)
        }
        baseline_correct = [_correct(c, r) for c, r in baseline.values()]
        add("baseline_accuracy", sum(baseline_correct) / len(baseline_correct))
        add("mean_accuracy", sum(_correct(c, r) for c, r, _ in rows) / len(rows))
        add("all_conditions_correct", float(all(_correct(c, r) for c, r, _ in rows)))
        add(
            "all_orders_correct",
            float(
                all(
                    _correct(c, r)
                    for c, r, m in rows
                    if all(m[axis] == "original" for axis in AXES)
                )
            ),
        )
        if any(m[axis] != "original" for _, _, m in rows for axis in AXES):
            wording_counts[panel] += 1
            add(
                "all_wordings_correct",
                float(all(_correct(c, r) for c, r, m in rows if m["order"] == 0)),
            )
        conditions: dict[tuple[object, ...], list[bool]] = defaultdict(list)
        for c, r, m in rows:
            conditions[(m["order"], *(m[axis] for axis in AXES))].append(_correct(c, r))
        add("worst_condition_accuracy", min(sum(v) / len(v) for v in conditions.values()))
        first_c, first_r = baseline[0]
        for repeat, (c, r) in baseline.items():
            if repeat == 0:
                continue
            add(
                "unchanged/accuracy_delta",
                float(_correct(c, r)) - float(_correct(first_c, first_r)),
            )
            add("unchanged/valid_pair_coverage", float(_valid(c, r) and _valid(first_c, first_r)))
            if _valid(c, r) and _valid(first_c, first_r):
                add("unchanged/valid_answer_flip", float(r["answer"] != first_r["answer"]))
            add("unchanged/error_rate", float(r["error"] is not None))
        for c, r, m in rows:
            changed = (["order"] if m["order"] != 0 else []) + [
                axis for axis in AXES if m[axis] != "original"
            ]
            if not changed:
                continue
            axis = "+".join(changed)
            reference_c, reference_r = baseline[cast(int, m["repeat"])]
            left, right = _correct(reference_c, reference_r), _correct(c, r)
            pair_counts[panel][axis] += 1
            add(axis + "/accuracy", float(right))
            add(axis + "/accuracy_delta", float(right) - float(left))
            add(axis + "/both_correct", float(left and right))
            add(axis + "/harmful_change", float(left and not right))
            add(axis + "/recovery", float(not left and right))
            add(axis + "/error_rate", float(r["error"] is not None))
            add(
                axis + "/valid_pair_coverage",
                float(_valid(reference_c, reference_r) and _valid(c, r)),
            )
            if _valid(reference_c, reference_r) and _valid(c, r):
                add(axis + "/valid_answer_flip", float(reference_r["answer"] != r["answer"]))
            if left:
                add(axis + "/failure_given_baseline_correct", float(not right))
            has_probabilities = (
                reference_r["probabilities"] is not None and r["probabilities"] is not None
            )
            add(axis + "/probability_pair_coverage", float(has_probabilities))
            if has_probabilities:
                p = cast(dict[str, float], reference_r["probabilities"])
                q = cast(dict[str, float], r["probabilities"])
                add(axis + "/probability_total_variation", sum(abs(p[k] - q[k]) for k in p) / 2)
            if changed == ["order"]:
                for index, choice in enumerate(c.request.choices):
                    if choice.id in c.expected:
                        positions[panel][index].append(right)
        for name, values in base_values.items():
            metrics.setdefault(name, {}).setdefault(case.group, []).append(
                sum(values) / len(values)
            )
            observations[panel][name] += len(values)
    return {
        "version": VERSION,
        "panels": [
            {
                "source": source,
                "split": split,
                "task": task,
                "menu_width": width,
                "context_action_count": context_width or None,
                "base_cases": base_counts[panel],
                "base_cases_with_wording": wording_counts[panel],
                "complete_family_robustness": {
                    name: wilson_interval(
                        sum(all(values) for values in groups[panel][name].values()),
                        len(groups[panel][name]),
                    )
                    for name in (
                        "all_orders_correct",
                        "all_wordings_correct",
                        "all_conditions_correct",
                    )
                    if name in groups[panel]
                },
                "paired_counts": dict(pair_counts[panel]),
                "metrics": {
                    name: {
                        "interval": _interval(
                            values,
                            cast(int, protocol["seed"]),
                            signed=name.endswith("accuracy_delta"),
                        ),
                        "observations": observations[panel][name],
                    }
                    for name, values in sorted(groups[panel].items())
                },
                "gold_position_accuracy": {
                    str(position): {
                        "correct": sum(values),
                        "count": len(values),
                        "accuracy": sum(values) / len(values),
                    }
                    for position, values in sorted(positions[panel].items())
                },
            }
            for panel in sorted(groups)
            for source, split, task, width, context_width in (panel,)
        ],
        "coverage": protocol["coverage"],
        "limitations": [
            "Wording equivalence is a recorded review assertion, not a semantic proof",
            "Intervals resample original source families; variants/repeats are dependent",
            "Intervals are descriptive marginal 95% intervals, not simultaneous tests",
            "Worst/all-condition scores depend on the frozen perturbation budget",
            "Valid flips can be harmless ties; low flip rates can reflect constant wrong answers",
            "Unchanged repeats measure variability; order effects still assume a stateless model",
        ],
    }

"""A bounded, sequential local server for the same public callable contract."""

from __future__ import annotations

from http.server import BaseHTTPRequestHandler, HTTPServer

from .api import (
    Model,
    Prediction,
    canonical_json,
    normalize_prediction,
    prediction_to_dict,
    request_from_dict,
    strict_json_loads,
)
from .models import MAX_BODY_BYTES


def make_server(model: Model, host: str = "127.0.0.1", port: int = 8000) -> HTTPServer:
    """Return an unstarted serial server. Caller owns serve/shutdown/close.

    Local transport only: no authentication or process isolation is provided.
    A backend call cannot be preempted here; its owner controls execution limits.
    """
    if not callable(model):
        raise TypeError("model must be callable")
    if isinstance(port, bool) or not isinstance(port, int) or not 0 <= port <= 65535:
        raise ValueError("port must be an integer in 0..65535")

    class Handler(BaseHTTPRequestHandler):
        def setup(self) -> None:
            self.request.settimeout(10.0)
            super().setup()

        def log_message(self, format: str, *args: object) -> None:
            # The caller owns request logging; do not print model inputs.
            pass

        def send_json(self, status: int, value: object) -> None:
            body = canonical_json(value).encode("utf-8")
            if len(body) > MAX_BODY_BYTES:
                status = 500
                body = b'{"error":"response exceeds byte limit"}'
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Connection", "close")
            self.end_headers()
            self.close_connection = True
            try:
                self.wfile.write(body)
            except (TimeoutError, BrokenPipeError, ConnectionResetError):
                pass

        def do_GET(self) -> None:
            if self.path == "/health":
                self.send_json(200, {"status": "ok"})
            else:
                self.send_json(404, {"error": "unknown endpoint"})

        def do_POST(self) -> None:
            if self.path != "/decide":
                self.send_json(404, {"error": "unknown endpoint"})
                return
            if self.headers.get_content_type() != "application/json":
                self.send_json(415, {"error": "Content-Type must be application/json"})
                return
            lengths = self.headers.get_all("Content-Length", [])
            if self.headers.get("Transfer-Encoding") is not None or len(lengths) != 1:
                self.send_json(400, {"error": "one Content-Length required; no transfer encoding"})
                return
            length_text = lengths[0]
            if len(length_text) > 12 or not length_text.isascii() or not length_text.isdigit():
                self.send_json(400, {"error": "invalid Content-Length"})
                return
            length = int(length_text)
            if length > MAX_BODY_BYTES:
                self.send_json(413, {"error": "request exceeds byte limit"})
                return
            try:
                raw = self.rfile.read(length)
                if len(raw) != length:
                    raise ValueError("incomplete request body")
                request = request_from_dict(strict_json_loads(raw.decode("utf-8")))
            except (OSError, ValueError, TypeError, RecursionError) as exc:
                self.send_json(400, {"error": f"invalid request: {type(exc).__name__}: {exc}"})
                return
            try:
                result = normalize_prediction(model(request), request)
            except Exception as exc:
                result = Prediction(answer=None, error=f"model: {type(exc).__name__}: {exc}")
            self.send_json(200, prediction_to_dict(result))

    return HTTPServer((host, port), Handler)

"""Deterministic routing imports with original annotations and official splits."""

from __future__ import annotations

import csv
import hashlib
import re
import unicodedata
from collections import Counter, defaultdict
from pathlib import Path
from typing import cast

from dmbench.api import Case, Choice, JSONValue, Request, canonical_json, strict_json_loads
from dmbench.imports import ImportResult


def context_group(text: str) -> str:
    """Group exact NFKC/casefold/whitespace equivalents; never alter model text."""
    normalized = " ".join(unicodedata.normalize("NFKC", text).casefold().split())
    return "text:" + hashlib.sha256(normalized.encode()).hexdigest()


def _revision(revision: str) -> None:
    if re.fullmatch(r"[0-9a-f]{40}", revision) is None:
        raise ValueError("A full lowercase upstream commit revision is required")


def _csv(path: Path, fields: list[str], *, hint_notes: bool = False) -> list[tuple[str, str]]:
    with path.open(encoding="utf-8", newline="") as stream:
        reader = csv.DictReader(stream)
        expected = fields + [""] if hint_notes and reader.fieldnames == fields + [""] else fields
        if reader.fieldnames != expected:
            raise ValueError("Unexpected routing CSV header")
        rows = list(reader)
    result = []
    for row in rows:
        if (
            set(row) != set(expected)
            or ("" in row and type(row[""]) is not str)
            or any(type(row[key]) is not str or not row[key].strip() for key in fields)
        ):
            raise ValueError("Routing rows require nonempty text and label")
        result.append((cast(str, row[fields[0]]), cast(str, row[fields[1]])))
    return result


def _pairs(value: JSONValue) -> list[tuple[str, str]]:
    if type(value) is not list:
        raise ValueError("Routing split requires a list")
    result = []
    for row in value:
        if (
            type(row) is not list
            or len(row) != 2
            or any(type(item) is not str or not item.strip() for item in row)
        ):
            raise ValueError("CLINC records require [utterance, native label]")
        result.append((cast(str, row[0]), cast(str, row[1])))
    return result


def _cases(
    source: str,
    prefix: str,
    splits: dict[str, list[tuple[str, str]]],
    labels: tuple[str, ...],
    *,
    oos: str | None = None,
    original_ids: dict[str, list[str]] | None = None,
    oos_description: str = "Outside all supplied supported intents",
    scope_policy: str | None = None,
) -> tuple[Case, ...]:
    if not labels or len(set(labels)) != len(labels) or any(not label.strip() for label in labels):
        raise ValueError("Routing menu must contain unique nonempty labels")
    criteria: dict[str, JSONValue] = {
        label: (oos_description if label == oos else label.replace("_", " ")) for label in labels
    }
    choices = tuple(Choice(label, cast(str, criteria[label])) for label in labels)
    question: dict[str, JSONValue] = {
        "type": "choice",
        "instructions": "Select the intent best supported by the supplied utterance and menu.",
        "criteria": criteria,
    }
    if oos is not None:
        question["instructions"] = (
            "Route the utterance to a supplied supported intent; select "
            + oos
            + " when the supplied out-of-scope criterion applies."
        )
    if scope_policy:
        question["instructions"] = str(question["instructions"]) + " " + scope_policy
    result = []
    for split, rows in splits.items():
        for index, (text, label) in enumerate(rows):
            if label not in labels:
                raise ValueError("Annotated label absent from training-defined menu")
            identifier = (
                f"{prefix}/{split}/{index:06d}"
                if original_ids is None
                else original_ids[split][index]
            )
            public = canonical_json({"state": text, "question": question, "labels": list(labels)})
            result.append(
                Case(
                    Request(identifier, "jevbench/choice", public, choices),
                    (label,),
                    context_group(text),
                    source,
                    split,
                )
            )
    return tuple(result)


def _result(
    root: Path,
    revision: str,
    source: str,
    repository: str,
    license_id: str,
    files: list[str],
    cases: tuple[Case, ...],
    *,
    oos: str | None = None,
) -> ImportResult:
    _revision(revision)
    groups: dict[str, list[Case]] = defaultdict(list)
    counts: Counter[str] = Counter()
    label_counts: dict[str, Counter[str]] = defaultdict(Counter)
    for case in cases:
        groups[case.group].append(case)
        counts[case.split] += 1
        label_counts[case.split][cast(str, case.expected[0])] += 1
    audit = {
        "original_split_counts": dict(counts),
        "label_counts": {split: dict(values) for split, values in label_counts.items()},
        "oos_label": oos,
        "oos_counts": {
            split: values.get(oos, 0) if oos else 0 for split, values in label_counts.items()
        },
        "duplicate_groups": [
            {
                "group": group,
                "ids": [case.request.id for case in values],
                "splits": sorted({case.split for case in values}),
                "labels": sorted({cast(str, case.expected[0]) for case in values}),
            }
            for group, values in sorted(groups.items())
            if len(values) > 1
        ],
        "cross_split_groups": sum(
            len({case.split for case in values}) > 1 for values in groups.values()
        ),
        "conflicting_label_groups": sum(
            len({case.expected for case in values}) > 1 for values in groups.values()
        ),
        "estimated_serialized_case_bytes": sum(
            len(
                canonical_json(
                    {
                        "request": {
                            "id": case.request.id,
                            "task": case.request.task,
                            "text": case.request.text,
                            "choices": [{"id": x.id, "text": x.text} for x in case.request.choices],
                        },
                        "expected": list(case.expected),
                        "source": case.source,
                        "group": case.group,
                        "split": case.split,
                    }
                ).encode()
            )
            + 1
            for case in cases
        ),
    }
    provenance: dict[str, object] = {
        "source": source,
        "repository": repository,
        "revision": revision,
        "license": license_id,
        "recipe": "routing-native-choice-v1",
        "menu_description_recipe": (
            "native-label-underscore-to-space; annotated-OOS-outside-supported-intents"
        ),
        "group_recipe": "sha256(NFKC-casefold-whitespace-collapse-original-utterance)",
        "official_splits_preserved": True,
        "file_sha256": {
            name: hashlib.sha256((root / name).read_bytes()).hexdigest() for name in files
        },
        "audit": audit,
    }
    # Do not validate_cases here: official cross-split duplicate groups are evidence
    # for composition quarantine, not permission to silently change source splits.
    return ImportResult(cases, provenance, ())


def import_banking77(directory: str | Path, revision: str) -> ImportResult:
    """Original PolyAI CSVs/categories; BANKING77 has no annotated OOS class."""
    _revision(revision)
    root = Path(directory)
    labels_raw = strict_json_loads((root / "banking_data/categories.json").read_text())
    if (
        type(labels_raw) is not list
        or len(labels_raw) != 77
        or any(type(label) is not str for label in labels_raw)
    ):
        raise ValueError("BANKING77 requires its 77 native category names")
    labels = tuple(cast(list[str], labels_raw))
    splits = {
        split: _csv(root / f"banking_data/{split}.csv", ["text", "category"])
        for split in ("train", "test")
    }
    cases = _cases("PolyAI/BANKING77", "banking77", splits, labels)
    return _result(
        root,
        revision,
        "PolyAI/BANKING77",
        "https://github.com/PolyAI-LDN/task-specific-datasets",
        "CC-BY-4.0",
        [
            "LICENSE",
            "banking_data/categories.json",
            "banking_data/train.csv",
            "banking_data/test.csv",
        ],
        cases,
    )


def import_clinc150(directory: str | Path, revision: str) -> ImportResult:
    """CLINC full splits, including only source-annotated `oos` observations."""
    _revision(revision)
    root = Path(directory)
    data = strict_json_loads((root / "data/data_full.json").read_text())
    if type(data) is not dict or set(data) != {
        "train",
        "val",
        "test",
        "oos_train",
        "oos_val",
        "oos_test",
    }:
        raise ValueError("CLINC full requires all six native split arrays")
    rows = {split: _pairs(value) for split, value in data.items()}
    labels = tuple(sorted({label for _, label in rows["train"]}))
    if len(labels) != 150 or "oos" in labels:
        raise ValueError("CLINC full requires 150 training-defined in-scope labels")
    splits = {}
    original_ids = {}
    for split in ("train", "val", "test"):
        if any(label == "oos" for _, label in rows[split]) or any(
            label != "oos" for _, label in rows["oos_" + split]
        ):
            raise ValueError("CLINC in-scope/OOS annotations disagree with native arrays")
        splits[split] = rows[split] + rows["oos_" + split]
        original_ids[split] = [
            f"clinc150/{native}/{index:06d}"
            for native in (split, "oos_" + split)
            for index in range(len(rows[native]))
        ]
    cases = _cases(
        "CLINC/CLINC150-full",
        "clinc150",
        splits,
        labels + ("oos",),
        oos="oos",
        original_ids=original_ids,
    )
    return _result(
        root,
        revision,
        "CLINC/CLINC150-full",
        "https://github.com/clinc/oos-eval",
        "CC-BY-3.0",
        ["LICENSE", "data/data_full.json"],
        cases,
        oos="oos",
    )


def import_hint3(directory: str | Path, revision: str, domain: str) -> ImportResult:
    """Corrected v2 natural queries; retain native NO_NODES_DETECTED annotation."""
    _revision(revision)
    if domain not in {"curekart", "powerplay11", "sofmattress"}:
        raise ValueError("Unknown HINT3 domain")
    root = Path(directory)
    paths = [f"dataset/v2/{split}/{domain}_{split}.csv" for split in ("train", "test")]
    splits = {
        split: _csv(root / path, ["sentence", "label"], hint_notes=True)
        for split, path in zip(("train", "test"), paths, strict=True)
    }
    oos = "NO_NODES_DETECTED"
    labels = tuple(sorted({label for _, label in splits["train"] if label != oos})) + (oos,)
    cases = _cases(
        "Haptik/HINT3-v2/" + domain,
        "hint3/" + domain,
        splits,
        labels,
        oos=oos,
        oos_description=(
            "Outside supported intents or non-Latin/code-mixed language under HINT3 scope"
        ),
        scope_policy=(
            "The source supports English queries: non-Latin-script or code-mixed "
            "queries are out of scope even when their topic is relevant."
        ),
    )
    result = _result(
        root,
        revision,
        "Haptik/HINT3-v2/" + domain,
        "https://github.com/hellohaptik/HINT3",
        "ODbL-1.0 AND DbCL-1.0",
        ["LICENSE.md", *paths],
        cases,
        oos=oos,
    )

    notes = []
    for path in paths:
        with (root / path).open(encoding="utf-8", newline="") as stream:
            for index, row in enumerate(csv.DictReader(stream)):
                if row.get(""):
                    notes.append({"path": path, "row_index": index, "annotation_note": row[""]})
    result.provenance["scope_policy"] = (
        "HINT3 paper section3.2: non-Latin/script or code-mixed queries annotated out of scope"
    )
    result.provenance["annotation_notes_excluded_from_inference"] = notes
    return result

"""Pinned public source bytes: validate before composition, fetch without execution."""

from __future__ import annotations

import hashlib
import os
import re
from dataclasses import dataclass, replace
from email.message import Message
from pathlib import Path, PurePosixPath
from tempfile import NamedTemporaryFile
from typing import IO, Protocol, cast
from urllib.parse import urlsplit
from urllib.request import HTTPRedirectHandler, Request, build_opener
from zipfile import ZipFile

from dmbench.api import strict_json_loads


@dataclass(frozen=True)
class SourceFile:
    path: str
    url: str
    sha256: str
    size: int
    revision: str


class _Response(Protocol):
    def read(self, size: int) -> bytes: ...
    def geturl(self) -> str: ...
    def __enter__(self) -> _Response: ...
    def __exit__(self, kind: object, value: object, traceback: object) -> None: ...


class _NoRedirect(HTTPRedirectHandler):
    def redirect_request(
        self, req: Request, fp: IO[bytes], code: int, msg: str, headers: Message, newurl: str
    ) -> None:
        raise ValueError("Pinned source fetch refuses redirects")


def _validate(file: SourceFile) -> None:
    path = PurePosixPath(file.path)
    if (
        not file.path
        or not path.parts
        or path.is_absolute()
        or ".." in path.parts
        or "\\" in file.path
        or path.as_posix() != file.path
    ):
        raise ValueError("Source path must be a normalized relative POSIX path")
    if not re.fullmatch(r"[0-9a-f]{40}", file.revision) or not re.fullmatch(
        r"[0-9a-f]{64}", file.sha256
    ):
        raise ValueError("Source revision/hash must be full lowercase hex")
    if type(file.size) is not int or not 0 <= file.size <= 75000000:
        raise ValueError("Source byte count exceeds the bounded public download contract")
    url = urlsplit(file.url)
    parts = url.path.split("/")
    if (
        url.scheme != "https"
        or url.netloc != "raw.githubusercontent.com"
        or url.query
        or url.fragment
        or len(parts) < 5
        or parts[3] != file.revision
        or not parts[1]
        or not parts[2]
    ):
        raise ValueError("Source URL must be HTTPS primary raw GitHub pinned to its revision")


def load_snapshot(registry: str | Path) -> tuple[SourceFile, ...]:
    raw = strict_json_loads(Path(registry).read_text(encoding="utf-8"))
    if (
        not isinstance(raw, dict)
        or set(raw) != {"schema_version", "files"}
        or type(raw["schema_version"]) is not int
        or raw["schema_version"] != 1
    ):
        raise ValueError("Unsupported source registry schema")
    rows = raw["files"]
    if not isinstance(rows, list) or not rows:
        raise ValueError("Source registry must contain files")
    files = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"path", "url", "sha256", "bytes", "revision"}:
            raise ValueError("Invalid source registry fields")
        if (
            any(type(row[key]) is not str for key in ("path", "url", "sha256", "revision"))
            or type(row["bytes"]) is not int
        ):
            raise ValueError("Invalid source registry value types")
        file = SourceFile(
            cast(str, row["path"]),
            cast(str, row["url"]),
            cast(str, row["sha256"]),
            row["bytes"],
            cast(str, row["revision"]),
        )
        _validate(file)
        if file.path in seen:
            raise ValueError("Duplicate source registry path")
        seen.add(file.path)
        files.append(file)
    logic = [f for f in files if "/LogicBench/data/LogicBench(Eval)/" in f.path]
    if logic:
        patterns = {
            task: {
                f.path.split(f"LogicBench(Eval)/{task}/", 1)[1]
                for f in logic
                if f"LogicBench(Eval)/{task}/" in f.path
            }
            for task in ("BQA", "MCQA")
        }
        if len(logic) != 50 or len(patterns["BQA"]) != 25 or patterns["BQA"] != patterns["MCQA"]:
            raise ValueError(
                "Registry must bind all 50 LogicBench Eval files across matching 25 patterns"
            )
    return tuple(files)


def revision_for_source(files: tuple[SourceFile, ...], prefix: str) -> str:
    selected = [file for file in files if file.path.startswith(prefix.rstrip("/") + "/")]
    revisions = {file.revision for file in selected}
    if not selected or len(revisions) != 1:
        raise ValueError("Source prefix must select one consistent pinned revision")
    return revisions.pop()


def _target(file: SourceFile, root: Path) -> Path:
    _validate(file)
    path = root / file.path
    if not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Source path escapes root through a symlink")
    return path


def _verify_bytes(file: SourceFile, data: bytes) -> None:
    if len(data) != file.size or hashlib.sha256(data).hexdigest() != file.sha256:
        raise ValueError(f"Pinned source byte/hash mismatch: {file.path}")


def verify_snapshot(files: tuple[SourceFile, ...], root: str | Path) -> None:
    for file in files:
        target = _target(file, Path(root))
        with target.open("rb") as stream:
            _verify_bytes(file, stream.read(file.size + 1))


def fetch_snapshot(files: tuple[SourceFile, ...], root: str | Path) -> None:
    """Fetch missing registry files only; never overwrite incorrect existing data."""
    directory = Path(root)
    opener = build_opener(_NoRedirect())
    for file in files:
        target = _target(file, directory)
        if target.exists():
            verify_snapshot((file,), directory)
            continue
        with cast(_Response, opener.open(file.url, timeout=30)) as response:
            if response.geturl() != file.url:
                raise ValueError("Pinned source URL changed")
            data = response.read(file.size + 1)
        _verify_bytes(file, data)
        _publish_bytes(file, directory, data)
    verify_snapshot(files, directory)


def _publish_bytes(file: SourceFile, root: Path, data: bytes) -> None:
    """Publish verified bytes exclusively; an existing different file is an error."""
    _verify_bytes(file, data)
    target = _target(file, root)
    if target.exists():
        verify_snapshot((file,), root)
        return
    target.parent.mkdir(parents=True, exist_ok=True)
    _target(file, root)
    temporary: Path | None = None
    try:
        with NamedTemporaryFile(
            dir=target.parent, prefix=".dmbench-source-", delete=False
        ) as stream:
            temporary = Path(stream.name)
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.link(temporary, target)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def materialize_contractnli(files: tuple[SourceFile, ...], root: str | Path) -> None:
    """Read only six whitelisted data/terms members from the verified release ZIP.

    Raw PDFs, executable files and arbitrary archive paths are never extracted.
    Existing derived files must match the exact pinned archive member bytes.
    """
    selected = [
        file
        for file in files
        if PurePosixPath(file.path).parts[-2:] == ("resources", "contract-nli.zip")
    ]
    if len(selected) != 1:
        raise ValueError("One pinned official ContractNLI archive is required")
    archive = selected[0]
    directory = Path(root)
    verify_snapshot((archive,), directory)
    parent = PurePosixPath(archive.path).parent.parent
    members = {name: name for name in ("train.json", "dev.json", "test.json", "TERMS")}
    members.update({"README.md": "archive-README.md", "LICENSE": "archive-LICENSE"})
    prepared: list[tuple[SourceFile, bytes]] = []
    with ZipFile(_target(archive, directory)) as bundle:
        names = bundle.namelist()
        for source_name, target_name in members.items():
            member = "contract-nli/" + source_name
            if names.count(member) != 1:
                raise ValueError("Missing or duplicate required ContractNLI ZIP member")
            info = bundle.getinfo(member)
            if info.is_dir() or info.flag_bits & 1 or not 0 <= info.file_size <= 75000000:
                raise ValueError("Unsupported or oversized ContractNLI ZIP member")
            with bundle.open(info) as stream:
                data = stream.read(info.file_size + 1)
            if len(data) != info.file_size:
                raise ValueError("ContractNLI archive member byte count differs")
            derived = replace(
                archive,
                path=(parent / target_name).as_posix(),
                sha256=hashlib.sha256(data).hexdigest(),
                size=len(data),
            )
            target = _target(derived, directory)
            if target.exists():
                verify_snapshot((derived,), directory)
            prepared.append((derived, data))
    for file, data in prepared:
        _publish_bytes(file, directory, data)

"""Group-weighted uncertainty; a large corpus cannot dominate a small ability."""

from __future__ import annotations

import math
import random
from collections import defaultdict
from collections.abc import Sequence

from .api import Case


def grouped_interval(
    values: Sequence[float], *, seed: int = 17, repetitions: int = 2000
) -> dict[str, object]:
    """Percentile bootstrap of independent groups, not correlated question rows."""
    if not values or repetitions < 100 or any(not 0 <= value <= 1 for value in values):
        raise ValueError("bounded observations and at least100 bootstrap repetitions required")
    rng = random.Random(seed)
    count = len(values)
    samples = sorted(
        sum(values[rng.randrange(count)] for _ in values) / count for _ in range(repetitions)
    )
    return {
        "estimate": sum(values) / count,
        "lower": samples[int(0.025 * repetitions)],
        "upper": samples[min(repetitions - 1, int(0.975 * repetitions))],
        "groups": count,
        "seed": seed,
        "repetitions": repetitions,
        "method": "group percentile bootstrap 95%; conditional on observed corpus",
    }


def wilson_interval(correct: int, count: int) -> dict[str, object]:
    """Boundary-aware interval; explicit independent Bernoulli-group assumption."""
    if type(correct) is not int or type(count) is not int or count < 1 or not 0 <= correct <= count:
        raise ValueError("Integer group counts required")
    z = 1.959963984540054
    estimate = correct / count
    denominator = 1 + z * z / count
    center = (estimate + z * z / (2 * count)) / denominator
    radius = (
        z * math.sqrt(estimate * (1 - estimate) / count + z * z / (4 * count * count)) / denominator
    )
    return {
        "estimate": estimate,
        "lower": max(0.0, center - radius),
        "upper": min(1.0, center + radius),
        "groups": count,
        "method": (
            "Wilson score 95%; assumes independent sampled groups; "
            "no guarantee beyond this generator/corpus"
        ),
    }


def panels(
    cases: Sequence[Case], correct: Sequence[bool], *, seed: int = 17
) -> list[dict[str, object]]:
    """Separate source/split panels. Missing/unsupported predictions are False."""
    if len(cases) != len(correct) or any(type(value) is not bool for value in correct):
        raise ValueError("one boolean outcome required for every case")
    groups: dict[tuple[str, str], dict[str, list[bool]]] = defaultdict(lambda: defaultdict(list))
    for case, outcome in zip(cases, correct, strict=True):
        groups[case.source, case.split][case.group].append(outcome)
    return [
        {
            "source": source,
            "split": split,
            "count": sum(len(x) for x in families.values()),
            "group_mean_accuracy": grouped_interval(
                [sum(x) / len(x) for x in families.values()], seed=seed
            ),
            "complete_group_accuracy": wilson_interval(
                sum(all(x) for x in families.values()), len(families)
            ),
        }
        for (source, split), families in sorted(groups.items())
    ]

"""Verified multi-source evaluation with a scoreboard, not a pooled headline."""

from __future__ import annotations

import hashlib
from collections.abc import Iterator
from pathlib import Path
from typing import cast

from .api import Case, JSONValue, Model, canonical_json, strict_json_loads
from .evaluation import evaluate
from .io import load_benchmark, validate_cases
from .relationship import score_relationship
from .robustness import evaluate_robustness, validate_robustness
from .statistics import panels


def read_suite_index(directory: str | Path) -> dict[str, object]:
    """Validate index identity only; cohort bytes are admitted by iter_suite."""
    root = Path(directory)
    value = strict_json_loads((root / "release.json").read_text())
    if (
        not isinstance(value, dict)
        or type(value.get("schema_version")) is not int
        or value.get("schema_version") != 1
    ):
        raise ValueError("Unsupported release index")
    identity = {key: item for key, item in value.items() if key != "release_id"}
    if value.get("release_id") != hashlib.sha256(canonical_json(identity).encode()).hexdigest():
        raise ValueError("Release index identity mismatch")
    entries = value.get("cohorts")
    if not isinstance(entries, dict) or not entries:
        raise ValueError("Release must name scored cohorts")
    return cast(dict[str, object], value)


def _cohorts(
    root: Path, index: dict[str, object]
) -> Iterator[tuple[str, tuple[Case, ...], dict[str, object]]]:
    entries = cast(dict[str, dict[str, object]], index["cohorts"])
    bindings: set[str] = set()
    request_ids: set[str] = set()
    group_splits: dict[tuple[str, str], str] = {}
    for name, raw in entries.items():
        if not isinstance(raw, dict) or not isinstance(raw.get("directory"), str):
            raise ValueError("Invalid cohort reference")
        relative = Path(cast(str, raw["directory"]))
        if relative.is_absolute() or ".." in relative.parts or not relative.parts:
            raise ValueError("Cohort path must remain inside release")
        target = root / relative
        if not target.resolve().is_relative_to(root.resolve()):
            raise ValueError("Cohort resolves outside release")
        manifest, cases = load_benchmark(target)
        if (
            type(raw.get("count")) is not int
            or manifest["release_id"] != raw.get("release_id")
            or len(cases) != raw.get("count")
        ):
            raise ValueError("Cohort binding mismatch")
        binding = cast(str, manifest["release_id"])
        if binding in bindings:
            raise ValueError("Duplicate cohort identity in suite")
        bindings.add(binding)
        for case in cases:
            if case.request.id in request_ids:
                raise ValueError("Duplicate request ID across suite cohorts")
            request_ids.add(case.request.id)
            group = case.source, case.group
            if group_splits.setdefault(group, case.split) != case.split:
                raise ValueError("Source family crosses suite splits")
        metadata = raw.get("relationship_metadata")
        if metadata is not None:
            if not isinstance(metadata, dict):
                raise ValueError("Invalid relationship metadata")
            score_relationship(cases, [], cast(dict[str, object], metadata))
        provenance = cast(dict[str, object], manifest["provenance"])
        protocol = provenance.get("robustness")
        if protocol != raw.get("robustness_protocol"):
            raise ValueError("Robustness protocol binding mismatch")
        if protocol is not None:
            validate_robustness(cases, cast(dict[str, object], protocol))
        yield name, cases, raw


def iter_suite(directory: str | Path) -> Iterator[tuple[str, tuple[Case, ...], dict[str, object]]]:
    """Inspect one admitted cohort at a time; exhaust before any model invocation."""
    root = Path(directory)
    yield from _cohorts(root, read_suite_index(root))


def load_suite(
    directory: str | Path, *, selected: tuple[str, ...] | None = None
) -> tuple[dict[str, object], dict[str, tuple[Case, ...]]]:
    index = read_suite_index(directory)
    entries = cast(dict[str, object], index["cohorts"])
    if selected is not None and (
        not selected or len(set(selected)) != len(selected) or set(selected) - set(entries)
    ):
        raise ValueError("Select distinct named release cohorts")
    cohorts = {
        name: cases
        for name, cases, _ in _cohorts(Path(directory), index)
        if selected is None or name in selected
    }
    return index, cohorts


def evaluate_suite(
    cohorts: dict[str, tuple[Case, ...]],
    model: Model,
    *,
    seed: int = 17,
    relationship_metadata: dict[str, dict[str, object]] | None = None,
    robustness_protocols: dict[str, dict[str, object]] | None = None,
) -> dict[str, object]:
    """Caller loads the verified suite before loading model code; caller owns it."""
    admitted = {
        name: validate_cases(
            Case(case.request, case.expected, case.group, case.source, case.split) for case in cases
        )
        for name, cases in cohorts.items()
    }
    validate_cases(case for cases in admitted.values() for case in cases)
    metadata = relationship_metadata or {}
    if set(metadata) - set(admitted):
        raise ValueError("Unknown relationship cohort")
    for name, declared in metadata.items():
        score_relationship(admitted[name], [], declared)  # full preflight, before inference
    protocols = robustness_protocols or {}
    if set(protocols) - set(admitted):
        raise ValueError("Unknown robustness cohort")
    for name, protocol in protocols.items():
        validate_robustness(admitted[name], protocol)

    reports: dict[str, object] = {}
    for name, cases in admitted.items():
        report = (
            evaluate_robustness(cases, model, protocols[name])
            if name in protocols
            else evaluate(cases, model)
        )
        records = cast(list[dict[str, JSONValue]], report["predictions"])
        outcomes = [
            record["error"] is None
            and canonical_json(record["answer"])
            in {canonical_json(answer) for answer in case.expected}
            for case, record in zip(cases, records, strict=True)
        ]
        report["group_uncertainty"] = panels(cases, outcomes, seed=seed)
        if name in metadata:
            report["relationship"] = score_relationship(
                cases, cast(list[dict[str, object]], records), metadata[name]
            )
        reports[name] = report
    return {
        "schema_version": 1,
        "cohorts": reports,
        "scoring_policy": (
            "Separate source/split panels. No pooled headline. "
            "Missing and unsupported outcomes remain failures."
        ),
        "uncertainty_seed": seed,
    }


def suite_relationship_metadata(
    index: dict[str, object], names: tuple[str, ...] | None = None
) -> dict[str, dict[str, object]]:
    entries = index.get("cohorts")
    if not isinstance(entries, dict):
        raise ValueError("Invalid cohort registry")
    result = {}
    for name, entry in entries.items():
        if names is not None and name not in names:
            continue
        if not isinstance(name, str) or not isinstance(entry, dict):
            raise ValueError("Invalid cohort entry")
        metadata = entry.get("relationship_metadata")
        if metadata is not None:
            if not isinstance(metadata, dict) or not all(isinstance(key, str) for key in metadata):
                raise ValueError("Invalid relationship metadata")
            result[name] = cast(dict[str, object], metadata)
    return result


def suite_robustness_protocols(
    index: dict[str, object], names: tuple[str, ...] | None = None
) -> dict[str, dict[str, object]]:
    entries = index.get("cohorts")
    if not isinstance(entries, dict):
        raise ValueError("Invalid cohort registry")
    result = {}
    for name, entry in entries.items():
        if names is not None and name not in names:
            continue
        if not isinstance(name, str) or not isinstance(entry, dict):
            raise ValueError("Invalid cohort entry")
        protocol = entry.get("robustness_protocol")
        if protocol is not None:
            if not isinstance(protocol, dict):
                raise ValueError("Invalid robustness protocol")
            result[name] = cast(dict[str, object], protocol)
    return result

"""Deterministic authored families with declared balance and intervention edits."""

from __future__ import annotations

import hashlib
import json
import random
from collections import Counter
from dataclasses import dataclass, replace
from itertools import combinations

from ..api import Case, JSONValue, canonical_json, strict_json_loads
from .probes import Probe, sample_probe
from .requirements import Action, Expression, Status, World, distance, optimal, request, status
from .teachers import reference

VERSION = "authored-requirements-v1"
WIDTHS = (4, 8, 16, 32, 64, 128, 254, 256)
SPLITS = ("train", "dev", "test")
STATUSES: tuple[Status, ...] = ("met", "violated", "unknown")
RESEARCH_FAMILIES_PER_STATUS = 40
DEVELOPMENT_FAMILIES_PER_STATUS = 6


@dataclass(frozen=True)
class Family:
    identifier: str
    split: str
    width: int
    worlds: tuple[tuple[str, World], ...]
    shape_hash: str
    probe_receipt: Probe


def _rename(world: World, prefix: str) -> World:
    names = {world.goal, *(name for name, _ in world.facts)}

    def collect(expression: Expression) -> None:
        if expression.operator == "atom":
            names.add(expression.atom)
        for child in expression.children:
            collect(child)

    for action in world.actions:
        collect(action.requires)
        names.update(name for name, _ in action.effects)
    atoms = {name: prefix + f"p{index}" for index, name in enumerate(sorted(names))}
    actions = {
        action.identifier: prefix + f"a{index}" for index, action in enumerate(world.actions)
    }

    def rename(expression: Expression) -> Expression:
        if expression.operator == "atom":
            return Expression("atom", atoms[expression.atom])
        return Expression(
            expression.operator, children=tuple(rename(x) for x in expression.children)
        )

    return World(
        atoms[world.goal],
        tuple((atoms[name], v) for name, v in world.facts),
        tuple(
            Action(
                actions[a.identifier],
                rename(a.requires),
                tuple((atoms[name], v) for name, v in a.effects),
            )
            for a in world.actions
        ),
        actions[world.probe],
    )


def _family(seed: int, split: str, width: int, target: Status, index: int) -> Family:
    identifier = f"{VERSION}/{seed}/{split}/{width}/{target}/{index}"
    digest = hashlib.sha256(identifier.encode()).hexdigest()
    rng = random.Random(int(digest, 16))
    facts = {**{f"t{i}": True for i in range(8)}, **{f"f{i}": False for i in range(8)}}
    sampled = sample_probe(rng, target, split)
    facts.update(sampled.facts)
    depth = sampled.depth
    base, edited = sampled.original, sampled.operator_edit
    probe = Action("probe", base, (("goal", True),))
    horizon = 2 if width == 4 else 2 + index % 5
    resource_count = min(8, 13 - horizon)
    resources = tuple(f"resource{i}" for i in range(resource_count))
    facts.update((name, False) for name in resources)
    r = tuple(Expression("atom", name) for name in resources)
    if split == "train":
        eligible = Expression("AND", children=(r[0], r[1]))
    elif split == "dev":
        eligible = Expression("AND", children=(r[0], Expression("OR", children=(r[1], r[2]))))
    else:
        eligible = Expression(
            "OR",
            children=(
                Expression("AND", children=(r[0], Expression("OR", children=(r[1], r[2])))),
                Expression("AND", children=(r[3], r[4])),
            ),
        )
    blocked_target = STATUSES[(seed + width + SPLITS.index(split)) % len(STATUSES)]
    facts["route"] = not (index % 6 == 1 and target == blocked_target)
    facts["goal"] = index % 6 == 5
    actions = [
        probe,
        Action(
            "prepare_resources",
            Expression("atom", "route"),
            tuple((name, True) for name in resources),
        ),
    ]
    chain_count = horizon - 1
    for step in range(chain_count):
        previous = Expression("atom", "route" if step == 0 else f"stage{step - 1}")
        requirement = Expression("AND", children=(previous, eligible))
        chain_effect = (("goal" if step == chain_count - 1 else f"stage{step}", True),)
        if step < chain_count - 1:
            facts[f"stage{step}"] = False
        actions.append(Action(f"advance{step}", requirement, chain_effect))
    if index % 3 == 2 and len(actions) < width:
        actions.append(
            Action(
                "alternative_resources",
                Expression("OR", children=(Expression("atom", "route"), Expression("atom", "u7"))),
                tuple((name, True) for name in resources),
            )
        )
    pool = [f"t{i}" for i in range(8)] + [f"f{i}" for i in range(8)] + [f"u{i}" for i in range(8)]
    candidates = list(combinations(pool, 2))
    rng.shuffle(candidates)
    signatures = set()
    cursor = 0
    while len(actions) < width:
        a, b = candidates[cursor % len(candidates)]
        requirement = Expression(
            "AND" if cursor % 2 else "OR", children=(Expression("atom", a), Expression("atom", b))
        )
        if cursor % 3 != 2:
            requirement = Expression(
                "AND" if cursor % 3 == 0 else "OR",
                children=(requirement, r[cursor % resource_count]),
            )
        effect = tuple((name, bool(cursor & (1 << bit))) for bit, name in enumerate(resources))
        if cursor % 7 == 0:
            requirement = Expression("AND", children=(requirement, Expression("atom", "f7")))
            effect = (("goal", True),)
        signature = (requirement, effect)
        cursor += 1
        if signature in signatures:
            continue
        signatures.add(signature)
        actions.append(Action(f"candidate{cursor}", requirement, effect))
    rng.shuffle(actions)
    original = World("goal", tuple(sorted(facts.items())), tuple(actions), "probe")
    fact_facts = dict(facts)
    probe_atoms = {f"observation{i}" for i in range(sampled.atom_count)}
    fact_facts = {name: result for name, result in facts.items() if name not in probe_atoms}
    fact_facts.update(sampled.fact_edit)
    fact_edit = replace(original, facts=tuple(sorted(fact_facts.items())))
    operator_edit = replace(
        original,
        actions=tuple(
            replace(action, requires=edited) if action.identifier == "probe" else action
            for action in actions
        ),
    )
    shape = {
        "depth": depth,
        "actions": sorted(
            canonical_json({"requires": _expression_record(a.requires), "effects": dict(a.effects)})
            for a in actions
        ),
    }
    worlds = tuple(
        (kind, _rename(world, "x" + digest[:12] + "_"))
        for kind, world in (
            ("original", original),
            ("fact", fact_edit),
            ("operator", operator_edit),
        )
    )
    return Family(
        identifier,
        split,
        width,
        worlds,
        hashlib.sha256(canonical_json(shape).encode()).hexdigest(),
        sampled,
    )


def _expression_record(expression: Expression) -> JSONValue:
    if expression.operator == "atom":
        return expression.atom
    return {expression.operator: [_expression_record(child) for child in expression.children]}


def generate_families(
    seed: int = 17,
    families_per_status: int = RESEARCH_FAMILIES_PER_STATUS,
    widths: tuple[int, ...] = WIDTHS,
    splits: tuple[str, ...] = SPLITS,
) -> tuple[Family, ...]:
    if type(seed) is not int or type(families_per_status) is not int:
        raise ValueError("Seed and family count must be integers")
    if families_per_status < 1:
        raise ValueError("Use a positive family count")
    if not widths or len(set(widths)) != len(widths) or any(w not in WIDTHS for w in widths):
        raise ValueError(
            "Widths must be distinct declared panels including the 254 boundary control"
        )
    if (
        not splits
        or len(set(splits)) != len(splits)
        or any(split not in SPLITS for split in splits)
    ):
        raise ValueError("Splits must be distinct declared train/dev/test panels")
    return tuple(
        _family(seed, split, width, label, index)
        for split in splits
        for width in widths
        for label in STATUSES
        for index in range(families_per_status)
    )


def build_cases(
    seed: int = 17,
    families_per_status: int = RESEARCH_FAMILIES_PER_STATUS,
    widths: tuple[int, ...] = WIDTHS,
    splits: tuple[str, ...] = SPLITS,
) -> tuple[tuple[Case, ...], dict[str, object]]:
    families = generate_families(seed, families_per_status, widths, splits)
    cases = []
    probe_counts: Counter[str] = Counter()
    catalog_counts: Counter[str] = Counter()
    panels: Counter[str] = Counter()
    audit_worlds: list[dict[str, object]] = []
    case_metadata: dict[str, object] = {}
    position_counts: Counter[str] = Counter()
    for family in families:
        base_probe = family.worlds[0][1]
        base_status = status(
            base_probe, next(a for a in base_probe.actions if a.identifier == base_probe.probe)
        )
        for kind, world in family.worlds:
            labels, accepted, length, states = reference(world)
            if any(labels[a.identifier] != status(world, a) for a in world.actions):
                raise ValueError("Independent requirement teacher disagrees")
            if set(accepted) != set(optimal(world)) or length != distance(world):
                raise ValueError("Independent planning teacher disagrees")
            if kind != "original" and labels[world.probe] == base_status:
                raise ValueError("Declared intervention did not change queried status")
            probe_counts[labels[world.probe]] += 1
            catalog_counts.update(labels.values())
            panels[f"{family.split}/{family.width}/{labels[world.probe]}"] += 1
            signatures = {(a.requires, a.effects) for a in world.actions}
            successors = {
                tuple(sorted({**dict(world.facts), **dict(a.effects)}.items()))
                for a in world.actions
                if labels[a.identifier] == "met"
            }
            audit_worlds.append(
                {
                    "family": family.identifier,
                    "intervention": kind,
                    "probe_status": labels[world.probe],
                    "catalog_status": dict(Counter(labels.values())),
                    "action_count": len(world.actions),
                    "action_menu_count": len(world.actions) + 2,
                    "distinct_requirement_effect_pairs": len(signatures),
                    "distinct_permitted_successors": len(successors),
                    "optimal_count": len(accepted),
                    "distance": length,
                    "reachable_states": states,
                    "writable_atom_count": len(
                        {name for action in world.actions for name, _ in action.effects}
                    ),
                }
            )
            presentations = (
                ("familiar", "layout", "rename", "order")
                if family.split == "train"
                else ("familiar", "wording", "rename", "order")
            )
            for presentation in presentations:
                displayed = _rename(world, "q") if presentation == "rename" else world
                if presentation == "order":
                    displayed = replace(displayed, actions=tuple(reversed(displayed.actions)))
                mapping = {
                    old.identifier: new.identifier
                    for old, new in zip(world.actions, displayed.actions, strict=True)
                }
                expected_actions = tuple(mapping.get(item, item) for item in accepted)
                if presentation == "order":
                    expected_actions = accepted
                for task in ("judgment", "action"):
                    name = family.identifier + f"/{kind}/{presentation}/{task}"
                    case_id = "authored-" + hashlib.sha256(name.encode()).hexdigest()
                    public = request(
                        displayed,
                        case_id,
                        task,
                        wording="held_out" if presentation == "wording" else "familiar",
                        menu_rotation=int(
                            hashlib.sha256(family.identifier.encode()).hexdigest(), 16
                        ),
                        reverse_menu=presentation == "order",
                    )
                    if presentation == "layout":
                        public = replace(
                            public,
                            text=json.dumps(
                                strict_json_loads(public.text), ensure_ascii=False, indent=2
                            ),
                        )
                    expected: tuple[JSONValue, ...] = (
                        (labels[world.probe],) if task == "judgment" else expected_actions
                    )
                    cases.append(Case(public, expected, family.identifier, VERSION, family.split))
                    case_metadata[case_id] = {
                        "family": family.identifier,
                        "width": family.width,
                        "task": task,
                        "intervention": kind,
                        "presentation": presentation,
                        "split": family.split,
                    }
                    for position, choice in enumerate(public.choices):
                        if choice.id in expected:
                            position_counts[f"{task}/{len(public.choices)}/{position}"] += 1
    if len(set(probe_counts.values())) != 1:
        raise ValueError("Authored probe panel is not balanced")
    audit: dict[str, object] = {
        "version": VERSION,
        "seed": seed,
        "family_count": len(families),
        "case_count": len(cases),
        "probe_status_counts_before_presentations": dict(probe_counts),
        "catalog_status_counts_before_presentations": dict(catalog_counts),
        "panel_probe_counts": dict(sorted(panels.items())),
        "worlds": audit_worlds,
        "case_metadata": case_metadata,
        "acceptable_answer_position_counts": dict(sorted(position_counts.items())),
        "shape_hashes": {family.identifier: family.shape_hash for family in families},
        "distinct_shape_hashes": len({family.shape_hash for family in families}),
        "presentation_counts": dict(
            Counter(
                f"{metadata['split']}/{metadata['presentation']}"
                for metadata in (
                    entry for entry in case_metadata.values() if isinstance(entry, dict)
                )
            )
        ),
        "families_per_status": families_per_status,
        "splits": list(splits),
        "widths": list(widths),
        "probe_sampling": {
            family.identifier: {
                "attempts": family.probe_receipt.attempts,
                "rejections": dict(family.probe_receipt.rejections),
                "depth": family.probe_receipt.depth,
                "essential_atom_count": family.probe_receipt.atom_count,
                "ordered_truth_function_hash": family.probe_receipt.truth_function_hash,
            }
            for family in families
        },
        "distinct_ordered_probe_functions": len(
            {family.probe_receipt.truth_function_hash for family in families}
        ),
        "shape_hash_scope": "generator-role graph signatures; not graph-isomorphism certificates",
        "oracle": "independent ternary tables and explicit graph/reverse BFS",
    }
    return tuple(cases), audit

"""Bounded deterministic intervention sampling over essential ternary atoms."""

from __future__ import annotations

import hashlib
import random
from collections import Counter
from dataclasses import dataclass, replace

from ..api import canonical_json
from .requirements import Expression, Status, value


@dataclass(frozen=True)
class Probe:
    original: Expression
    operator_edit: Expression
    facts: tuple[tuple[str, bool], ...]
    fact_edit: tuple[tuple[str, bool], ...]
    attempts: int
    rejections: tuple[tuple[str, int], ...]
    depth: int
    atom_count: int
    truth_function_hash: str


def _shape(depth: int, rng: random.Random) -> Expression:
    if depth == 0:
        return Expression("atom", "placeholder")
    arity = rng.choice((2, 3))
    children = [_shape(depth - 1, rng)]
    children.extend(_shape(rng.randrange(depth), rng) for _ in range(arity - 1))
    rng.shuffle(children)
    return Expression(rng.choice(("AND", "OR")), children=tuple(children))


def _leaves(expression: Expression) -> int:
    return 1 if expression.operator == "atom" else sum(_leaves(x) for x in expression.children)


def _instantiate(shape: Expression, names: list[str]) -> Expression:
    if shape.operator == "atom":
        return Expression("atom", names.pop())
    return Expression(
        shape.operator, children=tuple(_instantiate(x, names) for x in shape.children)
    )


def _label(expression: Expression, facts: dict[str, bool]) -> Status:
    result = value(expression, facts)
    return "unknown" if result is None else "met" if result else "violated"


def sample_probe(rng: random.Random, target: Status, split: str, *, limit: int = 10000) -> Probe:
    rejected: Counter[str] = Counter()
    for attempt in range(1, limit + 1):
        depth = 2 if split == "train" else 3 if split == "dev" else 4
        shape = _shape(depth, rng)
        count = _leaves(shape)
        atom_count = rng.choice((4, 5, 6))
        if not atom_count <= count <= 24:
            rejected["leaf_budget"] += 1
            continue
        atoms = [f"observation{i}" for i in range(atom_count)]
        names = atoms + [rng.choice(atoms) for _ in range(count - atom_count)]
        rng.shuffle(names)
        expression = _instantiate(shape, names)
        assignment = {name: rng.choice((False, None, True)) for name in atoms}
        facts = {name: result for name, result in assignment.items() if result is not None}
        if _label(expression, facts) != target:
            rejected["base_label"] += 1
            continue
        edited = replace(expression, operator="OR" if expression.operator == "AND" else "AND")
        changed_label = _label(edited, facts)
        if changed_label == target:
            rejected["operator_unchanged"] += 1
            continue
        remaining = ({"met", "violated", "unknown"} - {target, changed_label}).pop()
        candidates = []
        for name in atoms:
            for new_value in (False, None, True):
                if new_value is assignment[name]:
                    continue
                changed = dict(facts)
                if new_value is None:
                    changed.pop(name, None)
                else:
                    changed[name] = new_value
                if _label(expression, changed) == remaining:
                    candidates.append(changed)
        if not candidates:
            rejected["no_single_fact_remaining_class"] += 1
            continue
        # Every independently supplied atom must influence the Boolean function;
        # mentioning an absorbed/dead variable does not count as extra complexity.
        table = [
            value(expression, {name: bool(mask & (1 << index)) for index, name in enumerate(atoms)})
            for mask in range(1 << atom_count)
        ]
        if any(
            not any(table[mask] != table[mask ^ (1 << bit)] for mask in range(1 << atom_count))
            for bit in range(atom_count)
        ):
            rejected["nonessential_atom"] += 1
            continue
        fact_edit = rng.choice(candidates)
        return Probe(
            expression,
            edited,
            tuple(sorted(facts.items())),
            tuple(sorted(fact_edit.items())),
            attempt,
            tuple(sorted(rejected.items())),
            depth,
            atom_count,
            hashlib.sha256(
                canonical_json({"atom_count": atom_count, "ordered_boolean_table": table}).encode()
            ).hexdigest(),
        )
    raise ValueError(f"Probe search exhausted {limit} attempts: {dict(rejected)}")

"""Explicit three-valued requirements and unit-cost state transitions."""

from __future__ import annotations

from dataclasses import dataclass, replace
from typing import Literal

from ..api import Choice, JSONValue, Request, canonical_json

Status = Literal["met", "violated", "unknown"]
MAX_REACHABLE_STATES = 4096


@dataclass(frozen=True)
class Expression:
    operator: Literal["atom", "AND", "OR"]
    atom: str = ""
    children: tuple[Expression, ...] = ()

    def __post_init__(self) -> None:
        if self.operator == "atom":
            if not self.atom or self.children:
                raise ValueError("An atom needs a name and no children")
        elif self.operator in ("AND", "OR"):
            if self.atom or len(self.children) < 2:
                raise ValueError("A compound needs at least two children and no atom")
        else:
            raise ValueError("Unknown requirement operator")


@dataclass(frozen=True)
class Action:
    identifier: str
    requires: Expression
    effects: tuple[tuple[str, bool], ...]


@dataclass(frozen=True)
class World:
    goal: str
    facts: tuple[tuple[str, bool], ...]
    actions: tuple[Action, ...]
    probe: str

    def __post_init__(self) -> None:
        if not self.goal or not self.actions:
            raise ValueError("World requires a goal and actions")
        if len(dict(self.facts)) != len(self.facts):
            raise ValueError("Repeated fact")
        if any(type(value) is not bool for _, value in self.facts):
            raise ValueError("Observations must be Boolean; absence means unknown")
        identifiers = {action.identifier for action in self.actions}
        if len(identifiers) != len(self.actions) or self.probe not in identifiers:
            raise ValueError("Repeated action or missing probe")
        if identifiers & {"__stop__", "__abstain__"}:
            raise ValueError("Reserved action identifier")
        writable = set()
        for action in self.actions:
            if not action.identifier or not action.effects:
                raise ValueError("Action requires an identifier and effects")
            if len(dict(action.effects)) != len(action.effects):
                raise ValueError("Repeated effect")
            for name, value in action.effects:
                if not name or type(value) is not bool:
                    raise ValueError("Effects must be named Boolean assignments")
                writable.add(name)
        if len(writable) > 12:
            raise ValueError("Authored state space is bounded to twelve writable atoms")


def value(expression: Expression, facts: dict[str, bool]) -> bool | None:
    if expression.operator == "atom":
        return facts.get(expression.atom)
    children = [value(child, facts) for child in expression.children]
    if expression.operator == "AND":
        if False in children:
            return False
        return None if None in children else True
    if True in children:
        return True
    return None if None in children else False


def status(world: World, action: Action) -> Status:
    result = value(action.requires, dict(world.facts))
    return "unknown" if result is None else "met" if result else "violated"


def transition(world: World, identifier: str) -> World:
    action = next((item for item in world.actions if item.identifier == identifier), None)
    if action is None or status(world, action) != "met":
        raise ValueError("Action is absent or its requirements are not met")
    facts = dict(world.facts)
    facts.update(action.effects)
    return replace(world, facts=tuple(sorted(facts.items())))


def _solve(world: World) -> tuple[int | None, tuple[str, ...]]:
    initial = tuple(sorted(world.facts))
    frontier = {initial: set[str]()}
    visited = {initial: 0}
    steps = 0
    while frontier:
        winners: set[str] = set()
        reached = False
        for state, first in frontier.items():
            if dict(state).get(world.goal) is True:
                reached = True
                winners.update(first)
        if reached:
            return steps, tuple(a.identifier for a in world.actions if a.identifier in winners)
        following_layer: dict[tuple[tuple[str, bool], ...], set[str]] = {}
        for state, first in frontier.items():
            observations = dict(state)
            for action in world.actions:
                if value(action.requires, observations) is not True:
                    continue
                successor = dict(observations)
                successor.update(action.effects)
                key = tuple(sorted(successor.items()))
                previous = visited.get(key)
                if previous is not None and previous < steps + 1:
                    continue
                if previous is None and len(visited) >= MAX_REACHABLE_STATES:
                    raise ValueError("Production graph exceeds declared state cap")
                visited[key] = steps + 1
                origins = {action.identifier} if steps == 0 else first
                following_layer.setdefault(key, set()).update(origins)
        frontier = following_layer
        steps += 1
    return None, ()


def distance(world: World) -> int | None:
    return _solve(world)[0]


def optimal(world: World) -> tuple[str, ...]:
    steps, actions = _solve(world)
    if steps is None:
        return ("__abstain__",)
    if steps == 0:
        return ("__stop__",)
    return actions


def expression_json(expression: Expression) -> JSONValue:
    if expression.operator == "atom":
        return expression.atom
    return {expression.operator: [expression_json(child) for child in expression.children]}


def public_world(world: World) -> dict[str, JSONValue]:
    return {
        "facts": dict(world.facts),
        "goal": world.goal,
        "actions": [
            {
                "id": action.identifier,
                "requires": expression_json(action.requires),
                "effects": dict(action.effects),
            }
            for action in world.actions
        ],
    }


SEMANTICS = (
    "Facts explicitly marked true or false are known; omitted facts are unknown. "
    "AND is false if any operand is false, true if all are true, otherwise unknown. "
    "OR is true if any operand is true, false if all are false, otherwise unknown. "
    "Only actions with true requirements may execute. Their Boolean assignments replace "
    "the named facts. All actions cost one step."
)


def request(
    world: World,
    identifier: str,
    task: str,
    *,
    wording: str = "familiar",
    menu_rotation: int = 0,
    reverse_menu: bool = False,
) -> Request:
    state = public_world(world)
    if task == "judgment":
        target = next(action for action in world.actions if action.identifier == world.probe)
        state["queried_action"] = target.identifier
        instructions = (
            "Judge whether the queried action's requirements are met, violated, or unknown."
            if wording == "familiar"
            else "Using only supplied observations, classify the prerequisite expression for the "
            "named candidate. Select satisfied, contradicted, or undetermined respectively."
        )
        criteria = {
            "met": "Requirements are true",
            "violated": "Requirements are false",
            "unknown": "Requirements cannot be established true or false",
        }
    elif task == "action":
        instructions = (
            "Choose any first action of a shortest valid plan to make the goal true. "
            "Choose stop if already true; abstain only if no valid plan can achieve it."
            if wording == "familiar"
            else "Minimize permitted transitions needed to establish the target fact. "
            "Select a valid optimal initial transition, stop at success, or abstain when "
            "success is unreachable. Equally short alternatives are all acceptable."
        )
        criteria = {
            action.identifier: "Execute candidate " + action.identifier for action in world.actions
        }
        criteria.update(
            {
                "__stop__": "Stop: goal is already true",
                "__abstain__": "Abstain: no valid plan can reach the goal",
            }
        )
    else:
        raise ValueError("Unknown authored task")
    items = list(criteria.items())
    offset = menu_rotation % len(items)
    items = items[offset:] + items[:offset]
    if reverse_menu:
        items.reverse()
    criteria = dict(items)
    question: dict[str, JSONValue] = {
        "type": "choice",
        "instructions": SEMANTICS + " " + instructions,
        "criteria": {key: text for key, text in criteria.items()},
    }
    text = canonical_json({"state": state, "question": question, "labels": list(criteria)})
    return Request(
        identifier,
        "jevbench/choice",
        text,
        tuple(Choice(key, text) for key, text in criteria.items()),
    )

"""Independent ternary truth table and explicit graph/reverse-distance oracle.

Does not call the production requirement evaluator, transition or BFS.
"""

from __future__ import annotations

from collections import deque

from .requirements import Expression, Status, World

# Rows/columns are false, unknown, true. These are the declared truth tables.
_AND = ((0, 0, 0), (0, 1, 1), (0, 1, 2))
_OR = ((0, 1, 2), (1, 1, 2), (2, 2, 2))


def truth(expression: Expression, observations: dict[str, bool]) -> int:
    if expression.operator == "atom":
        return (
            1 if expression.atom not in observations else 2 if observations[expression.atom] else 0
        )
    table = _AND if expression.operator == "AND" else _OR
    result = 2 if expression.operator == "AND" else 0
    for child in expression.children:
        result = table[result][truth(child, observations)]
    return result


def reference(world: World) -> tuple[dict[str, Status], tuple[str, ...], int | None, int]:
    initial = tuple(sorted(world.facts))
    states = [initial]
    discovered = {initial}
    edges: dict[tuple[tuple[str, bool], ...], list[tuple[str, tuple[tuple[str, bool], ...]]]] = {}
    reverse: dict[tuple[tuple[str, bool], ...], set[tuple[tuple[str, bool], ...]]] = {}
    cursor = 0
    while cursor < len(states):
        state = states[cursor]
        cursor += 1
        observations = dict(state)
        edges[state] = []
        for action in world.actions:
            if truth(action.requires, observations) != 2:
                continue
            successor = dict(observations)
            for name, assignment in action.effects:
                successor[name] = assignment
            key = tuple(sorted(successor.items()))
            edges[state].append((action.identifier, key))
            reverse.setdefault(key, set()).add(state)
            if key not in discovered:
                discovered.add(key)
                states.append(key)
        if len(discovered) > 4096:
            raise ValueError("Reference graph exceeds declared state cap")
    labels: dict[str, Status] = {
        action.identifier: ("violated", "unknown", "met")[truth(action.requires, dict(initial))]
        for action in world.actions
    }
    distances = {state: 0 for state in states if dict(state).get(world.goal) is True}
    queue = deque(distances)
    while queue:
        state = queue.popleft()
        for previous in reverse.get(state, set()):
            if previous not in distances:
                distances[previous] = distances[state] + 1
                queue.append(previous)
    length = distances.get(initial)
    choices: tuple[str, ...]
    if length is None:
        choices = ("__abstain__",)
    elif length == 0:
        choices = ("__stop__",)
    else:
        choices = tuple(
            identifier
            for identifier, following in edges[initial]
            if distances.get(following) == length - 1
        )
    return labels, choices, length, len(states)

