        )
        if boundary == "choices"
        else public_request("long state " * 100)
    )
    with pytest.raises(ValueError, match="2..64|max_length"):
        as_dmbench_batch(Model(scorer, "fixture"), recipe=NATIVE)(
            (public_request(), public)
        )
    assert not scorer.requests

