def digest(path: Path) -> str:
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def read(path: Path) -> dict[str, object]:
    return cast(dict[str, object], json.loads(path.read_text()))


def verify(pins: dict[Path, str]) -> None:
    if any(digest(path) != sha for path, sha in pins.items()):
        raise ValueError("Frozen source or historical evidence changed")


def python_paths() -> dict[str, Path]:
    """Observe non-hidden checkout Python, including historical executed helpers."""
    paths: dict[str, Path] = {}
    for directory, folders, files in os.walk(ROOT):
        folders[:] = [name for name in folders if not name.startswith(".")]
        for name in files:
            if name.endswith(".py"):
                path = Path(directory) / name
                paths[str(path.relative_to(ROOT))] = path
    return paths


def run(command: list[str], environment: dict[str, str], cap: int) -> dict[str, object]:
    started = time.monotonic()
    child = subprocess.Popen(
        command,
        cwd=ROOT,
        env=environment,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        start_new_session=True,
    )
    timed_out = False
    try:
        stdout, stderr = child.communicate(timeout=cap)
    except subprocess.TimeoutExpired:
        timed_out = True
        try:
            os.killpg(child.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        stdout, stderr = child.communicate()
    finally:
        # Only this new owned session; reap even if the timeout races with exit.
        try:
            os.killpg(child.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        child.wait()
    return {
        "command": command,
        "cwd": str(ROOT),
        "pid": child.pid,
        "cap_seconds": cap,
        "seconds": time.monotonic() - started,
        "timed_out": timed_out,
        "exit_code": child.returncode,
        "reaped": child.poll() is not None,
        "stdout": stdout,
        "stderr": stderr,
    }


