"""Validate local Kai configuration, storage and content identity before loading."""

from __future__ import annotations

import hashlib
import math
import struct
from dataclasses import dataclass
from pathlib import Path

from wyat.wire import JsonObject, JsonValue, decode_json, read_object

ARCHITECTURE = "qwen3-text-endpoints-global-query-shared-bilinear-mlp"


PROMPT_VERSION = "decision2-segmented-options-global-query-v1"


def positive_integer(value: object, name: str) -> int:
    if type(value) is not int or value <= 0:
        raise ValueError(f"{name} must be a positive integer")
    return value


def normalize_config(raw: JsonObject) -> JsonObject:
    if raw.get("model_type") != "qwen3":
        raise ValueError("Kai backend requires a Qwen3 text backbone")
    if raw.get("hidden_act", "silu") != "silu":
        raise ValueError("Kai requires the SiLU backbone activation")
    config = dict(raw)
    layers = config.get("layer_types")
    if layers is not None and (
        not isinstance(layers, list)
        or any(layer != "full_attention" for layer in layers)
    ):
        raise ValueError("Kai requires full causal attention in every layer")
    if config.get("use_sliding_window", False):
        raise ValueError("Kai does not support sliding-window attention")
    rotary = config.pop("rope_parameters", None)
    if rotary is not None:
        if (
            not isinstance(rotary, dict)
            or rotary.get("rope_type") != "default"
            or set(rotary) - {"rope_type", "rope_theta"}
            or "rope_theta" not in rotary
            or config.get("rope_scaling") is not None
            or ("rope_theta" in config and config["rope_theta"] != rotary["rope_theta"])
        ):
            raise ValueError("Unsupported or contradictory rotary configuration")
        config["rope_theta"] = rotary["rope_theta"]
    elif config.get("rope_scaling") is not None:
        raise ValueError("Kai requires the unscaled default rotary recipe")
    theta = config.get("rope_theta", 10000.0)
    if (
        isinstance(theta, bool)
        or not isinstance(theta, (float, int))
        or not math.isfinite(theta)
        or theta <= 0
    ):
        raise ValueError("Rotary theta must be finite and positive")
    config["rope_theta"] = theta
    return config


@dataclass(frozen=True, slots=True)
class TensorSpec:
    dtype: str
    shape: tuple[int, ...]


def tensor_specs(path: Path) -> dict[str, TensorSpec]:
    """Inspect original storage before a framework can silently cast weights."""
    with path.open("rb") as stream:
        size_bytes = stream.read(8)
        if len(size_bytes) != 8:
            raise ValueError(f"Invalid Safetensors file: {path.name}")
        size = struct.unpack("<Q", size_bytes)[0]
        if size > 8 << 20:
            raise ValueError("Safetensors header exceeds 8 MiB limit")
        header = decode_json(stream.read(size))
    if not isinstance(header, dict):
        raise ValueError("Safetensors header must be an object")
    result: dict[str, TensorSpec] = {}
    for name, value in header.items():
        if name == "__metadata__":
            continue
        if not isinstance(value, dict):
            raise ValueError(f"Invalid tensor specification: {name}")
        dtype, shape = value.get("dtype"), value.get("shape")
        if not isinstance(dtype, str) or not isinstance(shape, list):
            raise ValueError(f"Invalid tensor dtype or shape: {name}")
        dimensions: list[int] = []
        for dimension in shape:
            if type(dimension) is not int or dimension < 0:
                raise ValueError(f"Invalid tensor dimension: {name}")
            dimensions.append(dimension)
        result[name] = TensorSpec(dtype, tuple(dimensions))
    return result


def _declared_hashes(value: JsonValue) -> dict[str, str]:
    if not isinstance(value, dict):
        raise ValueError("Manifest files_sha256 must map names to 64-hex digests")
    result: dict[str, str] = {}
    for name, digest in value.items():
        if (
            not isinstance(digest, str)
            or len(digest) != 64
            or any(char not in "0123456789abcdefABCDEF" for char in digest)
        ):
            raise ValueError("Manifest files_sha256 must map names to 64-hex digests")
        result[name] = digest.lower()
    return result


def _identity(root: Path, declared: dict[str, str] | None) -> str:
    names = [
        "decision_config.json",
        "decision_head.safetensors",
        "backbone/config.json",
        "backbone/model.safetensors",
        "tokenizer.json",
        "tokenizer_config.json",
    ]
    names.extend(
        name
        for name in (
            "config.json",
            "MODEL_MANIFEST.json",
            "special_tokens_map.json",
            "added_tokens.json",
            "vocab.json",
            "merges.txt",
        )
        if (root / name).is_file()
    )
    digest = hashlib.sha256()
    for name in sorted(names):
        file_digest = hashlib.sha256()
        with (root / name).open("rb") as stream:
            for block in iter(lambda: stream.read(8 << 20), b""):
                file_digest.update(block)
        if declared is not None and name in declared:
            if file_digest.hexdigest() != declared[name]:
                raise ValueError(
                    f"Checkpoint file differs from declared digest: {name}"
                )
        digest.update(name.encode("utf-8") + b"\0" + file_digest.digest())
    return "kai:" + digest.hexdigest()


@dataclass(frozen=True, slots=True)
class KaiArtifact:
    root: Path
    config: JsonObject
    head_dim: int
    max_options: int
    model_id: str


def load_artifact(path: str | Path, max_length: int) -> KaiArtifact:
    root = Path(path).resolve(strict=True)
    max_length = positive_integer(max_length, "max_length")
    metadata = read_object(root / "decision_config.json")
    if (
        metadata.get("architecture") != ARCHITECTURE
        or metadata.get("prompt_version") != PROMPT_VERSION
        or metadata.get("head_variant", "shared") != "shared"
        or metadata.get("checkpoint_format") not in (None, "full")
        or metadata.get("readout") not in (None, "candidate")
        or metadata.get("dec_residual") is not None
        or metadata.get("head_compute_dtype", "float32") != "float32"
        or metadata.get("backbone_model_type", "qwen3") != "qwen3"
    ):
        raise ValueError(
            "Unsupported Kai checkpoint architecture, prompt, head or format"
        )
    head_dim = positive_integer(metadata.get("head_dim"), "head_dim")
    max_options = positive_integer(metadata.get("max_options"), "max_options")
    if not 2 <= max_options <= 255:
        raise ValueError("Kai max_options must be within 2..255")
    config = normalize_config(read_object(root / "backbone/config.json"))
    cap = positive_integer(
        config.get("max_position_embeddings"), "max_position_embeddings"
    )
    declared = None
    manifest_path = root / "MODEL_MANIFEST.json"
    if manifest_path.exists():
        manifest = read_object(manifest_path)
        if (
            manifest.get("profile") != "qwen-full"
            or manifest.get("storage") is not None
            or manifest.get("calibration") is not None
        ):
            raise ValueError("Unsupported Kai package profile, storage or calibration")
        cap = min(
            cap, positive_integer(manifest.get("max_input_tokens"), "max_input_tokens")
        )
        if "files_sha256" in manifest:
            declared = _declared_hashes(manifest["files_sha256"])
    if max_length > cap:
        raise ValueError(f"max_length exceeds checkpoint limit {cap}")
    read_object(root / "tokenizer_config.json")
    if (root / "config.json").exists():
        read_object(root / "config.json")
    for name, spec in tensor_specs(root / "backbone/model.safetensors").items():
        if spec.dtype not in {"F32", "BF16"}:
            raise ValueError(f"Unsupported backbone tensor dtype: {name}")
    for name, spec in tensor_specs(root / "decision_head.safetensors").items():
        if spec.dtype != "F32":
            raise ValueError(f"Kai head tensor must use float32: {name}")
    return KaiArtifact(root, config, head_dim, max_options, _identity(root, declared))

"""Opt-in exact retained-prefix reuse with maintained CPU FP32 caches."""

from __future__ import annotations

from collections.abc import Sequence
from typing import Protocol, cast

import torch
from transformers import Qwen3Config
from transformers.cache_utils import DynamicCache, DynamicLayer

from wyat.core import Request

from ..encoding import EncodedRequest
from ..torch import KaiScorer

type KVState = tuple[torch.Tensor, torch.Tensor]


class CacheConstructor(Protocol):
    def __call__(
        self,
        *,
        config: Qwen3Config,
        ddp_cache_data: tuple[KVState, ...] | None = None,
    ) -> DynamicCache: ...


# The maintained constructor is untyped; narrow only this external boundary.
new_cache = cast(CacheConstructor, DynamicCache)


def _cache(
    config: Qwen3Config, states: tuple[KVState, ...] | None = None
) -> DynamicCache:
    try:
        owner = new_cache(config=config, ddp_cache_data=states)
        if (
            type(owner) is not DynamicCache
            or len(owner.layers) != config.num_hidden_layers
            or any(type(layer) is not DynamicLayer for layer in owner.layers)
        ):
            raise ValueError("CPU prefix requires stock full-attention DynamicCache")
        return owner
    except (TypeError, AttributeError) as error:
        raise ValueError("CPU prefix requires maintained DynamicCache APIs") from error


def _prepared_cache(config: Qwen3Config) -> DynamicCache:
    """Check seed/copy/append semantics before any model prefix forward."""
    try:
        empty = _cache(config)
        if empty.get_seq_length() != 0 or empty.get_mask_sizes(1, 0) != (1, 0):
            raise ValueError("CPU prefix requires an empty full-attention cache")
        kv_heads = config.num_key_value_heads
        if kv_heads is None or kv_heads <= 0:
            raise ValueError("CPU prefix requires configured key/value heads")
        seed = torch.zeros(
            (1, kv_heads, 1, config.head_dim), dtype=torch.float32, device="cpu"
        )
        owner = _cache(config, tuple((seed, seed) for _ in empty.layers))
        for raw_layer in owner.layers:
            layer = cast(DynamicLayer, raw_layer)  # Exact stock type checked by _cache.
            if (
                layer.keys is None
                or layer.values is None
                or layer.keys.data_ptr() == seed.data_ptr()
                or layer.values.data_ptr() == seed.data_ptr()
                or not torch.equal(layer.keys, seed)
                or not torch.equal(layer.values, seed)
            ):
                raise ValueError("CPU prefix requires independently owned cache seeds")
        if owner.get_seq_length() != 1 or owner.get_mask_sizes(1, 0) != (2, 0):
            raise ValueError(
                "CPU prefix requires absolute full-attention cache lengths"
            )
        seeded = cast(DynamicLayer, owner.layers[0]).keys
        suffix = torch.ones_like(seed)
        keys, values = owner.update(suffix, suffix, 0)
        if (
            seeded is None
            or owner.get_seq_length() != 2
            or keys.data_ptr() == seeded.data_ptr()
            or not torch.equal(seeded, seed)
            or not torch.equal(keys[..., :1, :], seed)
            or not torch.equal(values[..., :1, :], seed)
            or not torch.equal(keys[..., 1:, :], suffix)
            or not torch.equal(values[..., 1:, :], suffix)
        ):
            raise ValueError("CPU prefix requires allocating cache concatenation")
        return empty
    except (TypeError, AttributeError) as error:
        raise ValueError("CPU prefix requires maintained DynamicCache APIs") from error


class PrefixScorer:
    """Eager immutable prefix snapshots; each call owns a retained stock cache.

    Keep the base weights, head, config, device and encoder fixed for this
    resource's lifetime. No suffix state survives a call. Matching batches retain
    all layers' extended K/V through readout; this explicitly trades memory for
    prefix reuse. A mixed or overlapping-readout batch falls back intact.
    """

    def __init__(self, base: KaiScorer, prefix: tuple[int, ...]) -> None:
        if not isinstance(base, KaiScorer):
            raise TypeError("CPU prefix requires a KaiScorer base")
        if type(prefix) is not tuple:
            raise TypeError("Prefix must be an exact immutable token tuple")
        self._require_no_autocast()
        config = base.backbone.config
        rotary = config.rope_parameters
        if (
            not isinstance(rotary, dict)
            or rotary.get("rope_type", "default") != "default"
        ):
            raise ValueError("CPU prefix requires default unscaled RoPE")
        if (
            base.device.type != "cpu"
            or config._attn_implementation != "sdpa"
            or any(module.training for module in base.backbone.modules())
            or any(module.training for module in base.head.modules())
            or any(
                value.device.type != "cpu" or value.dtype != torch.float32
                for value in (*base.backbone.parameters(), *base.head.parameters())
            )
            or any(value.device.type != "cpu" for value in base.backbone.buffers())
            or base.backbone.has_sliding_layers
        ):
            raise ValueError("CPU prefix requires eval FP32 CPU SDPA full attention")
        self._require_no_hooks(base)
        if (
            not prefix
            or len(prefix) >= base.max_length
            or any(
                type(token) is not int or not 0 <= token < config.vocab_size
                for token in prefix
            )
        ):
            raise ValueError("Prefix requires valid nonempty tokens below max_length")
        self.base = base
        self.model_id = base.model_id
        self._prefix = prefix
        with torch.inference_mode():
            cache = _prepared_cache(config)
            base.backbone(
                input_ids=torch.tensor([prefix], dtype=torch.long, device="cpu"),
                past_key_values=cache,
                use_cache=True,
            )
            if len(cache.layers) != config.num_hidden_layers:
                raise ValueError("Maintained cache omitted a prefix layer")
            states: list[KVState] = []
            for raw_layer in cache.layers:
                if type(raw_layer) is not DynamicLayer:
                    raise ValueError("CPU prefix requires stock DynamicLayer state")
                layer = raw_layer
                keys, values = layer.keys, layer.values
                if (
                    keys is None
                    or values is None
                    or keys.shape != values.shape
                    or tuple(keys.shape)
                    != (1, config.num_key_value_heads, len(prefix), config.head_dim)
                    or keys.device.type != "cpu"
                    or values.device.type != "cpu"
                    or keys.dtype != torch.float32
                    or values.dtype != torch.float32
                    or keys.stride(-1) != 1
                    or values.stride(-1) != 1
                    or not torch.isfinite(keys).all().item()
                    or not torch.isfinite(values).all().item()
                ):
                    raise ValueError(
                        "Maintained cache did not retain exact FP32 prefix"
                    )
                states.append(
                    (
                        keys.detach().clone().contiguous(),
                        values.detach().clone().contiguous(),
                    )
                )
            self._states = tuple(states)

    @staticmethod
    def _require_no_autocast() -> None:
        if torch.is_autocast_enabled("cpu"):
            raise ValueError("CPU prefix requires disabled CPU autocast")

    @staticmethod
    def _require_no_hooks(base: KaiScorer) -> None:
        if any(
            module._forward_hooks or module._forward_pre_hooks
            for module in base.backbone.modules()
        ):
            raise ValueError("CPU prefix does not support backbone forward hooks")

    @property
    def prefix(self) -> tuple[int, ...]:
        return self._prefix

    @property
    def prefix_state_bytes(self) -> int:
        return sum(
            value.numel() * value.element_size()
            for pair in self._states
            for value in pair
        )

    def _admits(self, row: EncodedRequest) -> bool:
        length = len(self.prefix)
        return (
            len(row.ids) > length
            and row.ids[:length] == self.prefix
            and row.query_position >= length
            and all(position >= length for position in row.candidate_positions)
        )

    def _fork(self, batch_size: int) -> DynamicCache:
        if type(batch_size) is not int or batch_size < 1:
            raise ValueError("Cache batch size must be a positive integer")
        states = tuple(
            (keys.expand(batch_size, -1, -1, -1), values.expand(batch_size, -1, -1, -1))
            for keys, values in self._states
        )
        return _cache(self.base.backbone.config, states)

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        self._require_no_autocast()
        self._require_no_hooks(self.base)
        if not requests:
            return []
        # Admission belongs to complete original rows before removing any tokens.
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self._admits(row) for row in encoded):
            return self.base._score_encoded(encoded)
        with torch.inference_mode():
            return self.base._score_encoded(
                encoded, prefix_length=len(self.prefix), cache=self._fork(len(encoded))
            )

"""The maintained tokenizer policy and exact segmented Kai request encoding."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import NamedTuple, Protocol, cast

from wyat.core import Request
from wyat.wire import read_object

from .artifact import KaiArtifact, positive_integer

SUFFIX = (
    "\n\nSelect the single option best supported by the context and instructions."
    "\nDecision:"
)


class EncodedRequest(NamedTuple):
    ids: tuple[int, ...]
    candidate_positions: tuple[int, ...]
    query_position: int


class TokenizerProtocol(Protocol):
    @property
    def pad_token_id(self) -> int | None: ...

    @property
    def eos_token_id(self) -> int | None: ...

    def encode(self, text: str, *, add_special_tokens: bool = False) -> list[int]: ...


def load_tokenizer(root: Path) -> TokenizerProtocol:
    from transformers import AutoTokenizer

    config = read_object(root / "tokenizer_config.json")
    if config.get("fast_tokenizer_files"):
        raise ValueError(
            "Alternate tokenizer files require an explicit export contract"
        )
    # HF owns Qwen normalization, configured special tokens and legacy overrides.
    # Direct tokenizer.json loading silently skips those parts of the recipe.
    try:
        return cast(
            TokenizerProtocol,
            AutoTokenizer.from_pretrained(
                root,
                local_files_only=True,
                trust_remote_code=False,
            ),
        )
    except Exception as exc:
        raise ValueError(f"Cannot load local tokenizer: {exc}") from exc


class KaiEncoder:
    """Exact segmented tokens; cached values never contain contextual vectors."""

    def __init__(
        self,
        tokenizer: TokenizerProtocol,
        *,
        max_length: int,
        max_options: int,
        token_cache_size: int = 0,
    ) -> None:
        self.max_length = positive_integer(max_length, "max_length")
        if type(token_cache_size) is not int or token_cache_size < 0:
            raise ValueError("token_cache_size must be a nonnegative integer")
        self.tokenizer = tokenizer
        self.max_options = max_options
        self._option_tokens = lru_cache(maxsize=token_cache_size)(self._tokens)
        self._suffix = self._tokens(SUFFIX)
        pad_id = tokenizer.pad_token_id
        if pad_id is None:
            pad_id = tokenizer.eos_token_id
        if pad_id is None:
            raise ValueError("Tokenizer requires a pad or EOS token")
        self.pad_id = pad_id

    @classmethod
    def from_artifact(
        cls, artifact: KaiArtifact, *, max_length: int, token_cache_size: int = 0
    ) -> KaiEncoder:
        return cls(
            load_tokenizer(artifact.root),
            max_length=max_length,
            max_options=artifact.max_options,
            token_cache_size=token_cache_size,
        )

    def _tokens(self, text: str) -> tuple[int, ...]:
        if len(text.encode("utf-8")) > self.max_length * 32:
            raise ValueError("Input segment exceeds tokenization byte limit")
        ids = tuple(self.tokenizer.encode(text, add_special_tokens=False))
        if not ids or len(ids) > self.max_length:
            raise ValueError(
                "Input segment is empty or exceeds max_length; no truncation"
            )
        return ids

    def encode_request(self, request: Request) -> EncodedRequest:
        if request.task != "choice":
            raise ValueError("Kai currently supports choice requests only")
        if not 2 <= len(request.candidates) <= self.max_options:
            raise ValueError(f"Kai requires 2..{self.max_options} candidates")
        prefix = (
            f"Context:\n{request.context}\n\n"
            f"Task type: choice\nQuestion:\n{request.query}\nOptions:"
        )
        ids = list(self._tokens(prefix))
        positions: list[int] = []
        for candidate in request.candidates:
            payload = json.dumps(
                {"key": candidate.id, "description": candidate.text},
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            )
            ids.extend(self._option_tokens("\n<option>\n" + payload + "\n</option>"))
            positions.append(len(ids) - 1)
        ids.extend(self._suffix)
        if len(ids) > self.max_length:
            raise ValueError(
                f"{len(ids)} tokens exceeds max_length={self.max_length}; no truncation"
            )
        return EncodedRequest(tuple(ids), tuple(positions), len(ids) - 1)

"""Opt-in eager immutable prefix reuse for the native Kai scorer."""

from __future__ import annotations

from collections.abc import Callable, Sequence
from typing import Protocol, cast

import mlx.core as mx
from mlx_lm.models.cache import KVCache

from wyat.core import Request

from .encoding import EncodedRequest
from .mlx import MLXKaiScorer, _pack
from .readout import EndpointCache, cached_endpoint_hidden

type KVState = tuple[mx.array, mx.array]


class PrefixCache(EndpointCache, Protocol):
    @property
    def state(self) -> KVState: ...

    @state.setter
    def state(self, value: KVState) -> None: ...


type CachedForward = Callable[[mx.array, list[PrefixCache]], mx.array]
# The maintained cache/model APIs are untyped; narrow only those boundaries.
new_cache = cast(Callable[[], PrefixCache], KVCache)


class PrefixScorer:
    """One immutable prefix for fixed weights/device; fresh cache owners per call.

    Exact logical-length snapshots force KVCache to grow before suffix writes,
    so broadcast prefix views are never appended to in place. A mixed or
    overlapping-readout batch falls back intact to the original scorer.
    Weights, device and encoder must remain fixed for this resource lifetime.
    The admitted path is eager; the final block visits only actual readouts.
    """

    def __init__(self, base: MLXKaiScorer, prefix: tuple[int, ...]) -> None:
        if not isinstance(base, MLXKaiScorer):
            raise TypeError("Prefix requires a native MLXKaiScorer base")
        if type(prefix) is not tuple:
            raise TypeError("Prefix must be an exact immutable token tuple")
        if base.compiled:
            raise ValueError("Prefix scorer requires an eager, uncompiled base")
        if base.backbone.args.rope_scaling is not None:
            raise ValueError("Prefix scorer requires unscaled native RoPE")
        if (
            not prefix
            or len(prefix) >= base.encoder.max_length
            or any(
                type(token) is not int or not 0 <= token < base.backbone.vocab_size
                for token in prefix
            )
        ):
            raise ValueError(
                "Prefix requires nonempty valid token IDs below max_length"
            )
        self.base = base
        self.model_id = base.model_id
        self._prefix = prefix
        self._forward = cast(CachedForward, base.backbone)
        with mx.stream(base.device):
            caches = [new_cache() for _ in base.backbone.layers]
            self._forward(mx.array([list(prefix)], dtype=mx.int32), caches)
            self._states = tuple(
                (mx.contiguous(keys), mx.contiguous(values))
                for keys, values in (cache.state for cache in caches)
            )
            if any(
                cache.offset != len(prefix)
                or keys.shape[0] != 1
                or keys.shape[2] != len(prefix)
                or values.shape[:3] != keys.shape[:3]
                for cache, (keys, values) in zip(caches, self._states, strict=True)
            ):
                raise ValueError("Maintained cache did not retain the exact prefix")
            mx.eval(self._states)

    @property
    def prefix(self) -> tuple[int, ...]:
        return self._prefix

    @property
    def prefix_state_bytes(self) -> int:
        return sum(keys.nbytes + values.nbytes for keys, values in self._states)

    def _admits(self, row: EncodedRequest) -> bool:
        length = len(self.prefix)
        return (
            len(row.ids) > length
            and row.ids[:length] == self.prefix
            and row.query_position >= length
            and all(position >= length for position in row.candidate_positions)
        )

    def _fork(self, batch_size: int) -> list[PrefixCache]:
        caches: list[PrefixCache] = []
        for keys, values in self._states:
            cache = new_cache()
            cache.state = (
                mx.broadcast_to(keys, (batch_size, *keys.shape[1:])),
                mx.broadcast_to(values, (batch_size, *values.shape[1:])),
            )
            caches.append(cache)
        return caches

    def _logits(
        self,
        ids: mx.array,
        endpoints: mx.array,
        query_positions: mx.array,
        caches: list[PrefixCache],
    ) -> mx.array:
        positions = mx.concatenate([endpoints, query_positions[:, None]], axis=1)
        hidden = cached_endpoint_hidden(self.base.backbone, ids, positions, caches)
        return self.base.head(hidden[:, :-1], hidden[:, -1])

    def score_many(self, requests: Sequence[Request]) -> list[list[float]]:
        if not requests:
            return []
        encoded = [self.base.encode_request(request) for request in requests]
        if not all(self._admits(row) for row in encoded):
            return self.base.score_many(requests)
        prefix_length = len(self.prefix)
        with mx.stream(self.base.device):
            ids, endpoints, positions = _pack(
                encoded, self.base.encoder.pad_id, prefix_length=prefix_length
            )
            logits = self._logits(ids, endpoints, positions, self._fork(len(encoded)))
            mx.eval(logits)
            values = cast(list[list[float]], logits.tolist())
        return [
            row[: len(item.candidate_positions)]
            for row, item in zip(values, encoded, strict=True)
        ]

"""Immutable decision values and the sole runtime boundary: batches of logits."""

from __future__ import annotations

import math
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from numbers import Real
from typing import Protocol, cast


def _text(value: object, name: str, *, nonempty: bool = False) -> str:
    if not isinstance(value, str) or (nonempty and not value.strip()):
        raise ValueError(f"{name} must be {'nonempty ' if nonempty else ''}text")
    try:
        value.encode("utf-8")
    except UnicodeEncodeError as error:
        raise ValueError(f"{name} must contain valid Unicode") from error
    return value


@dataclass(frozen=True, slots=True)
class Candidate:
    id: str
    text: str

    def __post_init__(self) -> None:
        _text(self.id, "candidate.id", nonempty=True)
        _text(self.text, "candidate.text", nonempty=True)


@dataclass(frozen=True, slots=True)
class Request:
    query: str
    candidates: tuple[Candidate, ...]
    context: str = ""
    task: str = "choice"

    def __post_init__(self) -> None:
        _text(self.query, "query", nonempty=True)
        _text(self.context, "context")
        _text(self.task, "task", nonempty=True)
        if not isinstance(self.candidates, tuple) or not self.candidates:
            raise ValueError("candidates must be a nonempty tuple")
        if not all(isinstance(candidate, Candidate) for candidate in self.candidates):
            raise ValueError("candidates must contain Candidate values")
        ids = [candidate.id for candidate in self.candidates]
        if len(set(ids)) != len(ids):
            raise ValueError("candidate IDs must be unique")


class Scorer(Protocol):
    """Return finite raw logits in request and candidate order.

    Sigmoid scores, embeddings, and calibrated probabilities require their own
    model contracts; they do not satisfy this interface by renaming outputs.
    Implementations own batching, model state, tokenization, and resource limits.
    """

    def score_many(self, requests: Sequence[Request]) -> Sequence[Sequence[float]]: ...


class ModelOutputError(ValueError):
    """A scorer violated its output contract, rather than rejecting an input."""


@dataclass(frozen=True, slots=True)
class Decision:
    model_id: str
    scores: tuple[float, ...]
    probabilities: tuple[float, ...]
    ranking: tuple[str, ...]

    @property
    def selected(self) -> str:
        return self.ranking[0]

    def to_dict(self) -> dict[str, object]:
        return {
            "model_id": self.model_id,
            "selected": self.selected,
            "ranking": list(self.ranking),
            "scores": list(self.scores),
            "probabilities": list(self.probabilities),
        }


def decision_from_logits(
    request: Request, logits: Sequence[float], model_id: str
) -> Decision:
    """Pure interpretation; softmax values are relative, uncalibrated likelihoods."""
    if len(logits) != len(request.candidates):
        raise ModelOutputError("scorer returned a different candidate count")
    if any(isinstance(value, bool) or not isinstance(value, Real) for value in logits):
        raise ModelOutputError("scorer logits must be numbers")
    scores = tuple(float(value) for value in logits)
    if not all(math.isfinite(value) for value in scores):
        raise ModelOutputError("scorer logits must be finite")
    peak = max(scores)
    weights = tuple(math.exp(value - peak) for value in scores)
    total = math.fsum(weights)
    probabilities = tuple(weight / total for weight in weights)
    # Python's stable sort preserves caller order for exact ties.
    order = sorted(range(len(scores)), key=scores.__getitem__, reverse=True)
    return Decision(
        model_id,
        scores,
        probabilities,
        tuple(request.candidates[index].id for index in order),
    )


class Model:
    """A loaded logit scorer. Loading and inference are separate lifetimes."""

    def __init__(self, scorer: Scorer, model_id: str) -> None:
        _text(model_id, "model_id", nonempty=True)
        self._scorer = scorer
        self._model_id = model_id

    @property
    def model_id(self) -> str:
        return self._model_id

    def decide(self, request: Request) -> Decision:
        return self.decide_many((request,))[0]

    def decide_many(self, requests: Sequence[Request]) -> tuple[Decision, ...]:
        batch = tuple(requests)
        if not all(isinstance(request, Request) for request in batch):
            raise ValueError("batch must contain Request values")
        if not batch:
            return ()
        logits = self._scorer.score_many(batch)
        if len(logits) != len(batch):
            raise ModelOutputError("scorer returned a different request count")
        return tuple(
            decision_from_logits(request, scores, self.model_id)
            for request, scores in zip(batch, logits, strict=True)
        )


def request_from_dict(value: object) -> Request:
    if not isinstance(value, Mapping):
        raise ValueError("request must be an object")
    value = cast(Mapping[str, object], value)
    if set(value) - {"query", "candidates", "context", "task"}:
        raise ValueError("unknown request fields")
    if "query" not in value or "candidates" not in value:
        raise ValueError("request requires query and candidates")
    items = value["candidates"]
    if not isinstance(items, list):
        raise ValueError("candidates must be an array")
    candidates: list[Candidate] = []
    for item in items:
        if not isinstance(item, Mapping) or set(item) != {"id", "text"}:
            raise ValueError("candidate requires exactly id and text")
        item = cast(Mapping[str, object], item)
        candidates.append(
            Candidate(
                _text(item["id"], "candidate.id", nonempty=True),
                _text(item["text"], "candidate.text", nonempty=True),
            )
        )
    return Request(
        _text(value["query"], "query", nonempty=True),
        tuple(candidates),
        _text(value.get("context", ""), "context"),
        _text(value.get("task", "choice"), "task", nonempty=True),
    )

"""Failure-inclusive evaluation of a declared choice scorer on supplied cases."""

from __future__ import annotations

import hashlib
import json
import math
import time
from collections.abc import Iterable, Mapping, Sequence
from dataclasses import dataclass

from .core import Decision, Model, Request, request_from_dict


@dataclass(frozen=True, slots=True)
class EvaluationCase:
    id: str
    request: Request
    expected: tuple[str, ...]

    def __post_init__(self) -> None:
        if not isinstance(self.id, str) or not self.id.strip():
            raise ValueError("case ID must be nonempty text")
        if not isinstance(self.request, Request):
            raise ValueError("case request must be a Request")
        if (
            not isinstance(self.expected, tuple)
            or not self.expected
            or any(not isinstance(label, str) or not label for label in self.expected)
            or len(set(self.expected)) != len(self.expected)
        ):
            raise ValueError("expected IDs must be a nonempty tuple of unique text IDs")
        candidates = {candidate.id for candidate in self.request.candidates}
        if not set(self.expected) <= candidates:
            raise ValueError("expected IDs must belong to the submitted candidates")


def case_from_dict(value: object) -> EvaluationCase:
    """Parse labels separately from the request sent to the model."""
    if not isinstance(value, Mapping) or set(value) != {"id", "request", "expected"}:
        raise ValueError("evaluation case requires exactly id, request and expected")
    identifier, expected = value["id"], value["expected"]
    if not isinstance(identifier, str) or not isinstance(expected, list):
        raise ValueError("case ID must be text and expected must be a list of IDs")
    if any(not isinstance(label, str) for label in expected):
        raise ValueError("expected IDs must be text")
    return EvaluationCase(
        identifier, request_from_dict(value["request"]), tuple(expected)
    )


@dataclass(frozen=True, slots=True)
class EvaluationRow:
    id: str
    expected: tuple[str, ...]
    status: str
    prediction: Decision | None
    correct: bool
    latency_ms: float
    error: str | None

    def to_dict(self) -> dict[str, object]:
        return {
            "id": self.id,
            "expected": list(self.expected),
            "status": self.status,
            "prediction": None
            if self.prediction is None
            else self.prediction.to_dict(),
            "correct": self.correct,
            "latency_ms": self.latency_ms,
            "error": self.error,
        }


def percentile(values: Sequence[float], fraction: float) -> float:
    """Return a linearly interpolated percentile of finite measured values."""
    if not values or not math.isfinite(fraction) or not 0 <= fraction <= 1:
        raise ValueError("nonempty values and a percentile fraction in [0, 1] required")
    if any(not math.isfinite(value) or value < 0 for value in values):
        raise ValueError("latencies must be finite and nonnegative")
    ordered = sorted(values)
    position = fraction * (len(ordered) - 1)
    lower = math.floor(position)
    upper = math.ceil(position)
    return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)


@dataclass(frozen=True, slots=True)
class EvaluationReport:
    model_id: str
    rows: tuple[EvaluationRow, ...]
    input_sha256: str

    @property
    def total(self) -> int:
        return len(self.rows)

    @property
    def successful(self) -> int:
        return sum(row.status == "ok" for row in self.rows)

    @property
    def correct(self) -> int:
        return sum(row.correct for row in self.rows)

    @property
    def failed(self) -> int:
        return self.total - self.successful

    @property
    def accuracy(self) -> float:
        return self.correct / self.total

    @property
    def coverage(self) -> float:
        return self.successful / self.total

    @property
    def latency_p50_ms(self) -> float:
        return percentile([row.latency_ms for row in self.rows], 0.50)

    @property
    def latency_p95_ms(self) -> float:
        return percentile([row.latency_ms for row in self.rows], 0.95)

    def to_dict(self) -> dict[str, object]:
        return {
            "schema_version": 1,
            "input_sha256": self.input_sha256,
            "model_id": self.model_id,
            "total": self.total,
            "successful": self.successful,
            "failed": self.failed,
            "correct": self.correct,
            "accuracy": self.accuracy,
            "coverage": self.coverage,
            "latency_p50_ms": self.latency_p50_ms,
            "latency_p95_ms": self.latency_p95_ms,
            "rows": [row.to_dict() for row in self.rows],
        }


def _input_digest(cases: tuple[EvaluationCase, ...]) -> str:
    cohort = [
        {
            "id": case.id,
            "request": {
                "query": case.request.query,
                "context": case.request.context,
                "task": case.request.task,
                "candidates": [
                    {"id": candidate.id, "text": candidate.text}
                    for candidate in case.request.candidates
                ],
            },
            "expected": list(case.expected),
        }
        for case in cases
    ]
    canonical = json.dumps(
        cohort,
        ensure_ascii=False,
        allow_nan=False,
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(canonical).hexdigest()


def evaluate(model: Model, cases: Iterable[EvaluationCase]) -> EvaluationReport:
    """Validate the complete cohort, then retain every attempted prediction.

    Latency covers every model call, including failures. The sequence may mix
    cold and warm calls; its percentiles do not establish steady-state throughput.
    Labels affect only the cohort hash and scoring, never a model request.
    """
    cohort = tuple(cases)
    if not cohort or any(not isinstance(case, EvaluationCase) for case in cohort):
        raise ValueError(
            "evaluation requires a nonempty cohort of EvaluationCase values"
        )
    if len({case.id for case in cohort}) != len(cohort):
        raise ValueError("evaluation case IDs must be unique")
    input_sha256 = _input_digest(cohort)
    model_id = model.model_id
    rows: list[EvaluationRow] = []
    for case in cohort:
        start = time.perf_counter_ns()
        try:
            prediction = model.decide(case.request)
        except Exception as error:
            latency_ms = (time.perf_counter_ns() - start) / 1_000_000
            rows.append(
                EvaluationRow(
                    case.id,
                    case.expected,
                    "error",
                    None,
                    False,
                    latency_ms,
                    f"{type(error).__name__}: {error}",
                )
            )
        else:
            latency_ms = (time.perf_counter_ns() - start) / 1_000_000
            rows.append(
                EvaluationRow(
                    case.id,
                    case.expected,
                    "ok",
                    prediction,
                    prediction.selected in case.expected,
                    latency_ms,
                    None,
                )
            )
    return EvaluationReport(model_id, tuple(rows), input_sha256)

"""Expose a loaded choice model through explicit DMBench projection recipes."""

from __future__ import annotations

from collections.abc import Callable
from typing import TYPE_CHECKING, Literal, cast

from wyat.core import Candidate, Decision, Model, Request

if TYPE_CHECKING:
    from dmbench.api import Prediction as DMBenchPrediction
    from dmbench.api import Request as DMBenchRequest

type DMBenchRecipe = Literal["dmbench-verbatim-choice-v1", "dmbench-native-choice-v1"]


def as_dmbench(
    model: Model, *, recipe: DMBenchRecipe = "dmbench-verbatim-choice-v1"
) -> Callable[[DMBenchRequest], DMBenchPrediction]:
    """Preserve choices; use public text verbatim unless native roles are selected.

    DMBench owns loading cases, labels, scoring, grouping and provenance. A
    DMBench task identifies its panel; Wyat's task identifies the choice head.
    Choiceless tasks cannot be represented by this adapter. Inference errors
    propagate to the DMBench evaluator, which retains their denominator.
    """
    batch = as_dmbench_batch(model, recipe=recipe)

    def predict(public: DMBenchRequest) -> DMBenchPrediction:
        return batch((public,))[0]

    return predict


def _request(public: DMBenchRequest, recipe: DMBenchRecipe) -> Request:
    query = public.text
    context = ""
    if recipe == "dmbench-native-choice-v1":
        if public.task != "jevbench/choice":
            raise ValueError("Wyat's native recipe requires jevbench/choice")
        from dmbench.adapters.native import native_request
        from dmbench.api import canonical_json

        state, question, _ = native_request(public)
        # native_request validates the declared schema, including this text type.
        query = cast(str, question["instructions"])
        context = state if isinstance(state, str) else canonical_json(state)
    if not public.choices:
        raise ValueError("Wyat's choice adapter requires supplied DMBench choices")
    return Request(
        query=query,
        context=context,
        candidates=tuple(
            Candidate(choice.id, choice.text) for choice in public.choices
        ),
        task="choice",
    )


def as_dmbench_batch(
    model: Model, *, recipe: DMBenchRecipe = "dmbench-verbatim-choice-v1"
) -> Callable[[tuple[DMBenchRequest, ...]], tuple[DMBenchPrediction, ...]]:
    """Expose native batching; validate the entire public chunk before inference.

    Inputs and predictions retain caller order. No concurrency, retry, loading
    or hidden menu reduction is introduced. Scalar and batch calls share the
    same public request and prediction conversions.
    """
    if recipe not in {"dmbench-verbatim-choice-v1", "dmbench-native-choice-v1"}:
        raise ValueError("Unknown DMBench choice adapter recipe")
    from dmbench.api import Prediction

    def prediction(public: DMBenchRequest, decision: Decision) -> DMBenchPrediction:
        return Prediction(
            answer=decision.selected,
            probabilities=dict(
                zip(
                    (choice.id for choice in public.choices),
                    decision.probabilities,
                    strict=True,
                )
            ),
        )

    def predict_many(
        public: tuple[DMBenchRequest, ...],
    ) -> tuple[DMBenchPrediction, ...]:
        if not public:
            return ()
        requests = tuple(_request(request, recipe) for request in public)
        decisions = model.decide_many(requests)
        return tuple(
            prediction(request, decision)
            for request, decision in zip(public, decisions, strict=True)
        )

    return predict_many

"""Strict JSON decoding shared by the CLI and HTTP boundary."""

import json
import math
from pathlib import Path
from typing import cast

type JsonValue = (
    None | bool | int | float | str | list[JsonValue] | dict[str, JsonValue]
)
type JsonObject = dict[str, JsonValue]


def _object(pairs: list[tuple[str, JsonValue]]) -> JsonObject:
    result: JsonObject = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON field: {key}")
        result[key] = value
    return result


def _constant(value: str) -> None:
    raise ValueError(f"nonfinite JSON number: {value}")


def _float(value: str) -> float:
    parsed = float(value)
    if not math.isfinite(parsed):
        raise ValueError("JSON number exceeds finite float range")
    return parsed


def decode_json(data: str | bytes) -> JsonValue:
    # json.loads is dynamically typed; the decoder only creates JSON values.
    return cast(
        JsonValue,
        json.loads(
            data,
            object_pairs_hook=_object,
            parse_constant=_constant,
            parse_float=_float,
        ),
    )


def read_object(path: Path) -> JsonObject:
    value = decode_json(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError(f"Expected a JSON object: {path.name}")
    return value
